"use client"

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  useCallback,
  useMemo,
} from "react"
import { Stat, type StatSize } from "../components/stat/stat.js"
import { cx } from "../utils/cx.js"
import { Chart, type ChartCommonProps, useStableSpec } from "./chart.js"
import type { EChartsOption } from "./echarts.js"
import { type ChartFormat, toFormatter } from "./format.js"
import {
  areaFade,
  axisParams,
  lastPointMark,
  tooltipBase,
  tooltipHtml,
} from "./option-parts.js"
import { type ChartTokens, type ChartTone, colorOf } from "./tokens.js"

export interface SparklineSpec {
  /** Oldest first. Null leaves a gap. */
  values: (number | null)[]
  /** Names each point in the tooltip, such as dates. */
  labels?: string[]
  format?: ChartFormat
  color?: ChartTone | string
  area?: boolean
  smooth?: boolean
  /** A level ruled across the line, such as last period's average. */
  reference?: number
  tooltip?: boolean
}

export const sparklineOption = (
  {
    values,
    labels,
    color,
    area = true,
    smooth = true,
    reference,
    tooltip = true,
    ...spec
  }: SparklineSpec,
  tokens: ChartTokens,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const stroke = colorOf(tokens, color)
  return {
    grid: { left: 3, right: 6, top: 6, bottom: 3 },
    tooltip: tooltip
      ? {
          ...tooltipBase(tokens),
          trigger: "axis",
          axisPointer: { type: "line", lineStyle: { color: tokens.border, width: 1 } },
          formatter: (params: unknown) => {
            const at = axisParams(params)[0]?.dataIndex ?? -1
            const value = values[at]
            if (value == null) return ""
            return tooltipHtml(labels?.[at] ?? "", [
              { name: "Value", color: stroke, value: format(value) },
            ])
          },
        }
      : { show: false },
    xAxis: {
      type: "category",
      show: false,
      boundaryGap: false,
      data: values.map((_, index) => labels?.[index] ?? String(index + 1)),
    },
    // Scaled to its own range: a sparkline carries shape, not magnitude.
    yAxis: { type: "value", show: false, scale: true },
    series: [
      {
        type: "line",
        data: values,
        color: stroke,
        smooth: smooth ? 0.35 : false,
        smoothMonotone: "x",
        showSymbol: false,
        symbol: "circle",
        symbolSize: 5,
        lineStyle: { width: 1.75, color: stroke, cap: "round", join: "round" },
        itemStyle: { color: stroke, borderColor: tokens.surface, borderWidth: 1.5 },
        ...(area ? { areaStyle: { color: areaFade(stroke), opacity: 1 } } : {}),
        ...lastPointMark(tokens, stroke, values),
        ...(reference === undefined
          ? {}
          : {
              markLine: {
                silent: true,
                symbol: "none",
                animation: false,
                label: { show: false },
                lineStyle: { color: tokens.fgFaint, type: "dashed", width: 1 },
                data: [{ yAxis: reference }],
              },
            }),
      },
    ],
  } as EChartsOption
}

export interface SparklineProps extends ChartCommonProps, SparklineSpec {}

/** A trend at the size of a word, with a hover readout. */
export const Sparkline = forwardRef<HTMLDivElement, SparklineProps>(
  (
    {
      values,
      labels,
      format,
      color,
      area,
      smooth,
      reference,
      tooltip,
      label = "Trend",
      height = 48,
      summary = true,
      empty,
      ...props
    },
    ref,
  ) => {
    const spec = useStableSpec(
      { values, labels, format, color, area, smooth, reference, tooltip },
      format,
    )
    const option = useCallback(
      (tokens: ChartTokens) => sparklineOption(spec, tokens),
      [spec],
    )
    const table = useMemo(() => {
      if (!summary) return undefined
      const print = toFormatter(spec.format)
      return {
        columns: ["Point", "Value"],
        rows: spec.values.map((value, index) => [
          spec.labels?.[index] ?? String(index + 1),
          value === null ? null : print(value),
        ]),
      }
    }, [summary, spec])
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        height={height}
        summary={table}
        empty={empty}
        data-variant="sparkline"
        {...props}
      />
    )
  },
)

Sparkline.displayName = "Sparkline"

export interface SparkGridItem {
  label: string
  value: number
  /** Change versus the previous period, in percent. */
  delta?: number
  /** For metrics where down is good. */
  invertDelta?: boolean
  /** Recent values, oldest first. */
  trend?: number[]
}

export interface SparkGridProps extends HTMLAttributes<HTMLUListElement> {
  items: SparkGridItem[]
  format?: ChartFormat
  /** Narrowest a tile may get before the grid drops a column, in px. */
  minTileWidth?: number
  size?: StatSize
  /** Context under each value, such as “vs last week”. */
  helper?: string
}

/**
 * Small multiples: one KPI tile per entity, each with its own sparkline. Plain SVG rather
 * than one canvas per tile, which would cost more than the page around it at forty tiles.
 */
export const SparkGrid = forwardRef<HTMLUListElement, SparkGridProps>(
  (
    {
      items,
      format,
      minTileWidth = 180,
      size = "sm",
      helper,
      className,
      style,
      ...props
    },
    ref,
  ) => {
    const print = toFormatter(format)
    return (
      <ul
        ref={ref}
        className={cx("kg-spark-grid", className)}
        style={{ ...style, "--_tile": `${minTileWidth}px` } as CSSProperties}
        {...props}
      >
        {items.map((item) => {
          const trend = item.trend?.filter(Number.isFinite) ?? []
          const first = trend[0]
          const last = trend[trend.length - 1]
          return (
            <li key={item.label} className="kg-spark-grid__tile">
              <Stat
                label={item.label}
                value={print(item.value)}
                delta={item.delta}
                invertDelta={item.invertDelta}
                helper={helper}
                trend={item.trend}
                trendLabel={
                  first !== undefined && last !== undefined && trend.length > 1
                    ? `${item.label} trend, ${print(first)} to ${print(last)}`
                    : undefined
                }
                size={size}
              />
            </li>
          )
        })}
      </ul>
    )
  },
)

SparkGrid.displayName = "SparkGrid"

charts/spec-chart.tsx:
"use client"

import {
  type ForwardRefExoticComponent,
  forwardRef,
  type RefAttributes,
  useCallback,
  useMemo,
} from "react"
import {
  Chart,
  type ChartCommonProps,
  type ChartSummary,
  useStableSpec,
} from "./chart.js"
import type { EChartsOption } from "./echarts.js"
import type { ChartTokens } from "./tokens.js"

export interface SpecChartConfig<S extends object> {
  name: string
  /** Every spec prop; anything else is spread onto the root element. */
  keys: readonly (keyof S & string)[]
  option: (spec: S, tokens: ChartTokens, width: number) => EChartsOption
  table: (spec: S) => ChartSummary
  isEmpty: (spec: S) => boolean
  label: string
  height?: number | ((spec: S) => number)
}

export type SpecChartComponent<S extends object> = ForwardRefExoticComponent<
  ChartCommonProps & S & RefAttributes<HTMLDivElement>
>

/**
 * One data-first chart from its pure option builder: splits spec props from DOM props, keeps
 * the spec stable across equal re-renders, and adds the hidden table and the empty note.
 */
export const specChart = <S extends object>(
  config: SpecChartConfig<S>,
): SpecChartComponent<S> => {
  const Component = forwardRef<HTMLDivElement, ChartCommonProps & S>((props, ref) => {
    const {
      label = config.label,
      height,
      summary = true,
      empty = "No data to plot",
      ...rest
    } = props as ChartCommonProps & Record<string, unknown>
    const picked: Record<string, unknown> = {}
    const dom: Record<string, unknown> = {}
    for (const [key, value] of Object.entries(rest)) {
      if ((config.keys as readonly string[]).includes(key)) picked[key] = value
      else dom[key] = value
    }
    // Fixed length, so the memo's dependency list never changes size between renders.
    const functions = config.keys.map((key) =>
      typeof picked[key] === "function" ? picked[key] : undefined,
    )
    const spec = useStableSpec(picked as S, ...functions)
    const option = useCallback(
      (tokens: ChartTokens, width: number) => config.option(spec, tokens, width),
      [spec],
    )
    const table = useMemo(
      () => (summary ? config.table(spec) : undefined),
      [summary, spec],
    )
    const isEmpty = config.isEmpty(spec)
    const fitted =
      height ??
      (typeof config.height === "function" ? config.height(spec) : config.height)
    return (
      <Chart
        ref={ref}
        option={option}
        label={label}
        height={fitted}
        summary={isEmpty ? undefined : table}
        empty={isEmpty ? empty : undefined}
        {...dom}
      />
    )
  })
  Component.displayName = config.name
  return Component as SpecChartComponent<S>
}

/** `+12`, `-4`: direction in the text, so it never rests on color alone. */
export const signedFormat =
  (format: (value: number) => string) =>
  (value: number): string =>
    `${value > 0 ? "+" : ""}${format(value)}`

/** The minimal slice of the ECharts custom-series API these charts draw with. */
export interface CustomApi {
  coord: (point: number[]) => number[]
  size: (span: number[]) => number[]
}

export interface CustomParams {
  dataIndex: number
  coordSys: { x: number; y: number; width: number; height: number }
}

export const median = (values: readonly number[]): number => {
  const sorted = [...values].sort((a, b) => a - b)
  const middle = Math.floor(sorted.length / 2)
  if (sorted.length === 0) return 0
  return sorted.length % 2
    ? (sorted[middle] ?? 0)
    : ((sorted[middle - 1] ?? 0) + (sorted[middle] ?? 0)) / 2
}

const channelsOf = (color: string): number[] | null => {
  const value = color.trim()
  const hex = /^#([0-9a-f]{6})$/i.exec(value)?.[1]
  if (hex)
    return [0, 2, 4].map((at) => Number.parseInt(hex.slice(at, at + 2), 16)).concat(1)
  const parts = /^rgba?\(([^)]+)\)$/i
    .exec(value)?.[1]
    ?.split(/[\s,/]+/)
    .filter(Boolean)
    .map(Number)
  if (!parts || parts.length < 3 || parts.some(Number.isNaN)) return null
  return [parts[0] ?? 0, parts[1] ?? 0, parts[2] ?? 0, parts[3] ?? 1]
}

const luminance = ([r = 0, g = 0, b = 0]: number[]): number => {
  const linear = (value: number) => {
    const c = value / 255
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4
  }
  return 0.2126 * linear(r) + 0.7152 * linear(g) + 0.0722 * linear(b)
}

/** The theme's ink or its surface, whichever reads better on `fill` laid over the surface. */
export const inkOn = (tokens: ChartTokens, fill: string): string => {
  const top = channelsOf(fill)
  const paper = channelsOf(tokens.surface)
  const ink = channelsOf(tokens.fg)
  if (!top || !paper || !ink) return tokens.fg
  const alpha = top[3] ?? 1
  const ground = luminance(
    top.slice(0, 3).map((c, i) => c * alpha + (paper[i] ?? 0) * (1 - alpha)),
  )
  const contrast = (other: number) =>
    (Math.max(other, ground) + 0.05) / (Math.min(other, ground) + 0.05)
  return contrast(luminance(ink)) >= contrast(luminance(paper))
    ? tokens.fg
    : tokens.surface
}

charts/stacked-percent-bar.tsx:
"use client"

import type { ChartCommonProps } from "./chart.js"
import type { EChartsOption } from "./echarts.js"
import { type ChartFormat, formatPercent, toFormatter } from "./format.js"
import {
  axisParams,
  type ChartLegend,
  type ChartRow,
  type ChartSeriesInput,
  categoryAxis,
  legendOption,
  legendRoom,
  numberAt,
  resolveSeries,
  seriesEntries,
  tooltipBase,
  tooltipHtml,
  valueAxis,
} from "./option-parts.js"
import { inkOn, specChart } from "./spec-chart.js"
import { type ChartTokens, withAlpha } from "./tokens.js"

export interface StackedPercentBarSpec {
  data: ChartRow[]
  xKey: string
  series?: ChartSeriesInput[]
  /** How raw values print in the tooltip next to their share. */
  format?: ChartFormat
  orientation?: "horizontal" | "vertical"
  /** Prints each segment's share inside it when it is wide enough. On by default. */
  labels?: boolean
  legend?: ChartLegend
}

/** Each row's series as shares of that row's total, 0 to 1. */
export const percentRows = (
  data: readonly ChartRow[],
  keys: readonly string[],
): number[][] =>
  data.map((row) => {
    const values = keys.map((key) => Math.max(numberAt(row, key) ?? 0, 0))
    const total = values.reduce((sum, value) => sum + value, 0)
    return values.map((value) => (total > 0 ? value / total : 0))
  })

export const stackedPercentBarOption = (
  {
    data,
    xKey,
    orientation = "horizontal",
    labels = true,
    ...spec
  }: StackedPercentBarSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const series = resolveSeries(tokens, data, xKey, spec.series)
  const shares = percentRows(
    data,
    series.map((entry) => entry.key),
  )
  const legend = legendOption(tokens, spec.legend ?? "top", series.length)
  const sideways = orientation === "horizontal"
  const names = data.map((row) => String(row[xKey] ?? ""))
  const category = {
    ...categoryAxis(tokens, names),
    ...(sideways ? { inverse: true, axisLine: { show: false } } : {}),
  }
  const value = {
    ...valueAxis(tokens, (share) => formatPercent(share, 0), width),
    min: 0,
    max: 1,
    interval: 0.25,
  }

  return {
    legend: { ...legend, data: series.map((entry) => entry.label) },
    grid: { left: 4, right: 16, ...legendRoom(legend), containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: {
        type: "shadow",
        shadowStyle: { color: withAlpha(tokens.fgFaint, 0.08) },
      },
      formatter: (params: unknown) => {
        const index = axisParams(params)[0]?.dataIndex ?? -1
        const row = data[index]
        if (!row) return ""
        return tooltipHtml(
          names[index] ?? "",
          series.map((entry, at) => {
            const raw = numberAt(row, entry.key)
            return {
              name: entry.label,
              color: entry.color,
              value: `${formatPercent(shares[index]?.[at] ?? 0)}${raw === null ? "" : `  ${format(raw)}`}`,
            }
          }),
        )
      },
    },
    xAxis: sideways ? value : category,
    yAxis: sideways ? category : value,
    series: series.map((entry, at) => ({
      type: "bar",
      name: entry.label,
      stack: "share",
      barMaxWidth: 28,
      color: entry.color,
      emphasis: { focus: "series" },
      blur: { itemStyle: { opacity: 0.3 } },
      itemStyle: { borderColor: tokens.surface, borderWidth: 1 },
      label: {
        show: labels,
        color: inkOn(tokens, entry.color),
        fontFamily: tokens.fontMono,
        fontSize: 10,
        formatter: (params: { value: number }) =>
          params.value >= 0.08 ? formatPercent(params.value, 0) : "",
      },
      data: shares.map((row) => row[at] ?? 0),
    })),
  } as EChartsOption
}

export interface StackedPercentBarProps extends ChartCommonProps, StackedPercentBarSpec {}

/** Composition across rows: every bar runs to 100%, so mix compares where totals differ. */
export const StackedPercentBar = specChart<StackedPercentBarSpec>({
  name: "StackedPercentBar",
  keys: ["data", "xKey", "series", "format", "orientation", "labels", "legend"],
  option: stackedPercentBarOption,
  table: (spec) => {
    const entries = seriesEntries(spec.data, spec.xKey, spec.series)
    const shares = percentRows(
      spec.data,
      entries.map((entry) => entry.key),
    )
    return {
      columns: [spec.xKey, ...entries.map((entry) => entry.label ?? entry.key)],
      rows: spec.data.map((row, index) => [
        String(row[spec.xKey] ?? ""),
        ...entries.map((_, at) => formatPercent(shares[index]?.[at] ?? 0)),
      ]),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "100% stacked bar chart",
  height: (spec) =>
    spec.orientation === "vertical" ? 300 : Math.max(spec.data.length * 40 + 60, 160),
})

charts/theme-river-chart.tsx:
"use client"

import type { ChartCommonProps } from "./chart.js"
import type { EChartsOption } from "./echarts.js"
import { type ChartFormat, toFormatter } from "./format.js"
import {
  type ChartLegend,
  type ChartRow,
  type ChartSeriesInput,
  legendOption,
  numberAt,
  resolveSeries,
  seriesEntries,
  tableOf,
  tooltipBase,
  tooltipHtml,
} from "./option-parts.js"
import { specChart } from "./spec-chart.js"
import type { ChartTokens } from "./tokens.js"

export interface ThemeRiverChartSpec {
  /** One row per moment. `xKey` holds an ISO date, a timestamp, or a plain number. */
  data: ChartRow[]
  xKey: string
  series?: ChartSeriesInput[]
  format?: ChartFormat
  legend?: ChartLegend
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

const isTime = (data: readonly ChartRow[], xKey: string) =>
  typeof data[0]?.[xKey] === "string"

const dateLabel = (value: number) => {
  const date = new Date(value)
  return `${MONTHS[date.getUTCMonth()] ?? ""} ${date.getUTCDate()}`
}

export const themeRiverChartOption = (
  { data, xKey, ...spec }: ThemeRiverChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const series = resolveSeries(tokens, data, xKey, spec.series)
  const legend = legendOption(tokens, spec.legend, series.length)
  const time = isTime(data, xKey)
  const below = legend.show && legend.bottom !== undefined
  const stamp = (row: ChartRow) => {
    const raw = row[xKey]
    return time ? Date.parse(String(raw)) : Number(raw)
  }
  const tickText = (value: number) => (time ? dateLabel(value) : format(value))
  const most = width > 0 && width < 420 ? 3 : 6
  // A time axis adds its own month-boundary ticks that crowd the weekly ones, so labels sit on
  // evenly spaced data points instead.
  const stamps = time ? data.map(stamp).filter(Number.isFinite) : []
  const every = Math.max(1, Math.ceil(stamps.length / most))
  const ticks = stamps.filter((_, index) => index % every === 0)

  return {
    color: series.map((entry) => entry.color),
    legend: { ...legend, data: series.map((entry) => entry.label) },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "axis",
      axisPointer: { type: "line", lineStyle: { color: tokens.border } },
      formatter: (params: unknown) => {
        const hits = Array.isArray(params) ? (params as { value: unknown[] }[]) : []
        const at = Number(hits[0]?.value?.[0])
        const row = data.find((entry) => stamp(entry) === at) ?? data[0]
        if (!row) return ""
        return tooltipHtml(
          time ? String(row[xKey] ?? "") : tickText(at),
          series.map((entry) => ({
            name: entry.label,
            color: entry.color,
            value: format(numberAt(row, entry.key) ?? 0),
          })),
        )
      },
    },
    singleAxis: {
      type: time ? "time" : "value",
      top: legend.show && !below ? 40 : 12,
      bottom: below ? 52 : 28,
      left: 8,
      right: 8,
      min: "dataMin",
      max: "dataMax",
      splitNumber: most,
      axisTick: { show: false, ...(time ? { customValues: ticks } : {}) },
      axisLine: { lineStyle: { color: tokens.border } },
      axisLabel: {
        ...(time ? { customValues: ticks } : {}),
        alignMinLabel: "left",
        alignMaxLabel: "right",
        color: tokens.fgFaint,
        fontFamily: tokens.fontMono,
        fontSize: 11,
        hideOverlap: true,
        formatter: (value: number) => tickText(value),
      },
      splitLine: { show: true, lineStyle: { color: tokens.grid, type: "dashed" } },
    },
    series: [
      {
        type: "themeRiver",
        boundaryGap: ["8%", "8%"],
        emphasis: { focus: "self" },
        blur: { itemStyle: { opacity: 0.25 } },
        itemStyle: { borderColor: tokens.surface, borderWidth: 0.5 },
        label: { show: false },
        data: data.flatMap((row) =>
          series.map((entry) => [stamp(row), numberAt(row, entry.key) ?? 0, entry.label]),
        ),
      },
    ],
  } as EChartsOption
}

export interface ThemeRiverChartProps extends ChartCommonProps, ThemeRiverChartSpec {}

/** A streamgraph: stacked flows around a centre line, so each theme's swell and fade reads as shape. */
export const ThemeRiverChart = specChart<ThemeRiverChartSpec>({
  name: "ThemeRiverChart",
  keys: ["data", "xKey", "series", "format", "legend"],
  option: themeRiverChartOption,
  table: (spec) =>
    tableOf(
      spec.data,
      spec.xKey,
      seriesEntries(spec.data, spec.xKey, spec.series),
      toFormatter(spec.format),
    ),
  isEmpty: (spec) => spec.data.length === 0,
  label: "Streamgraph",
  height: 320,
})

charts/tokens.ts:
export type ChartTone = "accent" | "success" | "warning" | "danger" | "info" | "neutral"

export interface ChartTokens {
  fg: string
  fgMuted: string
  fgFaint: string
  surface: string
  border: string
  grid: string
  accent: string
  success: string
  warning: string
  danger: string
  info: string
  /** Series colors in order: the accent first, then graphite and accent tints. */
  palette: readonly string[]
  font: string
  fontMono: string
  /** Resolves any CSS color, `var()` included, in the chart's own scope. */
  resolve: (color: string) => string
}

// Each value is a `var()` with an Orbit default, so charts render sensibly even without the
// stylesheet. `--kg-chart-*` lets a theme or scope repaint charts without touching the accent.
const RECIPE = {
  fg: "var(--kg-fg, #1b1d22)",
  fgMuted: "var(--kg-fg-muted, #5b5f69)",
  fgFaint: "var(--kg-fg-faint, #81858f)",
  surface: "var(--kg-chart-surface, var(--kg-surface, #fcfcfd))",
  border: "var(--kg-border, #dfe1e5)",
  grid: "var(--kg-chart-grid, color-mix(in oklab, var(--kg-border, #dfe1e5) 75%, transparent))",
  accent: "var(--kg-accent, #f28a2e)",
  success: "var(--kg-success, #2f8a50)",
  warning: "var(--kg-warning, #d79a1f)",
  danger: "var(--kg-danger, #c8392f)",
  info: "var(--kg-info, #2f73b5)",
} as const

const PALETTE = [
  "var(--kg-accent, #f28a2e)",
  "color-mix(in oklab, var(--kg-fg, #1b1d22) 58%, var(--kg-bg, #f8f9fa))",
  "color-mix(in oklab, var(--kg-accent, #f28a2e) 50%, var(--_kg-chart-tint, var(--kg-bg, #f8f9fa)))",
  "color-mix(in oklab, var(--kg-fg, #1b1d22) var(--_kg-chart-quiet, 28%), var(--kg-bg, #f8f9fa))",
  "color-mix(in oklab, var(--kg-accent, #f28a2e), var(--kg-fg, #1b1d22) 45%)",
  "color-mix(in oklab, var(--kg-fg, #1b1d22) 82%, var(--kg-bg, #f8f9fa))",
].map((fallback, index) => `var(--kg-chart-${index + 1}, ${fallback})`)

type Key = keyof typeof RECIPE

/** Orbit light theme, used on the server, in tests and wherever styles cannot be read. */
export const fallbackChartTokens: ChartTokens = {
  fg: "#1b1d22",
  fgMuted: "#5b5f69",
  fgFaint: "#81858f",
  surface: "#fcfcfd",
  border: "#dfe1e5",
  grid: "rgba(223, 225, 229, 0.75)",
  accent: "#f28a2e",
  success: "#2f8a50",
  warning: "#d79a1f",
  danger: "#c8392f",
  info: "#2f73b5",
  palette: ["#f28a2e", "#7d808a", "#f6c08f", "#c3c5cb", "#91562a", "#3d4048"],
  font: "ui-sans-serif, system-ui, sans-serif",
  fontMono: "ui-monospace, SFMono-Regular, Menlo, monospace",
  resolve: (color) => color,
}

const SENTINEL = "#010203"
let context: CanvasRenderingContext2D | null | undefined

// Computed styles keep the authored color space (oklch, color-mix) and ECharts' own parser
// turns those black, so one pixel is rasterised to get plain rgb().
const toRgb = (value: string): string => {
  if (!value || /^(#|rgba?\()/i.test(value)) return value
  if (context === undefined) {
    try {
      const canvas = document.createElement("canvas")
      canvas.width = 1
      canvas.height = 1
      context = canvas.getContext("2d", { willReadFrequently: true })
    } catch {
      context = null
    }
  }
  if (!context) return value
  context.clearRect(0, 0, 1, 1)
  context.fillStyle = SENTINEL
  context.fillStyle = value
  if (context.fillStyle === SENTINEL) return value
  context.fillRect(0, 0, 1, 1)
  const [red = 0, green = 0, blue = 0, alpha = 255] = context.getImageData(
    0,
    0,
    1,
    1,
  ).data
  return alpha === 255
    ? `rgb(${red}, ${green}, ${blue})`
    : `rgba(${red}, ${green}, ${blue}, ${(alpha / 255).toFixed(3)})`
}

// One probe per color, appended together, so the whole theme costs a single style recalc.
const resolveAll = (scope: HTMLElement, colors: readonly string[]): string[] => {
  const probes = colors.map((color) => {
    const probe = document.createElement("span")
    probe.style.display = "none"
    probe.style.color = color
    return probe
  })
  scope.append(...probes)
  // An engine that cannot resolve custom properties hands back the var() itself.
  const resolved = probes.map((probe) => {
    const computed = getComputedStyle(probe).color
    return computed.includes("var(") ? "" : toRgb(computed)
  })
  for (const probe of probes) probe.remove()
  return resolved
}

/** The live theme at `scope`, resolved to concrete colors: canvas cannot paint `var()`. */
export const readChartTokens = (scope: HTMLElement): ChartTokens => {
  const keys = Object.keys(RECIPE) as Key[]
  const values = resolveAll(scope, [...keys.map((key) => RECIPE[key]), ...PALETTE])
  const pick = (index: number, fallback: string) => values[index] || fallback

  const tokens = { ...fallbackChartTokens }
  keys.forEach((key, index) => {
    tokens[key] = pick(index, fallbackChartTokens[key])
  })
  tokens.palette = PALETTE.map((_, index) =>
    pick(keys.length + index, fallbackChartTokens.palette[index] ?? tokens.accent),
  )

  const styles = getComputedStyle(scope)
  tokens.font = styles.fontFamily || fallbackChartTokens.font
  tokens.fontMono =
    styles.getPropertyValue("--kg-font-mono").trim() || fallbackChartTokens.fontMono
  tokens.resolve = (color) => resolveAll(scope, [color])[0] || color
  return tokens
}

/** A comparable fingerprint, so a mutation that changes no color does not replay the chart. */
export const tokenSignature = (tokens: ChartTokens): string =>
  [
    ...(Object.keys(RECIPE) as Key[]).map((key) => tokens[key]),
    ...tokens.palette,
    tokens.font,
    tokens.fontMono,
  ].join("|")

const HEX = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i
const FUNCTIONAL = /^rgba?\(([^)]+)\)$/i

/** Re-alphas a hex or rgb() color; anything else is returned untouched. */
export const withAlpha = (color: string, alpha: number): string => {
  const value = color.trim()
  const hex = HEX.exec(value)?.[1]
  if (hex) {
    const full = hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex
    const channel = (at: number) => Number.parseInt(full.slice(at * 2, at * 2 + 2), 16)
    return `rgba(${channel(0)}, ${channel(1)}, ${channel(2)}, ${alpha})`
  }
  const channels = FUNCTIONAL.exec(value)?.[1]
    ?.split(/[\s,/]+/)
    .filter(Boolean)
  if (channels && channels.length >= 3)
    return `rgba(${channels.slice(0, 3).join(", ")}, ${alpha})`
  return value
}

const TONES: Record<ChartTone, (tokens: ChartTokens) => string> = {
  accent: (t) => t.accent,
  success: (t) => t.success,
  warning: (t) => t.warning,
  danger: (t) => t.danger,
  info: (t) => t.info,
  neutral: (t) => t.fgFaint,
}

const isTone = (value: string): value is ChartTone => value in TONES

/** A tone name, any CSS color, or the palette entry for `index` when neither is given. */
export const colorOf = (
  tokens: ChartTokens,
  color: ChartTone | string | undefined,
  index = 0,
): string => {
  if (color) return isTone(color) ? TONES[color](tokens) : tokens.resolve(color)
  return tokens.palette[index % tokens.palette.length] ?? tokens.accent
}

charts/tree-chart.tsx:
"use client"

import type { ChartCommonProps } from "./chart.js"
import type { EChartsOption } from "./echarts.js"
import { type ChartFormat, toFormatter } from "./format.js"
import { tooltipBase, tooltipHtml } from "./option-parts.js"
import { specChart } from "./spec-chart.js"
import type { ChartTokens } from "./tokens.js"

export interface TreeChartNode {
  label: string
  value?: number
  children?: TreeChartNode[]
}

export interface TreeChartSpec {
  data: TreeChartNode
  format?: ChartFormat
  /** `horizontal` grows left to right, `vertical` top to bottom, `radial` outward from the centre. */
  orient?: "horizontal" | "vertical" | "radial"
  /** Levels open on first render; deeper branches open on click. All open by default. */
  depth?: number
}

interface TreeItem {
  name: string
  value?: number
  children?: TreeItem[]
}

const toItem = (node: TreeChartNode): TreeItem => ({
  name: node.label,
  ...(node.value === undefined ? {} : { value: node.value }),
  ...(node.children?.length ? { children: node.children.map(toItem) } : {}),
})

/** Every node with its depth and parent, top-down, for the hidden table. */
export const treeRows = (
  node: TreeChartNode,
  parent = "",
  depth = 0,
): { label: string; parent: string; depth: number; value?: number }[] => [
  { label: node.label, parent, depth, value: node.value },
  ...(node.children ?? []).flatMap((child) => treeRows(child, node.label, depth + 1)),
]

const leafCount = (node: TreeChartNode): number =>
  node.children?.length ? node.children.reduce((sum, child) => sum + leafCount(child), 0) : 1

export const treeChartOption = (
  { data, orient = "horizontal", depth, ...spec }: TreeChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const radial = orient === "radial"
  const vertical = orient === "vertical"
  const narrow = width > 0 && width < 520
  const text = { color: tokens.fgMuted, fontFamily: tokens.font, fontSize: 11 }

  return {
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const hit = params as { name: string; value?: number }
        return tooltipHtml(
          hit.name,
          typeof hit.value === "number" ? [{ name: "Value", value: format(hit.value) }] : [],
        )
      },
    },
    series: [
      {
        type: "tree",
        data: [toItem(data)],
        layout: radial ? "radial" : "orthogonal",
        orient: vertical ? "TB" : "LR",
        top: vertical ? 24 : 12,
        bottom: vertical ? 48 : 12,
        left: radial ? "12%" : vertical ? 12 : narrow ? 60 : 96,
        right: radial ? "12%" : vertical ? 12 : narrow ? 80 : 128,
        initialTreeDepth: depth ?? -1,
        expandAndCollapse: true,
        roam: false,
        symbol: "circle",
        symbolSize: 8,
        edgeShape: radial ? "curve" : "polyline",
        edgeForkPosition: "50%",
        itemStyle: { color: tokens.accent, borderColor: tokens.surface, borderWidth: 1.5 },
        lineStyle: { color: tokens.border, width: 1.25, curveness: 0.5 },
        emphasis: { focus: "relative" },
        blur: { itemStyle: { opacity: 0.3 }, lineStyle: { opacity: 0.2 } },
        label: {
          ...text,
          color: tokens.fg,
          position: vertical ? "top" : "left",
          verticalAlign: "middle",
          align: vertical ? "center" : "right",
          distance: 6,
          ...(vertical ? { rotate: 0 } : {}),
        },
        leaves: {
          label: {
            ...text,
            position: vertical ? "bottom" : "right",
            align: vertical ? "center" : "left",
            ...(vertical && leafCount(data) > 8 ? { rotate: -45, align: "left" } : {}),
          },
          itemStyle: {
            color: tokens.surface,
            borderColor: tokens.accent,
            borderWidth: 1.5,
          },
        },
        animationDurationUpdate: 420,
      },
    ],
  } as EChartsOption
}

export interface TreeChartProps extends ChartCommonProps, TreeChartSpec {}

/** A hierarchy as a tidy tree: parents filled, leaves hollow, branches collapse on click. */
export const TreeChart = specChart<TreeChartSpec>({
  name: "TreeChart",
  keys: ["data", "format", "orient", "depth"],
  option: treeChartOption,
  table: (spec) => {
    const print = toFormatter(spec.format)
    return {
      columns: ["Node", "Parent", "Level", "Value"],
      rows: treeRows(spec.data).map((row) => [
        row.label,
        row.parent || null,
        row.depth,
        row.value === undefined ? null : print(row.value),
      ]),
    }
  },
  isEmpty: (spec) => !spec.data?.label,
  label: "Tree chart",
  height: (spec) =>
    spec.orient === "horizontal" || spec.orient === undefined
      ? Math.max(Math.min(leafCount(spec.data) * 26 + 40, 640), 220)
      : 400,
})

charts/waffle-chart.tsx:
"use client"

import type { ChartCommonProps } from "./chart.js"
import type { EChartsOption } from "./echarts.js"
import { type ChartFormat, formatPercent, toFormatter } from "./format.js"
import {
  type ChartDatum,
  legendOption,
  tooltipBase,
  tooltipHtml,
} from "./option-parts.js"
import { specChart } from "./spec-chart.js"
import { type ChartTokens, colorOf, withAlpha } from "./tokens.js"

export interface WaffleChartSpec {
  data: ChartDatum[]
  format?: ChartFormat
  /** Cells per row. */
  columns?: number
  /** Rows of cells; `columns × rows` cells stand for the whole. */
  rows?: number
  /** Rounded cells, from square (0) to dots (1). */
  roundness?: number
  /** Counts toward the whole beyond the data; the leftover cells stay empty. */
  total?: number
}

interface WaffleApi {
  value: (dimension: number) => number
  getWidth: () => number
  getHeight: () => number
}

/** Cells per datum by largest remainder, so the counts always add up to the grid. */
export const waffleCells = (
  data: readonly ChartDatum[],
  cells: number,
  total?: number,
): number[] => {
  const sum = data.reduce((acc, datum) => acc + Math.max(datum.value, 0), 0)
  const whole = Math.max(total ?? sum, sum)
  if (whole <= 0) return data.map(() => 0)
  const exact = data.map((datum) => (Math.max(datum.value, 0) / whole) * cells)
  const counts = exact.map(Math.floor)
  const target = Math.round((sum / whole) * cells)
  let left = target - counts.reduce((acc, count) => acc + count, 0)
  const order = exact
    .map((value, index) => ({ index, rest: value - Math.floor(value) }))
    .sort((a, b) => b.rest - a.rest)
  for (const { index } of order) {
    if (left <= 0) break
    counts[index] = (counts[index] ?? 0) + 1
    left -= 1
  }
  return counts
}

export const waffleChartOption = (
  { data, columns = 10, rows = 10, roundness = 0.3, total, ...spec }: WaffleChartSpec,
  tokens: ChartTokens,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const cells = columns * rows
  const counts = waffleCells(data, cells, total)
  const sum = Math.max(
    total ?? 0,
    data.reduce((acc, datum) => acc + Math.max(datum.value, 0), 0),
  )
  const colors = data.map((datum, index) => colorOf(tokens, datum.color, index))
  const legend = legendOption(tokens, "bottom", data.length)
  const starts = counts.map((_, index) =>
    counts.slice(0, index).reduce((acc, count) => acc + count, 0),
  )
  const filled = counts.reduce((acc, count) => acc + count, 0)

  const cell = (index: number, api: WaffleApi, fill: string) => {
    const room = 72
    const width = api.getWidth()
    const height = api.getHeight() - room
    const gap = 3
    const side = Math.max(
      Math.min((width - gap * (columns - 1)) / columns, (height - gap * (rows - 1)) / rows),
      2,
    )
    const gridWidth = side * columns + gap * (columns - 1)
    const left = (width - gridWidth) / 2
    const column = index % columns
    const row = Math.floor(index / columns)
    return {
      type: "rect",
      shape: {
        x: left + column * (side + gap),
        y: 4 + row * (side + gap),
        width: side,
        height: side,
        r: (side / 2) * Math.min(Math.max(roundness, 0), 1),
      },
      style: { fill },
    }
  }

  const share = (index: number) => (sum > 0 ? (data[index]?.value ?? 0) / sum : 0)

  return {
    legend: {
      ...legend,
      // Plain wraps onto a second line; a scrolling legend would hide the last share.
      type: "plain",
      left: "center",
      icon: "roundRect",
      data: data.map((datum) => datum.label),
      formatter: (name: string) => {
        const index = data.findIndex((datum) => datum.label === name)
        return `${name}  ${formatPercent(share(index), 0)}`
      },
    },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const index = (params as { seriesIndex: number }).seriesIndex
        const datum = data[index]
        return datum
          ? tooltipHtml(datum.label, [
              { name: "Value", color: colors[index], value: format(datum.value) },
              { name: "Share", value: formatPercent(share(index)) },
            ])
          : ""
      },
    },
    series: [
      ...data.map((datum, index) => ({
        type: "custom",
        name: datum.label,
        coordinateSystem: "none",
        color: colors[index],
        emphasis: { focus: "series" },
        blur: { itemStyle: { opacity: 0.25 } },
        data: Array.from({ length: counts[index] ?? 0 }, (_, at) => (starts[index] ?? 0) + at),
        renderItem: (_params: unknown, api: WaffleApi) =>
          cell(api.value(0), api, colors[index] ?? tokens.accent),
      })),
      {
        type: "custom",
        name: "Remaining",
        coordinateSystem: "none",
        silent: true,
        tooltip: { show: false },
        data: Array.from({ length: cells - filled }, (_, at) => filled + at),
        renderItem: (_params: unknown, api: WaffleApi) =>
          cell(api.value(0), api, withAlpha(tokens.fgFaint, 0.14)),
      },
    ],
  } as EChartsOption
}

export interface WaffleChartProps extends ChartCommonProps, WaffleChartSpec {}

/** Parts of a whole as a grid of cells, each one a fixed share: easier to count than a pie. */
export const WaffleChart = specChart<WaffleChartSpec>({
  name: "WaffleChart",
  keys: ["data", "format", "columns", "rows", "roundness", "total"],
  option: (spec, tokens) => waffleChartOption(spec, tokens),
  table: (spec) => {
    const print = toFormatter(spec.format)
    const sum = Math.max(
      spec.total ?? 0,
      spec.data.reduce((acc, datum) => acc + Math.max(datum.value, 0), 0),
    )
    return {
      columns: ["Label", "Value", "Share"],
      rows: spec.data.map((datum) => [
        datum.label,
        print(datum.value),
        formatPercent(sum > 0 ? datum.value / sum : 0),
      ]),
    }
  },
  isEmpty: (spec) => spec.data.length === 0,
  label: "Waffle chart",
  height: 320,
})

charts/waterfall-chart.tsx:
"use client"

import type { ChartCommonProps, ChartSummary } from "./chart.js"
import type { EChartsOption } from "./echarts.js"
import { type ChartFormat, toFormatter } from "./format.js"
import { categoryAxis, tooltipBase, tooltipHtml, valueAxis } from "./option-parts.js"
import {
  type CustomApi,
  type CustomParams,
  signedFormat,
  specChart,
} from "./spec-chart.js"
import { type ChartTokens, withAlpha } from "./tokens.js"

/** `total` is a level, not a change: the start, a subtotal or the end. */
export type WaterfallChartKind = "delta" | "total"

export interface WaterfallChartStep {
  label: string
  /** A change for a delta. For a total, the level; omitted, the running sum so far. */
  value?: number
  kind?: WaterfallChartKind
}

export interface WaterfallChartSpec {
  data: WaterfallChartStep[]
  format?: ChartFormat
  /** For measures where a fall is good, such as cost. */
  invert?: boolean
  /** Prints each change above its bar. */
  values?: boolean
}

export interface WaterfallChartBar {
  label: string
  kind: WaterfallChartKind
  /** The signed change, or the level for a total. */
  value: number
  low: number
  high: number
  /** The running level after this step. */
  level: number
}

/** Where each bar floats: deltas hang off the running sum, totals stand on zero. */
export const waterfallBars = (
  steps: readonly WaterfallChartStep[],
): WaterfallChartBar[] => {
  let running = 0
  return steps.map((step) => {
    const kind = step.kind ?? "delta"
    if (kind === "total") {
      running = step.value ?? running
      return {
        label: step.label,
        kind,
        value: running,
        low: Math.min(0, running),
        high: Math.max(0, running),
        level: running,
      }
    }
    const change = step.value ?? 0
    const before = running
    running += change
    return {
      label: step.label,
      kind,
      value: change,
      low: Math.min(before, running),
      high: Math.max(before, running),
      level: running,
    }
  })
}

export const waterfallChartOption = (
  { data, invert = false, values = true, ...spec }: WaterfallChartSpec,
  tokens: ChartTokens,
  width = 0,
): EChartsOption => {
  const format = toFormatter(spec.format)
  const signed = signedFormat(format)
  const bars = waterfallBars(data)
  const last = bars.length - 1
  const slot = width > 0 ? width / Math.max(bars.length, 1) : 96
  const cramped = slot < 56
  const colorOf = (bar: WaterfallChartBar, index: number) =>
    bar.kind === "total"
      ? index === last
        ? tokens.accent
        : (tokens.palette[1] ?? tokens.fgMuted)
      : bar.value >= 0 !== invert
        ? tokens.success
        : tokens.danger
  const caption = (bar: WaterfallChartBar) =>
    bar.kind === "total" ? format(bar.value) : signed(bar.value)

  return {
    grid: { left: 4, right: 8, top: values ? 28 : 12, bottom: 4, containLabel: true },
    tooltip: {
      ...tooltipBase(tokens),
      trigger: "item",
      formatter: (params: unknown) => {
        const bar = bars[(params as { dataIndex: number }).dataIndex]
        if (!bar) return ""
        return tooltipHtml(
          bar.label,
          bar.kind === "total"
            ? [{ name: "Level", value: format(bar.level) }]
            : [
                { name: "Change", color: colorOf(bar, -1), value: signed(bar.value) },
                { name: "Level after", value: format(bar.level) },
              ],
        )
      },
    },
    xAxis: {
      ...categoryAxis(
        tokens,
        bars.map((bar) => bar.label),
      ),
      axisLabel: {
        ...categoryAxis(tokens, []).axisLabel,
        interval: 0,
        hideOverlap: false,
        rotate: cramped ? 40 : 0,
        width: cramped ? 72 : Math.max(slot - 8, 44),
        overflow: "truncate",
      },
    },
    yAxis: valueAxis(tokens, format, width),
    series: [
      {
        type: "custom",
        name: "Steps",
        encode: { x: 0, y: [1, 2] },
        data: bars.map((bar, index) => [index, bar.low, bar.high]),
        animationDelay: (index: number) => index * 40,
        renderItem: (params: CustomParams, api: CustomApi) => {
          const index = params.dataIndex
          const bar = bars[index]
          if (!bar) return null
          const band = api.size([1, 0])[0] ?? 0
          const thick = Math.min(44, band * 0.62)
          const [x = 0, bottom = 0] = api.coord([index, bar.low])
          const top = api.coord([index, bar.high])[1] ?? 0
          const left = x - thick / 2
          const fill = colorOf(bar, index)
          const before = bars[index - 1]
          const children: unknown[] = [
            {
              type: "rect",
              shape: {
                x: left,
                y: top,
                width: thick,
                height: Math.max(bottom - top, 1),
                r: 3,
              },
              style: { fill },
              emphasis: { style: { fill: withAlpha(fill, 0.82) } },
            },
          ]
          if (before) {
            const y = api.coord([index, before.level])[1] ?? 0
            children.push({
              type: "line",
              silent: true,
              shape: { x1: left - (band - thick), y1: y, x2: left, y2: y },
              style: { stroke: tokens.fgFaint, lineWidth: 1, lineDash: [3, 3] },
            })
          }
          if (values && !(cramped && bar.kind === "delta"))
            children.push({
              type: "text",
              silent: true,
              x,
              y: top - 6,
              style: {
                text: caption(bar),
                fill: tokens.fgMuted,
                font: `600 11px ${tokens.fontMono}`,
                align: "center",
                verticalAlign: "bottom",
              },
            })
          return { type: "group", children }
        },
      },
    ],
  } as EChartsOption
}

export const waterfallChartTable = ({
  data,
  format,
}: WaterfallChartSpec): ChartSummary => {
  const print = toFormatter(format)
  return {
    columns: ["Step", "Change", "Level"],
    rows: waterfallBars(data).map((bar) => [
      bar.label,
      bar.kind === "total" ? null : signedFormat(print)(bar.value),
      print(bar.level),
    ]),
  }
}

export interface WaterfallChartProps extends ChartCommonProps, WaterfallChartSpec {}

/** A bridge from a start to an end: each change floats on the running sum. */
export const WaterfallChart = specChart<WaterfallChartSpec>({
  name: "WaterfallChart",
  keys: ["data", "format", "invert", "values"],
  option: waterfallChartOption,
  table: waterfallChartTable,
  isEmpty: (spec) => spec.data.length === 0,
  label: "Waterfall chart",
  height: 320,
})

