"use client"

import {
  type ButtonHTMLAttributes,
  createContext,
  forwardRef,
  type HTMLAttributes,
  type KeyboardEvent as ReactKeyboardEvent,
  type MouseEvent as ReactMouseEvent,
  useCallback,
  useContext,
  useId,
  useMemo,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { useRovingFocus } from "../../hooks/use-roving-focus.js"
import { cx } from "../../utils/cx.js"

interface AccordionContextValue {
  value: readonly string[]
  toggle: (item: string) => void
  /** True when the open item of a single, non-collapsible accordion can't be closed. */
  isLocked: (item: string) => boolean
  disabled: boolean
}

const AccordionContext = createContext<AccordionContextValue | null>(null)

const useAccordionContext = (part: string): AccordionContextValue => {
  const context = useContext(AccordionContext)
  if (!context) throw new Error(`<${part}> must be rendered inside <Accordion>.`)
  return context
}

interface AccordionItemContextValue {
  value: string
  open: boolean
  disabled: boolean
  triggerId: string
  contentId: string
}

const AccordionItemContext = createContext<AccordionItemContextValue | null>(null)

const useItemContext = (part: string): AccordionItemContextValue => {
  const context = useContext(AccordionItemContext)
  if (!context) throw new Error(`<${part}> must be rendered inside <AccordionItem>.`)
  return context
}

interface AccordionBaseProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  disabled?: boolean
}

export interface AccordionSingleProps extends AccordionBaseProps {
  /** One item open at a time. */
  type?: "single"
  /** The open item, or "" for none. */
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Allow closing the open item so that none is open. */
  collapsible?: boolean
}

export interface AccordionMultipleProps extends AccordionBaseProps {
  /** Any number of items open at once. */
  type: "multiple"
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
}

export type AccordionProps = AccordionSingleProps | AccordionMultipleProps

type LooseAccordionProps = AccordionBaseProps & {
  type?: "single" | "multiple"
  value?: string | string[]
  defaultValue?: string | string[]
  onValueChange?: ((value: string) => void) | ((value: string[]) => void)
  collapsible?: boolean
}

const toList = (value: string | string[] | undefined): string[] | undefined => {
  if (value === undefined) return undefined
  if (Array.isArray(value)) return value
  return value === "" ? [] : [value]
}

// Only this accordion's own headers, so a nested accordion keeps its own arrow-key scope.
const HEADER_SELECTOR =
  ":scope > .kg-accordion__item > .kg-accordion__heading > .kg-accordion__trigger:not([disabled])"

export const Accordion = forwardRef<HTMLDivElement, AccordionProps>((props, ref) => {
  const {
    type = "single",
    value: valueProp,
    defaultValue,
    onValueChange,
    collapsible = false,
    disabled = false,
    onKeyDown,
    className,
    ...rest
  } = props as LooseAccordionProps
  const [value, setValue] = useControllableState<string[]>({
    value: toList(valueProp),
    defaultValue: toList(defaultValue) ?? [],
    onChange: (next) => {
      if (type === "multiple")
        (onValueChange as ((value: string[]) => void) | undefined)?.(next)
      else (onValueChange as ((value: string) => void) | undefined)?.(next[0] ?? "")
    },
  })
  const rove = useRovingFocus({ orientation: "vertical", selector: HEADER_SELECTOR })

  const toggle = useCallback(
    (item: string) =>
      setValue((current) => {
        const isOpen = current.includes(item)
        if (type === "multiple") {
          return isOpen ? current.filter((entry) => entry !== item) : [...current, item]
        }
        if (isOpen) return collapsible ? [] : current
        return [item]
      }),
    [setValue, type, collapsible],
  )

  const context = useMemo<AccordionContextValue>(
    () => ({
      value,
      toggle,
      isLocked: (item) => type === "single" && !collapsible && value.includes(item),
      disabled,
    }),
    [value, toggle, type, collapsible, disabled],
  )

  const handleKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event)
    if (event.defaultPrevented) return
    // Arrow keys inside a panel (inputs, sliders…) belong to that content, not to the headers.
    const target = event.target as HTMLElement
    if (!target.matches(".kg-accordion__trigger")) return
    if (target.closest(".kg-accordion") !== event.currentTarget) return
    rove(event)
  }

  return (
    <AccordionContext.Provider value={context}>
      <div
        ref={ref}
        className={cx("kg-accordion flex min-w-0 flex-col text-kg-fg", className)}
        data-disabled={disabled || undefined}
        onKeyDown={handleKeyDown}
        {...rest}
      />
    </AccordionContext.Provider>
  )
})

Accordion.displayName = "Accordion"

export interface AccordionItemProps extends HTMLAttributes<HTMLDivElement> {
  value: string
  disabled?: boolean
}

export const AccordionItem = forwardRef<HTMLDivElement, AccordionItemProps>(
  ({ value, disabled = false, className, ...props }, ref) => {
    const accordion = useAccordionContext("AccordionItem")
    const open = accordion.value.includes(value)
    const id = useId()
    const item = useMemo<AccordionItemContextValue>(
      () => ({
        value,
        open,
        disabled: disabled || accordion.disabled,
        triggerId: `${id}-trigger`,
        contentId: `${id}-content`,
      }),
      [value, open, disabled, accordion.disabled, id],
    )
    return (
      <AccordionItemContext.Provider value={item}>
        <div
          ref={ref}
          className={cx("kg-accordion__item border-b-2 border-kg-border", className)}
          data-state={open ? "open" : "closed"}
          data-disabled={item.disabled || undefined}
          {...props}
        />
      </AccordionItemContext.Provider>
    )
  },
)

AccordionItem.displayName = "AccordionItem"

export type AccordionHeadingLevel = 1 | 2 | 3 | 4 | 5 | 6

export interface AccordionTriggerProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** The heading level wrapping the button, to fit the page outline. */
  level?: AccordionHeadingLevel
}

const ChevronIcon = () => (
  // The chevron rides on a small paper disc that turns sage with an ink ring when it opens.
  <svg
    className={[
      "kg-accordion__chevron box-content size-3.5 shrink-0 rounded-full bg-kg-muted p-[0.3125rem] text-kg-fg-muted",
      "shadow-[inset_0_0_0_1px_var(--kg-border)] transition-[rotate,color,background-color,box-shadow] duration-(--kg-duration-base) ease-kg-out",
      "group-enabled/trigger:group-hover/trigger:text-kg-fg",
      "group-data-[state=open]/trigger:rotate-180 group-data-[state=open]/trigger:bg-kg-paper-sage group-data-[state=open]/trigger:text-kg-fg",
      "group-data-[state=open]/trigger:shadow-[inset_0_0_0_2px_var(--kg-ink)]",
    ].join(" ")}
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    aria-hidden="true"
  >
    <path d="m6 9 6 6 6-6" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
)

export const AccordionTrigger = forwardRef<HTMLButtonElement, AccordionTriggerProps>(
  ({ level = 3, onClick, className, children, ...props }, ref) => {
    const accordion = useAccordionContext("AccordionTrigger")
    const item = useItemContext("AccordionTrigger")
    const Heading = `h${level}` as "h3"
    const locked = accordion.isLocked(item.value)
    return (
      <Heading className="kg-accordion__heading m-0 flex [font:inherit]">
        <button
          ref={ref}
          type="button"
          id={item.triggerId}
          aria-expanded={item.open}
          aria-controls={item.contentId}
          // APG: an open panel that can't be collapsed reports its header as disabled.
          aria-disabled={locked || undefined}
          disabled={item.disabled}
          className={cx(
            "kg-accordion__trigger group/trigger flex flex-1 cursor-pointer items-center justify-between gap-4 rounded-kg-sm border-0 bg-transparent px-0.5 py-4",
            "text-start [font-family:inherit] text-kg-base font-semibold leading-[1.4] text-inherit [-webkit-tap-highlight-color:transparent]",
            "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
            "aria-disabled:cursor-default disabled:cursor-not-allowed disabled:opacity-50",
            className,
          )}
          data-state={item.open ? "open" : "closed"}
          {...props}
          onClick={(event: ReactMouseEvent<HTMLButtonElement>) => {
            onClick?.(event)
            if (!event.defaultPrevented) accordion.toggle(item.value)
          }}
        >
          <span className="kg-accordion__label decoration-kg-ink decoration-2 underline-offset-[0.3em] group-enabled/trigger:group-hover/trigger:underline">{children}</span>
          <ChevronIcon />
        </button>
      </Heading>
    )
  },
)

AccordionTrigger.displayName = "AccordionTrigger"

export interface AccordionContentProps extends HTMLAttributes<HTMLDivElement> {}

/** Collapses with `grid-template-rows` and leaves the accessibility tree while closed. */
export const AccordionContent = forwardRef<HTMLDivElement, AccordionContentProps>(
  ({ className, children, ...props }, ref) => {
    const item = useItemContext("AccordionContent")
    return (
      <div
        ref={ref}
        id={item.contentId}
        role="region"
        aria-labelledby={item.triggerId}
        className={cx(
          // visibility drops the closed panel from the tab order and accessibility tree once the
          // collapse has finished, without unmounting it.
          "kg-accordion__content grid grid-rows-[0fr] opacity-0 invisible",
          "[transition:grid-template-rows_var(--kg-duration-base)_var(--kg-ease-out),opacity_var(--kg-duration-fast)_var(--kg-ease-out),visibility_0s_linear_var(--kg-duration-base)]",
          "data-[state=open]:visible data-[state=open]:grid-rows-[1fr] data-[state=open]:opacity-100",
          "data-[state=open]:[transition:grid-template-rows_var(--kg-duration-slow)_var(--kg-ease-out),opacity_var(--kg-duration-base)_var(--kg-ease-out),visibility_0s]",
          className,
        )}
        data-state={item.open ? "open" : "closed"}
        {...props}
      >
        <div className="kg-accordion__clip min-h-0 overflow-hidden">
          <div className="kg-accordion__body px-0.5 pb-4 text-kg-base leading-[1.6] text-kg-fg-muted">{children}</div>
        </div>
      </div>
    )
  },
)

AccordionContent.displayName = "AccordionContent"

components/action-bar/action-bar.tsx:
"use client"

import { forwardRef, type ReactNode } from "react"
import { usePresence } from "../../hooks/use-presence.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"
import { Toolbar, ToolbarButton, type ToolbarProps, ToolbarSeparator } from "../toolbar/toolbar.js"

export type ActionBarPosition = "fixed" | "absolute"

export interface ActionBarProps extends Omit<ToolbarProps, "orientation"> {
  /** Number of selected items. The bar shows while it is above zero. */
  count: number
  /** Formats the count, e.g. `(n) => \`${n} files\``. */
  formatCount?: (count: number) => ReactNode
  /** Clears the selection: from the close button or Escape inside the bar. */
  onClear?: () => void
  clearLabel?: string
  /** `fixed` floats over the viewport; `absolute` floats over the nearest positioned parent. */
  position?: ActionBarPosition
  /** Actions, usually ToolbarButton elements. */
  children?: ReactNode
}

/* An inverted ink bar on a sage offset; it rises calmly from the bottom edge. */
const barClass = [
  "kg-action-bar z-40 left-1/2 bottom-[max(calc(var(--kg-space)*6),env(safe-area-inset-bottom))] max-w-[calc(100%-var(--kg-space)*6)]",
  "-translate-x-1/2 origin-[50%_100%] data-[position=fixed]:fixed data-[position=absolute]:absolute",
  "[--_toolbar-bg:var(--kg-fg)] [--_toolbar-fg:var(--kg-surface)] [--_toolbar-edge:var(--kg-fg)] [--_toolbar-radius:var(--kg-radius-xl)]",
  "[--_toolbar-shadow:5px_5px_0_var(--kg-paper-sage)] [--_toolbar-separator:color-mix(in_oklab,var(--kg-surface)_30%,transparent)]",
  "[--_toolbar-button:color-mix(in_oklab,var(--kg-surface)_80%,transparent)] [--_toolbar-button-hover:var(--kg-surface)]",
  "[--_toolbar-button-hover-bg:color-mix(in_oklab,var(--kg-surface)_14%,transparent)]",
  "[--kg-enter-y:12px] data-[state=open]:animate-[kg-pop-in_var(--kg-duration-slow)_var(--kg-ease-out)]",
  "data-[state=closed]:pointer-events-none data-[state=closed]:animate-[kg-pop-out_var(--kg-duration-fast)_var(--kg-ease-in)_forwards]",
]

const Close = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
    <path d="M18 6 6 18M6 6l12 12" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
)

/** A floating toolbar for bulk actions on a selection, turning up from the bottom edge. */
export const ActionBar = forwardRef<HTMLDivElement, ActionBarProps>(
  (
    {
      count,
      formatCount = (value) => `${value} selected`,
      onClear,
      clearLabel = "Clear selection",
      position = "fixed",
      className,
      children,
      onKeyDown,
      "aria-label": ariaLabel = "Selection actions",
      ...props
    },
    forwardedRef,
  ) => {
    const { ref, present, state } = usePresence<HTMLDivElement>(count > 0)
    const composed = useComposedRefs(ref, forwardedRef)
    if (!present) return null
    return (
      <Toolbar
        ref={composed}
        aria-label={ariaLabel}
        className={cx(barClass, className)}
        data-state={state}
        data-position={position}
        onKeyDown={(event) => {
          onKeyDown?.(event)
          if (event.key === "Escape" && onClear) {
            event.preventDefault()
            onClear()
          }
        }}
        {...props}
      >
        <span className="kg-action-bar__count inline-flex items-center gap-2 ps-1 pe-2 text-kg-sm font-medium whitespace-nowrap" aria-live="polite">
          <span className="kg-action-bar__badge grid h-[1.5rem] min-w-[1.5rem] place-items-center rounded-full bg-kg-paper-sage px-[6px] text-kg-xs font-bold tabular-nums text-kg-fg" aria-hidden="true">
            {count}
          </span>
          <span className="kg-action-bar__count-text text-[color-mix(in_oklab,var(--kg-surface)_86%,transparent)] max-[30rem]:sr-only">{formatCount(count)}</span>
        </span>
        <ToolbarSeparator />
        {children}
        {onClear && (
          <>
            <ToolbarSeparator />
            <ToolbarButton label={clearLabel} icon={<Close />} onClick={onClear} />
          </>
        )}
      </Toolbar>
    )
  },
)

ActionBar.displayName = "ActionBar"

components/activity-feed/activity-feed.t:
"use client"

import { forwardRef, type HTMLAttributes, type ReactNode, useId } from "react"
import { useLocale } from "../../hooks/use-locale.js"
import { cx } from "../../utils/cx.js"

export type ActivityFeedTone = "neutral" | "accent" | "success" | "warning" | "danger" | "info"
export type ActivityFeedHeadingElement = "h2" | "h3" | "h4" | "h5" | "h6"

export interface ActivityFeedItem {
  id: string
  /** Who did it, shown first and in bold. */
  actor?: ReactNode
  /** A `<Avatar>` or image for the actor. Takes the place of the icon. */
  avatar?: ReactNode
  /** Decorative glyph in a toned disc, for system events. */
  icon?: ReactNode
  tone?: ActivityFeedTone
  /** The verb phrase: "changed access for", "exported", "joined". */
  action: ReactNode
  target?: ReactNode
  /** A quieter second line. */
  detail?: ReactNode
  time: Date | string | number
}

export interface ActivityFeedLabels {
  today?: string
  yesterday?: string
}

export interface ActivityFeedProps extends HTMLAttributes<HTMLDivElement> {
  items: readonly ActivityFeedItem[]
  /** Split the feed under one heading per day. */
  groupByDay?: boolean
  dayAs?: ActivityFeedHeadingElement
  /** "Today" is measured from here. Pass it when rendering on the server so both sides agree. */
  now?: Date | number
  locale?: string
  timeZone?: string
  formatTime?: (date: Date) => string
  formatDay?: (date: Date) => string
  labels?: ActivityFeedLabels
  /** Shown when there are no items. */
  empty?: ReactNode
}

/* Paper Layers: system events sit on a paper disc in the item's tone; accent is an ink fill. */
const markerTone: Record<ActivityFeedTone, string> = {
  neutral: "bg-kg-muted text-kg-fg-muted",
  accent: "bg-kg-accent text-kg-accent-fg",
  success: "bg-kg-paper-sage text-kg-fg",
  warning: "bg-kg-paper-butter text-kg-fg",
  danger: "bg-kg-paper-rose text-kg-fg",
  info: "bg-kg-paper-sky text-kg-fg",
}

/* The timeline thread runs from this 1.75rem marker down to the next one. */
const itemClass = [
  "kg-activity-feed__item relative grid grid-cols-[1.75rem_minmax(0,1fr)_auto] gap-3 rounded-kg-md px-1.5 py-2",
  "transition-colors duration-(--kg-duration-fast) ease-kg-out hover:bg-kg-muted/70",
  "not-last:before:absolute not-last:before:w-px not-last:before:-translate-x-1/2 not-last:before:bg-kg-border not-last:before:content-['']",
  "not-last:before:start-[calc(var(--kg-space)*1.5+0.875rem)] not-last:before:top-[calc(var(--kg-space)*2+1.75rem+2px)] not-last:before:bottom-[calc(var(--kg-space)*-2+2px)]",
].join(" ")

const toDate = (value: Date | string | number) =>
  value instanceof Date ? value : new Date(value)

/**
 * A timeline of events: who did what to which thing, and when, grouped under a heading per
 * day. Times are real `<time>` elements. Server-safe; pass `now` so server and client agree on
 * which day is "Today".
 */
export const ActivityFeed = forwardRef<HTMLDivElement, ActivityFeedProps>(
  (
    {
      items,
      groupByDay = true,
      dayAs: Day = "h3",
      now,
      locale: localeProp,
      timeZone,
      formatTime,
      formatDay,
      labels,
      empty,
      className,
      ...props
    },
    ref,
  ) => {
    const id = useId()
    const locale = useLocale(localeProp)
    const dayKey = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    })
    const timeFormat = new Intl.DateTimeFormat(locale, {
      timeZone,
      hour: "numeric",
      minute: "2-digit",
    })
    const dayFormat = new Intl.DateTimeFormat(locale, {
      timeZone,
      weekday: "long",
      month: "short",
      day: "numeric",
    })
    const reference = now === undefined ? new Date() : toDate(now)
    const today = dayKey.format(reference)
    const yesterday = dayKey.format(new Date(reference.getTime() - 86_400_000))

    const dayLabel = (date: Date) => {
      if (formatDay) return formatDay(date)
      const key = dayKey.format(date)
      if (key === today) return labels?.today ?? "Today"
      if (key === yesterday) return labels?.yesterday ?? "Yesterday"
      return dayFormat.format(date)
    }

    const groups: { key: string; date: Date; items: ActivityFeedItem[] }[] = []
    for (const item of items) {
      const date = toDate(item.time)
      const key = !groupByDay
        ? "all"
        : Number.isNaN(date.getTime())
          ? "unknown"
          : dayKey.format(date)
      const last = groups[groups.length - 1]
      if (last?.key === key) last.items.push(item)
      else groups.push({ key, date, items: [item] })
    }

    const list = (entries: ActivityFeedItem[]) => (
      <ol className="kg-activity-feed__list m-0 list-none p-0">
        {entries.map((item) => {
          const date = toDate(item.time)
          return (
            <li key={item.id} className={itemClass} data-tone={item.tone ?? "neutral"}>
              <span
                className={cx(
                  "kg-activity-feed__marker grid size-[1.75rem] place-items-center [--kg-avatar-size:1.75rem] rounded-full [&>svg]:size-[0.875rem]",
                  markerTone[item.tone ?? "neutral"],
                )}
                aria-hidden="true"
              >
                {item.avatar ?? item.icon ?? (
                  <span className="kg-activity-feed__dot size-[0.4375rem] rounded-full bg-current" />
                )}
              </span>
              <div className="kg-activity-feed__content grid min-w-0 gap-0.5 self-center">
                <p className="kg-activity-feed__line m-0 leading-[1.45] wrap-anywhere">
                  {item.actor != null && (
                    <span className="kg-activity-feed__actor font-[580]">{item.actor} </span>
                  )}
                  <span className="kg-activity-feed__action text-kg-fg-muted">{item.action}</span>
                  {item.target != null && (
                    <span className="kg-activity-feed__target font-[580]"> {item.target}</span>
                  )}
                </p>
                {item.detail != null && (
                  <p className="kg-activity-feed__detail m-0 text-kg-xs leading-[1.45] text-kg-fg-faint wrap-anywhere">
                    {item.detail}
                  </p>
                )}
              </div>
              <time
                className="kg-activity-feed__time pt-[0.2rem] text-kg-xs tabular-nums whitespace-nowrap text-kg-fg-faint"
                dateTime={Number.isNaN(date.getTime()) ? undefined : date.toISOString()}
              >
                {Number.isNaN(date.getTime())
                  ? String(item.time)
                  : formatTime
                    ? formatTime(date)
                    : timeFormat.format(date)}
              </time>
            </li>
          )
        })}
      </ol>
    )

    return (
      <div ref={ref} className={cx("kg-activity-feed grid min-w-0 gap-4 text-kg-sm text-kg-fg", className)} {...props}>
        {items.length === 0 && empty != null ? (
          <div className="kg-activity-feed__empty px-0 py-8 text-center text-kg-fg-muted">{empty}</div>
        ) : groupByDay ? (
          groups.map((group, index) => (
            <section
              key={`${group.key}-${index}`}
              className="kg-activity-feed__group grid gap-1"
              aria-labelledby={`${id}-${index}`}
            >
              <Day
                className="kg-activity-feed__day m-0 flex items-center gap-3 py-1 text-kg-xs font-semibold tracking-[0.02em] text-kg-fg-muted after:h-px after:flex-1 after:bg-kg-border after:content-['']"
                id={`${id}-${index}`}
              >
                {Number.isNaN(group.date.getTime()) ? group.key : dayLabel(group.date)}
              </Day>
              {list(group.items)}
            </section>
          ))
        ) : (
          list([...items])
        )}
      </div>
    )
  },
)

ActivityFeed.displayName = "ActivityFeed"

components/add-to-cart-button/add-to-car:
"use client"

import {
  forwardRef,
  type MouseEvent,
  type ReactNode,
  type RefObject,
  useEffect,
  useRef,
  useState,
} from "react"
import { useEventCallback } from "../../hooks/use-event-callback.js"
import { cx } from "../../utils/cx.js"
import { Button, type ButtonProps } from "../button/button.js"
import { type CartItemInput, useCartActions } from "../cart/cart.js"
import { useFlyToCart } from "./fly-to-cart.js"

export type AddToCartButtonState = "idle" | "adding" | "added"

export interface AddToCartButtonLabels {
  add?: ReactNode
  adding?: ReactNode
  added?: ReactNode
  soldOut?: ReactNode
  /** Announced politely once the item is in the cart. */
  announcement?: string
}

export interface AddToCartButtonProps extends Omit<ButtonProps, "loading" | "asChild"> {
  /** Runs on click. While its promise is pending the button shows a spinner. */
  onAdd?: () => void | Promise<unknown>
  /** Added to the surrounding `CartProvider` once `onAdd` resolves. */
  item?: CartItemInput
  quantity?: number
  soldOut?: boolean
  /** How long the "Added" confirmation shows, in ms. */
  addedDuration?: number
  /** Fly this element (usually the product image) into the `[data-cart-target]` on success. */
  flyFrom?: RefObject<Element | null>
  /** Called when `onAdd` rejects. Without it the error is rethrown. */
  onError?: (error: unknown) => void
  labels?: AddToCartButtonLabels
  /** Hide the leading bag icon. */
  hideIcon?: boolean
}

const defaultLabels = {
  add: "Add to cart",
  adding: "Adding…",
  added: "Added",
  soldOut: "Sold out",
  announcement: "Added to cart",
} satisfies Required<AddToCartButtonLabels>

const BagIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.9"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M5 8h14l-1.2 11.1a2 2 0 0 1-2 1.9H8.2a2 2 0 0 1-2-1.9L5 8Z" />
    <path d="M9 10V7a3 3 0 0 1 6 0v3" />
  </svg>
)

const CheckIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.4"
    aria-hidden="true"
  >
    <path
      className="kg-add-to-cart__check [stroke-dasharray:1] [stroke-dashoffset:1] transition-[stroke-dashoffset] delay-(--kg-duration-fast) duration-(--kg-duration-slower) ease-kg-out in-data-[state=added]:[stroke-dashoffset:0]"
      d="m5 12.5 4.5 4.5L19 7.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      pathLength={1}
    />
  </svg>
)

type Face = "idle" | "adding" | "added"

/* The face each state replaces: it leaves upward while the new one rises from below. */
const outgoing: Record<Face, Face> = { idle: "added", adding: "idle", added: "adding" }

const faceClass = (face: Face, state: Face) =>
  cx(
    "kg-add-to-cart__face relative inline-flex items-center justify-center gap-2 [grid-area:1/1]",
    "transition-[opacity,translate,scale] duration-(--kg-duration-base) ease-kg-out",
    face !== state && "scale-[0.92] opacity-0",
    face !== state && (outgoing[state] === face ? "-translate-y-[70%]" : "translate-y-[70%]"),
    face === "added" && "text-kg-success-fg",
  )

/**
 * A primary "Add to cart" that morphs idle → spinner → check → idle around an async `onAdd`.
 * Every label is stacked in one grid cell, so the button keeps its width through the morph.
 */
export const AddToCartButton = forwardRef<HTMLButtonElement, AddToCartButtonProps>(
  (
    {
      onAdd,
      item,
      quantity = 1,
      soldOut = false,
      addedDuration = 1800,
      flyFrom,
      onError,
      labels,
      hideIcon = false,
      size = "lg",
      disabled,
      className,
      onClick,
      children,
      ...props
    },
    ref,
  ) => {
    const text = { ...defaultLabels, ...labels }
    const [state, setState] = useState<AddToCartButtonState>("idle")
    const cart = useCartActions()
    const fly = useFlyToCart()
    const mounted = useRef(true)
    const reportError = useEventCallback(onError)

    useEffect(() => {
      mounted.current = true
      return () => {
        mounted.current = false
      }
    }, [])

    useEffect(() => {
      if (state !== "added") return
      const timer = setTimeout(() => setState("idle"), addedDuration)
      return () => clearTimeout(timer)
    }, [state, addedDuration])

    const handleClick = async (event: MouseEvent<HTMLButtonElement>) => {
      onClick?.(event)
      if (event.defaultPrevented || state !== "idle" || soldOut) return
      setState("adding")
      try {
        await onAdd?.()
      } catch (error) {
        if (mounted.current) setState("idle")
        if (onError) reportError(error)
        else throw error
        return
      }
      if (item && cart) cart.addItem(item, quantity)
      if (flyFrom?.current) void fly(flyFrom.current)
      if (mounted.current) setState("added")
    }

    const unavailable = soldOut || disabled
    const idleLabel = soldOut ? text.soldOut : (children ?? text.add)

    return (
      <>
        <Button
          ref={ref}
          size={size}
          className={cx("kg-add-to-cart overflow-hidden", className)}
          data-state={soldOut ? "sold-out" : state}
          disabled={unavailable}
          aria-busy={state === "adding" || undefined}
          onClick={(event) => void handleClick(event)}
          {...props}
        >
          <span
            className={cx(
              "kg-add-to-cart__fill pointer-events-none absolute inset-0 bg-kg-success transition-opacity duration-(--kg-duration-base) ease-kg-out",
              state === "added" && !soldOut ? "opacity-100" : "opacity-0",
            )}
            aria-hidden="true"
          />
          <span className="kg-add-to-cart__stack grid place-items-center">
            <span
              className={faceClass("idle", soldOut ? "idle" : state)}
              data-face="idle"
              aria-hidden={state !== "idle"}
            >
              {!hideIcon && !soldOut && <BagIcon />}
              {idleLabel}
            </span>
            <span
              className={faceClass("adding", soldOut ? "idle" : state)}
              data-face="adding"
              aria-hidden={state !== "adding"}
            >
              <span
                className={cx(
                  "kg-add-to-cart__spinner size-[1em] rounded-full border-2 border-current border-e-transparent",
                  state === "adding" &&
                    "animate-spin [animation-duration:0.7s] motion-reduce:[animation-duration:1.6s]",
                )}
                aria-hidden="true"
              />
              {text.adding}
            </span>
            <span
              className={faceClass("added", soldOut ? "idle" : state)}
              data-face="added"
              aria-hidden={state !== "added"}
            >
              <CheckIcon />
              {text.added}
            </span>
          </span>
        </Button>
        <span className="kg-visually-hidden" aria-live="polite">
          {state === "added" ? text.announcement : ""}
        </span>
      </>
    )
  },
)

AddToCartButton.displayName = "AddToCartButton"

components/add-to-cart-button/fly-to-car:
"use client"

import { useCallback, useRef } from "react"
import { useIsomorphicLayoutEffect } from "../../hooks/use-isomorphic-layout-effect.js"
import { useReducedMotion } from "../../hooks/use-reduced-motion.js"

export interface FlyToCartOptions {
  /** Where to land. Defaults to the first visible `[data-cart-target]`. */
  target?: Element | null
  /** Flight time in ms. */
  duration?: number
  /** How high the arc rises above the straight line, in px. */
  arc?: number
}

export type FlyToCart = (
  from: Element | null,
  options?: FlyToCartOptions,
) => Promise<void>

const STEPS = 16

const findTarget = (): Element | null => {
  for (const node of document.querySelectorAll("[data-cart-target]")) {
    const rect = node.getBoundingClientRect()
    if (rect.width > 0 && rect.height > 0) return node
  }
  return null
}

/** Scale bounce on the cart icon, so the add registers even without a flight. */
export const bumpCartTarget = (target: Element | null): void => {
  target?.animate?.(
    [
      { scale: 1 },
      { scale: 1.22, offset: 0.35 },
      { scale: 0.94, offset: 0.7 },
      { scale: 1 },
    ],
    { duration: 480, easing: "ease-out" },
  )
}

const makeGhost = (from: Element, rect: DOMRect): HTMLElement => {
  const image = from instanceof HTMLImageElement ? from : from.querySelector("img")
  let ghost: HTMLElement
  if (image) {
    const img = document.createElement("img")
    img.src = image.currentSrc || image.src
    img.alt = ""
    img.style.objectFit = "cover"
    ghost = img
  } else {
    ghost = from.cloneNode(true) as HTMLElement
  }
  ghost.setAttribute("aria-hidden", "true")
  Object.assign(ghost.style, {
    position: "fixed",
    left: `${rect.left}px`,
    top: `${rect.top}px`,
    width: `${rect.width}px`,
    height: `${rect.height}px`,
    margin: "0",
    zIndex: "2147483000",
    pointerEvents: "none",
    boxShadow: "var(--kg-shadow-lg)",
    transformOrigin: "center",
    willChange: "transform, opacity",
  })
  return ghost
}

/**
 * Returns `fly(fromElement)`: clones the product image (or `fromElement` itself) and sends it
 * along an arc into the cart icon, then bumps the icon. Under reduced motion only the bump plays.
 */
export const useFlyToCart = (): FlyToCart => {
  const reduced = useReducedMotion()
  const latest = useRef(reduced)
  useIsomorphicLayoutEffect(() => {
    latest.current = reduced
  })

  return useCallback(async (from, options = {}) => {
    const target = options.target ?? findTarget()
    if (!target) return
    if (latest.current || !from || typeof document.body.animate !== "function") {
      bumpCartTarget(target)
      return
    }
    const start = from.getBoundingClientRect()
    const end = target.getBoundingClientRect()
    if (start.width === 0 || start.height === 0) {
      bumpCartTarget(target)
      return
    }

    const ghost = makeGhost(from, start)
    document.body.append(ghost)

    const dx = end.left + end.width / 2 - (start.left + start.width / 2)
    const dy = end.top + end.height / 2 - (start.top + start.height / 2)
    const endScale = Math.max(
      0.06,
      Math.min(end.width / start.width, end.height / start.height),
    )
    const arc = options.arc ?? Math.min(220, Math.max(80, Math.abs(dx) * 0.35))
    // Quadratic Bézier from the image to the icon with its control point above both.
    const cx = dx * 0.35
    const cy = Math.min(0, dy) - arc

    const keyframes: Keyframe[] = Array.from({ length: STEPS + 1 }, (_, step) => {
      const t = step / STEPS
      const u = 1 - t
      const x = 2 * u * t * cx + t * t * dx
      const y = 2 * u * t * cy + t * t * dy
      const scale = 1 + (endScale - 1) * t ** 1.4
      return {
        offset: t,
        transform: `translate(${x}px, ${y}px) scale(${scale})`,
        opacity: t > 0.85 ? 1 - (t - 0.85) / 0.15 : 1,
        borderRadius: `${12 + 40 * t}%`,
      }
    })

    try {
      await ghost.animate(keyframes, {
        duration: options.duration ?? 720,
        easing: "cubic-bezier(0.45, 0, 0.25, 1)",
        fill: "forwards",
      }).finished
    } catch {
      // Cancelled (e.g. the page navigated): still clean up below.
    } finally {
      ghost.remove()
    }
    bumpCartTarget(target)
  }, [])
}

