"use client"

import {
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  useEffect,
  useId,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"
import { CheckIcon, CopyIcon } from "../copy-field/copy-field.js"
import { useCopy } from "../copy-field/copy-text.js"

export interface ApiKeyFieldLabels {
  reveal?: string
  copy?: string
  copied?: string
  regenerate?: string
  confirm?: string
  cancel?: string
  /** Shown while the confirmation is open. */
  warning?: string
  /** Read before the visible tail of a masked key. */
  masked?: string
}

export interface ApiKeyFieldProps extends Omit<HTMLAttributes<HTMLDivElement>, "onCopy"> {
  /** The full key. Only the prefix and `visibleChars` of it are drawn until revealed. */
  value: string
  name: ReactNode
  /** A quiet line beside the name: created date, last used. */
  meta?: ReactNode
  /** Characters kept at the end of the masked key. */
  visibleChars?: number
  revealed?: boolean
  defaultRevealed?: boolean
  onRevealedChange?: (revealed: boolean) => void
  /** Adds a Regenerate action guarded by an inline confirmation. May return a promise. */
  onRegenerate?: () => void | Promise<void>
  onCopy?: (value: string) => void
  labels?: ApiKeyFieldLabels
}

const words: Required<ApiKeyFieldLabels> = {
  reveal: "Show key",
  copy: "Copy key",
  copied: "Copied",
  regenerate: "Regenerate",
  confirm: "Regenerate key",
  cancel: "Cancel",
  warning: "The current key stops working now.",
  masked: "hidden, ending in",
}

/** Keeps a recognisable prefix such as `sk_live_` and the last few characters. */
const mask = (value: string, visible: number) => {
  const prefix = /^[a-z]+(?:_[a-z]+)*_/i.exec(value)?.[0] ?? ""
  const tail = value.slice(Math.max(prefix.length, value.length - visible))
  const hidden = Math.max(value.length - prefix.length - tail.length, 0)
  return { prefix, dots: "•".repeat(Math.min(hidden, 16)), tail }
}

const EyeIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
    <path d="M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12Z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
)

const RotateIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
    <path d="M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
)

const tool = cx(
  "kg-api-key-field__tool grid place-items-center size-[1.875rem] p-0 [&_svg]:size-4",
  "border-0 rounded-kg-sm bg-transparent text-kg-fg-muted cursor-pointer",
  "transition-colors duration-(--kg-duration-fast) ease-kg-out",
  "interactive:not-aria-pressed:hover:bg-kg-muted interactive:not-aria-pressed:hover:text-kg-fg",
  "aria-pressed:bg-kg-accent aria-pressed:text-kg-accent-fg data-copied:text-kg-success",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
)

const action = cx(
  "kg-api-key-field__action h-kg-sm px-3 text-kg-xs font-[560] font-[family-name:inherit] rounded-full border-2 border-kg-ink",
  "cursor-pointer shadow-kg-xs transition-[translate,box-shadow] duration-(--kg-duration-fast) ease-kg-out",
  "interactive:hover:-translate-px interactive:active:translate-0.5 interactive:active:shadow-none",
  "disabled:cursor-progress disabled:opacity-70 disabled:shadow-none",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
)

/** An API key row: masked value, reveal, copy and a confirmed regenerate. */
export const ApiKeyField = forwardRef<HTMLDivElement, ApiKeyFieldProps>(
  (
    {
      value,
      name,
      meta,
      visibleChars = 4,
      revealed: revealedProp,
      defaultRevealed = false,
      onRevealedChange,
      onRegenerate,
      onCopy,
      labels,
      className,
      ...props
    },
    ref,
  ) => {
    const t = { ...words, ...labels }
    const nameId = useId()
    const warnId = useId()
    const [revealed, setRevealed] = useControllableState({
      value: revealedProp,
      defaultValue: defaultRevealed,
      onChange: onRevealedChange,
    })
    const [confirming, setConfirming] = useState(false)
    const [busy, setBusy] = useState(false)
    const { copied, copy } = useCopy()
    const cancelRef = useRef<HTMLButtonElement>(null)
    const regenRef = useRef<HTMLButtonElement>(null)
    const wasConfirming = useRef(false)

    useEffect(() => {
      if (confirming) cancelRef.current?.focus()
      else if (wasConfirming.current) regenRef.current?.focus()
      wasConfirming.current = confirming
    }, [confirming])

    const parts = mask(value, visibleChars)

    const regenerate = async () => {
      setBusy(true)
      try {
        await onRegenerate?.()
      } finally {
        setBusy(false)
        setConfirming(false)
      }
    }

    return (
      <div
        ref={ref}
        role="group"
        aria-labelledby={nameId}
        className={cx(
          "kg-api-key-field grid gap-2 min-w-0 p-3 text-kg-fg",
          "bg-kg-surface border-2 border-kg-ink rounded-kg-lg shadow-kg-sm",
          className,
        )}
        data-state={confirming ? "confirming" : "idle"}
        {...props}
      >
        <div className="kg-api-key-field__head flex items-baseline justify-between gap-3 min-w-0">
          <span id={nameId} className="kg-api-key-field__name text-kg-sm font-semibold text-kg-fg">
            {name}
          </span>
          {meta != null && (
            <span className="kg-api-key-field__meta text-kg-xs whitespace-nowrap text-kg-fg-faint">
              {meta}
            </span>
          )}
        </div>
        <div
          className={cx(
            "kg-api-key-field__row flex items-center gap-2 min-w-0 h-kg-md ps-3 pe-1",
            "bg-kg-surface-sunken border-2 border-kg-border rounded-kg-md",
          )}
        >
          <code
            className={cx(
              "kg-api-key-field__value flex-1 min-w-0 overflow-hidden p-0 bg-transparent rounded-none",
              "font-kg-mono text-kg-sm text-kg-fg whitespace-nowrap text-ellipsis",
              "data-revealed:animate-[kg-fade-in_var(--kg-duration-slow)_var(--kg-ease-out)]",
            )}
            data-revealed={revealed || undefined}
          >
            {revealed ? (
              value
            ) : (
              <>
                <span className="kg-api-key-field__prefix text-kg-fg-muted">{parts.prefix}</span>
                <span
                  className="kg-api-key-field__dots tracking-[0.08em] text-kg-fg-faint"
                  aria-hidden="true"
                >
                  {parts.dots}
                </span>
                <span className="kg-visually-hidden"> {t.masked} </span>
                {parts.tail}
              </>
            )}
          </code>
          <div className="kg-api-key-field__tools flex shrink-0 gap-0.5">
            <button
              type="button"
              className={tool}
              aria-label={t.reveal}
              aria-pressed={revealed}
              onClick={() => setRevealed(!revealed)}
            >
              <EyeIcon />
            </button>
            <button
              type="button"
              className={tool}
              aria-label={t.copy}
              data-copied={copied || undefined}
              onClick={async () => {
                if (await copy(value)) onCopy?.(value)
              }}
            >
              {copied ? <CheckIcon /> : <CopyIcon />}
            </button>
            {onRegenerate && !confirming && (
              <button
                ref={regenRef}
                type="button"
                className={tool}
                aria-label={t.regenerate}
                onClick={() => setConfirming(true)}
              >
                <RotateIcon />
              </button>
            )}
          </div>
        </div>
        {confirming && (
          <div
            className={cx(
              "kg-api-key-field__confirm flex flex-wrap items-center gap-2 px-2.5 py-2 text-kg-fg",
              "bg-kg-paper-rose border-2 border-kg-ink rounded-kg-md origin-top",
              "animate-[kg-pop-in_var(--kg-duration-base)_var(--kg-ease-out)]",
            )}
            role="alertdialog"
            aria-labelledby={warnId}
            onKeyDown={(event) => {
              if (event.key !== "Escape") return
              event.stopPropagation()
              setConfirming(false)
            }}
          >
            <span
              id={warnId}
              className="kg-api-key-field__warning flex-1 min-w-[10rem] text-kg-xs font-[520] text-kg-fg"
            >
              {t.warning}
            </span>
            <button
              ref={cancelRef}
              type="button"
              className={cx(action, "bg-kg-surface text-kg-fg")}
              onClick={() => setConfirming(false)}
            >
              {t.cancel}
            </button>
            <button
              type="button"
              className={cx(action, "bg-kg-danger text-kg-danger-fg")}
              data-tone="danger"
              aria-busy={busy || undefined}
              disabled={busy}
              onClick={() => void regenerate()}
            >
              {t.confirm}
            </button>
          </div>
        )}
        <span className="kg-visually-hidden" role="status">
          {copied ? t.copied : ""}
        </span>
      </div>
    )
  },
)

ApiKeyField.displayName = "ApiKeyField"

components/app-shell/app-shell.tsx:
"use client"

import {
  type ButtonHTMLAttributes,
  createContext,
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  useContext,
  useEffect,
  useId,
  useMemo,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { useMediaQuery } from "../../hooks/use-media-query.js"
import { cx } from "../../utils/cx.js"
import { Drawer, DrawerContent } from "../drawer/drawer.js"
import { SkipLink } from "../skip-link/skip-link.js"

export interface AppShellContextValue {
  /** True while the desktop sidebar is folded to its icon rail. Always false on mobile. */
  collapsed: boolean
  setCollapsed: (collapsed: boolean) => void
  /** True below `mobileQuery`, where the sidebar becomes an off-canvas drawer. */
  mobile: boolean
  mobileOpen: boolean
  setMobileOpen: (open: boolean) => void
  sidebarId: string
  mainId: string
}

const AppShellContext = createContext<AppShellContextValue | null>(null)

/** The surrounding shell's state, or null outside an `AppShell`. */
export const useAppShell = (): AppShellContextValue | null =>
  useContext(AppShellContext)

const useAppShellContext = (part: string): AppShellContextValue => {
  const context = useContext(AppShellContext)
  if (!context) throw new Error(`<${part}> must be rendered inside <AppShell>.`)
  return context
}

export interface AppShellProps extends HTMLAttributes<HTMLDivElement> {
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean) => void
  mobileOpen?: boolean
  defaultMobileOpen?: boolean
  onMobileOpenChange?: (open: boolean) => void
  /** Below this media query the sidebar moves into a drawer. */
  mobileQuery?: string
  /** Sets `--kg-app-shell-sidebar`. Any CSS length. */
  sidebarWidth?: string
  /** Sets `--kg-app-shell-rail`, the collapsed width. */
  railWidth?: string
  /** Remembers the collapsed state in localStorage under this key. */
  storageKey?: string
  /** Text of the built-in skip link. Pass `false` to render your own. */
  skipLink?: ReactNode
  /** Id given to `AppShellMain`, which the skip link targets. */
  mainId?: string
}

const innerClass = cx(
  "kg-app-shell__sidebar-inner flex flex-col gap-3 h-full p-3 overflow-x-hidden overflow-y-auto",
  "overscroll-contain [scrollbar-width:thin]",
)

const readStored = (key: string): boolean | null => {
  try {
    const value = localStorage.getItem(key)
    return value === null ? null : value === "true"
  } catch {
    return null
  }
}

export const AppShell = forwardRef<HTMLDivElement, AppShellProps>(
  (
    {
      collapsed: collapsedProp,
      defaultCollapsed = false,
      onCollapsedChange,
      mobileOpen: mobileOpenProp,
      defaultMobileOpen = false,
      onMobileOpenChange,
      mobileQuery = "(max-width: 767.98px)",
      sidebarWidth,
      railWidth,
      storageKey,
      skipLink = "Skip to content",
      mainId: mainIdProp,
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const [collapsed, setCollapsed] = useControllableState({
      value: collapsedProp,
      defaultValue: defaultCollapsed,
      onChange: onCollapsedChange,
    })
    const [mobileOpen, setMobileOpen] = useControllableState({
      value: mobileOpenProp,
      defaultValue: defaultMobileOpen,
      onChange: onMobileOpenChange,
    })
    const mobile = useMediaQuery(mobileQuery)
    const id = useId()
    const mainId = mainIdProp ?? `${id}-main`
    const sidebarId = `${id}-sidebar`

    // Read after mount: the server can't see storage, and hydration must match its markup.
    useEffect(() => {
      if (!storageKey) return
      const stored = readStored(storageKey)
      if (stored !== null) setCollapsed(stored)
    }, [storageKey, setCollapsed])

    useEffect(() => {
      if (!storageKey) return
      try {
        localStorage.setItem(storageKey, String(collapsed))
      } catch {}
    }, [storageKey, collapsed])

    // Leaving the mobile layout must not leave an invisible drawer holding the page inert.
    useEffect(() => {
      if (!mobile) setMobileOpen(false)
    }, [mobile, setMobileOpen])

    const value = useMemo<AppShellContextValue>(
      () => ({
        collapsed: collapsed && !mobile,
        setCollapsed,
        mobile,
        mobileOpen: mobileOpen && mobile,
        setMobileOpen,
        sidebarId,
        mainId,
      }),
      [collapsed, setCollapsed, mobile, mobileOpen, setMobileOpen, sidebarId, mainId],
    )

    const vars = {
      ...(sidebarWidth && { "--kg-app-shell-sidebar": sidebarWidth }),
      ...(railWidth && { "--kg-app-shell-rail": railWidth }),
      ...style,
    } as CSSProperties

    return (
      <AppShellContext.Provider value={value}>
        <div
          ref={ref}
          className={cx(
            "kg-app-shell relative grid h-dvh min-h-0 text-kg-fg bg-kg-bg",
            "[--kg-app-shell-sidebar:16rem] [--kg-app-shell-rail:4.25rem]",
            mobile
              ? "grid-cols-[minmax(0,1fr)] grid-rows-[auto_minmax(0,1fr)] [grid-template-areas:'header'_'main']"
              : cx(
                  "grid-rows-[auto_minmax(0,1fr)] [grid-template-areas:'sidebar_header'_'sidebar_main']",
                  value.collapsed
                    ? "grid-cols-[var(--kg-app-shell-rail)_minmax(0,1fr)]"
                    : "grid-cols-[var(--kg-app-shell-sidebar)_minmax(0,1fr)]",
                ),
            className,
          )}
          data-layout={mobile ? "mobile" : "desktop"}
          data-collapsed={value.collapsed || undefined}
          style={vars}
          {...props}
        >
          {skipLink !== false && <SkipLink target={mainId}>{skipLink}</SkipLink>}
          {children}
        </div>
      </AppShellContext.Provider>
    )
  },
)

AppShell.displayName = "AppShell"

export interface AppShellSidebarProps extends HTMLAttributes<HTMLElement> {
  /** Accessible name of the sidebar landmark and of the mobile drawer. */
  label?: string
  /** Accessible name of the mobile drawer's close button. */
  closeLabel?: string
}

/** A complementary landmark on desktop; a left drawer on the native <dialog> on mobile. */
export const AppShellSidebar = forwardRef<HTMLElement, AppShellSidebarProps>(
  (
    {
      label = "Sidebar",
      closeLabel = "Close navigation",
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const shell = useAppShellContext("AppShellSidebar")

    if (shell.mobile) {
      return (
        <Drawer open={shell.mobileOpen} onOpenChange={shell.setMobileOpen}>
          <DrawerContent
            side="left"
            aria-label={label}
            closeLabel={closeLabel}
            className={cx(
              "kg-app-shell__drawer [--_drawer-size:min(var(--kg-app-shell-sidebar,16rem),85vw)]",
              className,
            )}
          >
            <div className={cx(innerClass, "pt-3.5")}>{children}</div>
          </DrawerContent>
        </Drawer>
      )
    }

    return (
      <aside
        ref={ref}
        id={shell.sidebarId}
        aria-label={label}
        className={cx(
          "kg-app-shell__sidebar [grid-area:sidebar] min-w-0 min-h-0 bg-kg-surface border-e-2 border-kg-ink",
          className,
        )}
        data-collapsed={shell.collapsed || undefined}
        {...props}
      >
        <div className={cx(innerClass, shell.collapsed && "px-2 items-stretch")}>{children}</div>
      </aside>
    )
  },
)

AppShellSidebar.displayName = "AppShellSidebar"

export interface AppShellHeaderProps extends HTMLAttributes<HTMLElement> {}

export const AppShellHeader = forwardRef<HTMLElement, AppShellHeaderProps>(
  ({ className, ...props }, ref) => (
    <header
      ref={ref}
      className={cx(
        "kg-app-shell__header [grid-area:header] relative z-1 min-w-0 bg-kg-bg border-b-2 border-kg-ink",
        className,
      )}
      {...props}
    />
  ),
)

AppShellHeader.displayName = "AppShellHeader"

export interface AppShellMainProps extends Omit<HTMLAttributes<HTMLElement>, "id"> {}

/** The scrolling content region and the skip link's target. */
export const AppShellMain = forwardRef<HTMLElement, AppShellMainProps>(
  ({ className, ...props }, ref) => {
    const shell = useAppShellContext("AppShellMain")
    return (
      <main
        ref={ref}
        id={shell.mainId}
        tabIndex={-1}
        className={cx(
          "kg-app-shell__main [grid-area:main] min-w-0 min-h-0 overflow-auto overscroll-contain outline-none",
          className,
        )}
        {...props}
      />
    )
  },
)

AppShellMain.displayName = "AppShellMain"

export interface AppShellToggleProps extends Omit<
  ButtonHTMLAttributes<HTMLButtonElement>,
  "children"
> {
  /** Accessible names for each state. */
  labels?: { collapse?: string; expand?: string; open?: string }
}

const PanelIcon = ({ flipped }: { flipped: boolean }) => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.8"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <rect x="3" y="4" width="18" height="16" rx="3" />
    <path d="M9 4v16" />
    <path
      className={cx(
        "kg-app-shell__toggle-chevron [transform-box:fill-box] origin-center",
        "transition-[rotate] duration-(--kg-duration-slow) ease-kg-out",
        flipped && "rotate-180",
      )}
      d="m15 10-2 2 2 2"
    />
  </svg>
)

/** Folds the sidebar to its rail on desktop and opens the navigation drawer on mobile. */
export const AppShellToggle = forwardRef<HTMLButtonElement, AppShellToggleProps>(
  ({ labels, className, onClick, ...props }, ref) => {
    const shell = useAppShellContext("AppShellToggle")
    const label = shell.mobile
      ? (labels?.open ?? "Open navigation")
      : shell.collapsed
        ? (labels?.expand ?? "Expand sidebar")
        : (labels?.collapse ?? "Collapse sidebar")
    return (
      <button
        ref={ref}
        type="button"
        className={cx(
          "kg-app-shell__toggle inline-grid place-items-center shrink-0 h-kg-sm w-(--kg-control-sm) p-0 text-kg-fg-muted",
          "bg-transparent border-0 rounded-kg-md cursor-pointer [&_svg]:size-[1.125rem]",
          "transition-[color,background-color,scale] duration-(--kg-duration-fast) ease-kg-out",
          "interactive:hover:text-kg-fg interactive:hover:bg-kg-muted interactive:active:scale-94",
          "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
          className,
        )}
        aria-label={label}
        aria-expanded={shell.mobile ? shell.mobileOpen : !shell.collapsed}
        aria-controls={shell.mobile ? undefined : shell.sidebarId}
        aria-haspopup={shell.mobile ? "dialog" : undefined}
        data-collapsed={shell.collapsed || undefined}
        onClick={(event) => {
          onClick?.(event)
          if (event.defaultPrevented) return
          if (shell.mobile) shell.setMobileOpen(true)
          else shell.setCollapsed(!shell.collapsed)
        }}
        {...props}
      >
        <PanelIcon flipped={shell.collapsed || shell.mobile} />
      </button>
    )
  },
)

