        "kg-bleed my-[calc(var(--_block,0px)*-1)]",
        full ? "mx-[calc(50%-50vw)] w-screen max-w-[100vw]" : "mx-[calc(var(--_inline,0px)*-1)]",
        className,
      )}
      data-full={full || undefined}
      style={{ ...vars({ "--_inline": space(inline), "--_block": space(block) }), ...style }}
      {...props}
    />
  ),
)

