import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
} from "react"
import { type BackdropMask, backdropRoot, hasChildren } from "../aurora/internal/backdrop.js"
import { createRandom, round } from "../aurora/internal/random.js"

export type BokehMask = BackdropMask

export interface BokehProps extends HTMLAttributes<HTMLDivElement> {
  /** Number of discs, 3–40. */
  count?: number
  /** CSS colors the discs cycle through. Defaults to sage and peach paper and ink. */
  colors?: readonly string[]
  /** Smallest and largest disc, as a fraction of the larger side. */
  size?: readonly [min: number, max: number]
  /** Drift speed multiplier; 0 holds them still. */
  speed?: number
  /** Same seed, same discs. */
  seed?: number
  mask?: BokehMask
  children?: ReactNode
}

const DEFAULT_COLORS = [
  "var(--kg-paper-sage)",
  "var(--kg-paper-peach)",
  "color-mix(in oklab, var(--kg-ink) 30%, transparent)",
] as const

/**
 * Out-of-focus discs of light floating in front of the lens. Seeded positions, sizes and drift,
 * all on transform and opacity loops. Server-component safe.
 */
export const Bokeh = forwardRef<HTMLDivElement, BokehProps>(
  (
    {
      count = 16,
      colors = DEFAULT_COLORS,
      size = [0.04, 0.16],
      speed = 1,
      seed = 9,
      mask = "none",
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const wrapper = hasChildren(children)
    const random = createRandom(seed)
    const total = Math.round(Math.min(Math.max(count, 3), 40))
    const [min, max] = size
    const palette = colors.length ? colors : DEFAULT_COLORS
    return (
      <div
        ref={ref}
        {...backdropRoot(
          "kg-bokeh absolute inset-0 overflow-hidden pointer-events-none data-wrapper:relative data-wrapper:inset-auto data-wrapper:isolate data-wrapper:pointer-events-auto",
          className,
          wrapper,
        )}
        data-mask={mask}
        style={
          {
            "--kg-bokeh-speed": Math.max(speed, 0.001),
            "--kg-bokeh-state": speed === 0 ? "paused" : "running",
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        <div className="kg-bokeh__layer pointer-events-none absolute inset-0 z-0 overflow-hidden [container-type:size]" aria-hidden="true">
          {Array.from({ length: total }, (_, index) => {
            const depth = random()
            return (
              <span
                key={index}
                className="kg-bokeh__disc absolute aspect-square w-[calc(var(--_size)*100cqmax)] -translate-1/2 rounded-full opacity-(--_alpha) will-change-transform"
                style={
                  {
                    left: `${round(random() * 100, 2)}%`,
                    top: `${round(random() * 100, 2)}%`,
                    "--_size": round(min + (max - min) * depth ** 1.5, 4),
                    "--_c": palette[index % palette.length],
                    "--_alpha": round(0.18 + random() * 0.4),
                    "--_dur": `${round(14 + random() * 16, 2)}s`,
                    "--_delay": `${round(-random() * 30, 2)}s`,
                    "--_dx": `${round((random() - 0.5) * 16, 2)}cqw`,
                    "--_dy": `${round(-4 - random() * 12, 2)}cqh`,
                  } as CSSProperties
                }
              />
            )
          })}
        </div>
        {wrapper && <div className="kg-bokeh__content relative z-1">{children}</div>}
      </div>
    )
  },
)

Bokeh.displayName = "Bokeh"

components/border-beam/border-beam.css:
/* An XOR mask, the beam pseudo-elements on an offset path and a registered angle fallback. */
@property --kg-beam-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@layer kg.components {
  .kg-border-beam {
    --_size: var(--kg-beam-size, 80px);
    --_duration: var(--kg-beam-duration, 6s);
    --_delay: var(--kg-beam-delay, 0s);

    /* Two masks XOR'd leave only the edge band, so the beam never crosses the content. */
    -webkit-mask:
      linear-gradient(#000 0 0) content-box,
      linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask:
      linear-gradient(#000 0 0) content-box exclude,
      linear-gradient(#000 0 0);

    /* The beam rides the container's own outline at constant speed, corners included. */
    &::after {
      content: "";
      position: absolute;
      width: var(--_size);
      aspect-ratio: 1;
      offset-path: rect(0 auto auto 0 round var(--_path-radius, 0px));
      offset-anchor: 90% 50%;
      background: linear-gradient(to left, var(--_from), var(--_to), transparent);
      animation: kg-beam-travel var(--_duration) linear var(--_delay) infinite;
    }

    &[data-reverse]::after {
      offset-anchor: 10% 50%;
      background: linear-gradient(to right, var(--_from), var(--_to), transparent);
      animation-direction: reverse;
    }

    &[data-paused]::after,
    &[data-paused]::before {
      animation-play-state: paused;
    }
  }

  @keyframes kg-beam-travel {
    from {
      offset-distance: 0%;
    }
    to {
      offset-distance: 100%;
    }
  }

  @keyframes kg-beam-spin {
    to {
      --kg-beam-angle: 360deg;
    }
  }

  /* Without offset-path shapes, sweep a conic gradient around the edge instead. */
  @supports not (offset-path: rect(0 auto auto 0)) {
    .kg-border-beam {
      &::after {
        display: none;
      }

      &::before {
        content: "";
        position: absolute;
        inset: 0;
        background: conic-gradient(
          from var(--kg-beam-angle),
          transparent 0turn,
          transparent 0.72turn,
          var(--_to) 0.92turn,
          var(--_from) 1turn
        );
        animation: kg-beam-spin var(--_duration) linear var(--_delay) infinite;
      }

      &[data-reverse]::before {
        background: conic-gradient(
          from var(--kg-beam-angle),
          var(--_from) 0turn,
          var(--_to) 0.08turn,
          transparent 0.28turn,
          transparent 1turn
        );
        animation-direction: reverse;
      }
    }
  }

  /* Reduced motion: a still gradient edge in the same colours. */
  @media (prefers-reduced-motion: reduce) {
    .kg-border-beam {
      &::after {
        display: none;
      }

      &::before {
        content: "";
        position: absolute;
        inset: 0;
        animation: none;
        background: linear-gradient(135deg, var(--_from), transparent 35%, transparent 65%, var(--_to));
      }
    }
  }

  [data-kg-motion="reduce"] .kg-border-beam {
    &::after {
      display: none;
    }

    &::before {
      content: "";
      position: absolute;
      inset: 0;
      animation: none;
      background: linear-gradient(135deg, var(--_from), transparent 35%, transparent 65%, var(--_to));
    }
  }
}

