components/checkout-form/checkout-form.t:
"use client"

import {
  type FormEvent,
  forwardRef,
  type FormHTMLAttributes,
  type ReactNode,
  useId,
  useRef,
  useState,
} from "react"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"
import { formatMoney } from "../../utils/money.js"
import {
  AddressForm,
  type AddressFormCountry,
  type AddressFormField,
  type AddressFormValue,
  emptyAddress,
} from "../address-form/address-form.js"
import { Button } from "../button/button.js"
import { Checkbox } from "../checkbox/checkbox.js"
import { Field } from "../field/field.js"
import { Input } from "../input/input.js"
import { PaymentMethodSelector } from "../payment-method-selector/payment-method-selector.js"

export interface CheckoutFormShippingOption {
  id: string
  label: string
  /** e.g. "2-4 business days". */
  detail?: string
  /** 0 renders as `labels.free`. */
  price: number
}

export interface CheckoutFormValue {
  email: string
  marketing: boolean
  address: AddressFormValue
  shippingOption: string | undefined
}

export interface CheckoutFormLabels {
  contact?: string
  email?: string
  emailInvalid?: string
  marketing?: string
  shipping?: string
  delivery?: string
  payment?: string
  free?: string
  required?: string
  /** Submit button text, given the formatted total. */
  submit?: (total: string) => string
}

export interface CheckoutFormProps extends Omit<
  FormHTMLAttributes<HTMLFormElement>,
  "onSubmit" | "defaultValue"
> {
  onSubmit: (value: CheckoutFormValue) => void | Promise<void>
  /** Order total before shipping; the chosen shipping price is added on the button. */
  subtotal: number
  currency?: string
  locale?: string
  shippingOptions?: readonly CheckoutFormShippingOption[]
  countries?: readonly AddressFormCountry[]
  defaultValue?: Partial<CheckoutFormValue>
  /** The payment section's content, e.g. a PaymentMethodSelector or provider element. */
  payment?: ReactNode
  labels?: CheckoutFormLabels
}

const defaultLabels: Required<CheckoutFormLabels> = {
  contact: "Contact",
  email: "Email",
  emailInvalid: "Enter a valid email address.",
  marketing: "Email me with news and offers",
  shipping: "Shipping address",
  delivery: "Delivery",
  payment: "Payment",
  free: "Free",
  required: "Required",
  submit: (total) => `Pay ${total}`,
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
const REQUIRED: AddressFormField[] = ["name", "line1", "city", "postalCode"]

/**
 * One-page checkout in numbered sections: contact, shipping address, delivery speed and payment.
 * Errors are shown inline after a submit attempt and focus moves to the first one.
 */
export const CheckoutForm = forwardRef<HTMLFormElement, CheckoutFormProps>(
  (
    {
      onSubmit,
      subtotal,
      currency = "USD",
      locale,
      shippingOptions = [],
      countries,
      defaultValue,
      payment,
      labels,
      className,
      ...props
    },
    ref,
  ) => {
    const text = { ...defaultLabels, ...labels }
    const id = useId()
    const formRef = useRef<HTMLFormElement>(null)
    const composedRef = useComposedRefs(formRef, ref)
    const [email, setEmail] = useState(defaultValue?.email ?? "")
    const [marketing, setMarketing] = useState(defaultValue?.marketing ?? false)
    const [address, setAddress] = useState<AddressFormValue>(
      defaultValue?.address ?? emptyAddress(countries?.[0]?.code),
    )
    const [shippingOption, setShippingOption] = useState(
      defaultValue?.shippingOption ?? shippingOptions[0]?.id,
    )
    const [attempted, setAttempted] = useState(false)
    const [submitting, setSubmitting] = useState(false)

    const money = { currency, locale }
    const shipping = shippingOptions.find((option) => option.id === shippingOption)?.price ?? 0
    const total = subtotal + shipping

    const emailError = attempted && !EMAIL.test(email.trim()) ? text.emailInvalid : undefined
    const addressErrors = attempted
      ? Object.fromEntries(
          REQUIRED.filter((field) => !address[field].trim()).map((field) => [field, text.required]),
        )
      : {}

    const submit = async (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault()
      setAttempted(true)
      const valid =
        EMAIL.test(email.trim()) && REQUIRED.every((field) => address[field].trim())
      if (!valid) {
        requestAnimationFrame(() =>
          formRef.current?.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus(),
        )
        return
      }
      setSubmitting(true)
      try {
        await onSubmit({ email: email.trim(), marketing, address, shippingOption })
      } finally {
        setSubmitting(false)
      }
    }

    const section = (index: number, title: string, children: ReactNode) => (
      <section className="kg-checkout-form__section grid gap-4" aria-labelledby={`${id}-s${index}`}>
        <h2 id={`${id}-s${index}`} className="kg-checkout-form__heading flex items-center gap-2.5 m-0 text-kg-md font-[650]">
          <span
            className="kg-checkout-form__step inline-grid place-items-center size-6 shrink-0 rounded-full border-2 border-kg-ink bg-kg-accent text-kg-xs font-bold text-kg-accent-fg"
            aria-hidden="true"
          >
            {index}
          </span>
          {title}
        </h2>
        {children}
      </section>
    )

    let step = 0
    return (
      <form
        ref={composedRef}
        noValidate
        className={cx("kg-checkout-form grid gap-7 w-full max-w-xl text-kg-fg", className)}
        onSubmit={submit}
        {...props}
      >
        {section(
          ++step,
          text.contact,
          <div className="kg-checkout-form__fields grid gap-3">
            <Field label={text.email} error={emailError} required>
              <Input
                type="email"
                name="email"
                autoComplete="email"
                inputMode="email"
                value={email}
                onChange={(event) => setEmail(event.target.value)}
              />
            </Field>
            <Checkbox
              size="sm"
              label={text.marketing}
              checked={marketing}
              onCheckedChange={setMarketing}
            />
          </div>,
        )}
        {section(
          ++step,
          text.shipping,
          <AddressForm
            value={address}
            onValueChange={setAddress}
            countries={countries}
            errors={addressErrors}
            labels={{ legend: text.shipping }}
          />,
        )}
        {shippingOptions.length > 0 &&
          section(
            ++step,
            text.delivery,
            <PaymentMethodSelector
              label={text.delivery}
              name="shipping-option"
              value={shippingOption}
              onValueChange={setShippingOption}
              methods={shippingOptions.map((option) => ({
                id: option.id,
                label: option.label,
                description: option.detail,
                aside: option.price === 0 ? text.free : formatMoney(option.price, money),
              }))}
            />,
          )}
        {payment != null && section(++step, text.payment, payment)}
        <Button type="submit" size="lg" fullWidth loading={submitting}>
          {text.submit(formatMoney(total, money))}
        </Button>
      </form>
    )
  },
)

CheckoutForm.displayName = "CheckoutForm"

components/checkout-steps/checkout-steps:
import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
} from "react"
import { cx } from "../../utils/cx.js"

export type CheckoutStepsOrientation = "horizontal" | "vertical"
export type CheckoutStepState = "complete" | "current" | "upcoming"
/** `auto` switches to "Step 2 of 4" when the steps no longer fit their container. */
export type CheckoutStepsCompact = "auto" | boolean

export interface CheckoutStep {
  id: string
  label: ReactNode
  description?: ReactNode
}

export interface CheckoutStepsLabels {
  /** Names the navigation landmark. */
  nav?: string
  /** Appended to completed steps for screen readers. */
  complete?: string
  /** The compact summary. */
  summary?: (position: number, total: number) => string
}

export interface CheckoutStepsProps extends Omit<
  HTMLAttributes<HTMLElement>,
  "onChange"
> {
  steps: readonly CheckoutStep[]
  /** Id of the current step. Steps before it are complete. */
  current: string
  /** Makes completed steps buttons that navigate back. */
  onStepClick?: (id: string, index: number) => void
  orientation?: CheckoutStepsOrientation
  compact?: CheckoutStepsCompact
  labels?: CheckoutStepsLabels
}

const defaultLabels: Required<CheckoutStepsLabels> = {
  nav: "Checkout progress",
  complete: "completed",
  summary: (position, total) => `Step ${position} of ${total}`,
}

const Check = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="3"
    aria-hidden="true"
  >
    <path d="m5 12.5 4.5 4.5L19 7.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
)

type StepState = "complete" | "current" | "upcoming"

const markerState: Record<StepState, string> = {
  complete: "bg-kg-accent text-kg-accent-fg",
  current: "bg-kg-paper-sage text-kg-fg shadow-kg-xs",
  upcoming: "bg-kg-surface text-kg-fg-muted",
}

const itemClass =
  "kg-checkout-steps__item inline-flex max-w-full shrink-0 items-center gap-2.5 rounded-kg-md border-0 bg-transparent p-1 text-start font-[inherit] text-inherit"

/** A checkout progress stepper with animated connectors and a compact mobile summary. */
export const CheckoutSteps = forwardRef<HTMLElement, CheckoutStepsProps>(
  (
    {
      steps,
      current,
      onStepClick,
      orientation = "horizontal",
      compact = "auto",
      labels,
      className,
      style,
      ...props
    },
    ref,
  ) => {
    const text = { ...defaultLabels, ...labels }
    const found = steps.findIndex((step) => step.id === current)
    const active = found === -1 ? 0 : found
    const currentStep = steps[active]
    const progress = steps.length > 1 ? active / (steps.length - 1) : 1
    const vertical = orientation === "vertical"
    const summaryShown =
      compact === true
        ? "grid"
        : compact === "auto" && !vertical
          ? "hidden @max-[34rem]:grid"
          : "hidden"
    const listShown =
      compact === true ? "hidden" : compact === "auto" && !vertical ? "flex @max-[34rem]:hidden" : "flex"

    return (
      <nav
        ref={ref}
        aria-label={text.nav}
        className={cx("kg-checkout-steps @container text-kg-fg", className)}
        data-orientation={orientation}
        data-compact={
          compact === true ? "always" : compact === "auto" ? "auto" : undefined
        }
        style={
          {
            "--_progress": progress,
            "--_count": steps.length,
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        <div
          className={cx(
            "kg-checkout-steps__summary gap-2 text-kg-sm text-kg-fg-muted [&_strong]:font-[650] [&_strong]:text-kg-fg",
            summaryShown,
          )}
        >
          <span className="kg-checkout-steps__summary-text">
            {text.summary(active + 1, steps.length)}
            {currentStep && (
              <>
                <span aria-hidden="true"> · </span>
                <strong>{currentStep.label}</strong>
              </>
            )}
          </span>
          <span
            className="kg-checkout-steps__summary-bar relative block h-2.5 overflow-hidden rounded-full border-2 border-kg-ink bg-kg-surface"
            aria-hidden="true"
          >
            <span
              className="absolute inset-0 origin-left bg-kg-accent transition-[scale] duration-(--kg-duration-slower) ease-kg-in-out rtl:origin-right"
              style={{ scale: `${steps.length ? (active + 1) / steps.length : 1} 1` }}
            />
          </span>
        </div>
        <ol className={cx("kg-checkout-steps__list m-0 list-none p-0", listShown, vertical && "flex-col")}>
          {steps.map((step, index) => {
            const state: CheckoutStepState =
              index < active ? "complete" : index === active ? "current" : "upcoming"
            const marker = (
              <span
                className={cx(
                  "kg-checkout-steps__marker grid size-7 shrink-0 place-items-center rounded-full border-2 border-kg-ink text-kg-xs font-[650] tabular-nums [&>svg]:size-3.5",
                  "transition-[background-color,color,box-shadow] duration-(--kg-duration-base) ease-kg-out",
                  markerState[state],
                )}
                aria-hidden="true"
              >
                {state === "complete" ? <Check /> : index + 1}
              </span>
            )
            const content = (
              <>
                {marker}
                <span className="kg-checkout-steps__text grid min-w-0 gap-0.5">
                  <span
                    className={cx(
                      "kg-checkout-steps__label text-kg-sm leading-[1.3] whitespace-nowrap",
                      state === "upcoming" ? "font-[550] text-kg-fg-muted" : "text-kg-fg",
                      state === "current" ? "font-[650]" : state === "complete" && "font-[550]",
                    )}
                  >
                    {step.label}
                    {state === "complete" && (
                      <span className="kg-visually-hidden">, {text.complete}</span>
                    )}
                  </span>
                  {step.description != null && (
                    <span className="kg-checkout-steps__description text-kg-xs leading-[1.4] text-kg-fg-muted">
                      {step.description}
                    </span>
                  )}
                </span>
              </>
            )
            return (
              <li
                key={step.id}
                className={cx(
                  "kg-checkout-steps__step flex min-w-0",
                  vertical
                    ? "flex-none flex-col items-stretch"
                    : "flex-auto items-center last:flex-none",
                )}
                data-state={state}
                aria-current={state === "current" ? "step" : undefined}
                style={{ "--_index": index } as CSSProperties}
              >
                {state === "complete" && onStepClick ? (
                  <button
                    type="button"
                    className={cx(
                      itemClass,
                      vertical && "items-start",
                      "cursor-pointer transition-[background-color] duration-(--kg-duration-fast) ease-kg-out hover:bg-kg-paper-sage focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
                    )}
                    onClick={() => onStepClick(step.id, index)}
                  >
                    {content}
                  </button>
                ) : (
                  <span className={cx(itemClass, vertical && "items-start")}>{content}</span>
                )}
                {index < steps.length - 1 && (
                  <span
                    className={cx(
                      "kg-checkout-steps__connector relative overflow-hidden rounded-full bg-kg-border",
                      vertical
                        ? "my-1 ms-[calc(var(--kg-space)*1+0.875rem-1px)] min-h-6 w-[2px] flex-none"
                        : "mx-2 h-[2px] min-w-4 flex-auto",
                    )}
                    aria-hidden="true"
                  >
                    <span
                      className={cx(
                        "absolute inset-0 bg-kg-ink transition-[scale] duration-(--kg-duration-slower) ease-kg-in-out",
                        vertical ? "origin-top" : "origin-left rtl:origin-right",
                        state !== "complete" && (vertical ? "scale-y-0" : "scale-x-0"),
                      )}
                    />
                  </span>
                )}
              </li>
            )
          })}
        </ol>
      </nav>
    )
  },
)

CheckoutSteps.displayName = "CheckoutSteps"

components/chip-list/chip-list.tsx:
"use client"

import { forwardRef, type HTMLAttributes, type ReactNode, useState } from "react"
import { cx } from "../../utils/cx.js"
import { variants } from "../../utils/variants.js"

/* Paper Layers: chips are small paper tabs with an ink edge; tones pick the paper colour. */
const listVariants = variants({
  base: "kg-chip-list m-0 flex list-none flex-wrap gap-1.5 p-0",
  variants: {
    size: {
      sm: "[--_h:1.375rem] [--_fs:var(--kg-text-xs)]",
      md: "[--_h:1.75rem] [--_fs:var(--kg-text-sm)]",
    },
  },
  defaults: { size: "md" },
})

const chip =
  "inline-flex h-(--_h) items-center gap-[0.3125rem] whitespace-nowrap rounded-full border-2 px-[calc(var(--_h)*0.42)] text-(length:--_fs) leading-none font-medium text-kg-fg"

const chipVariants = variants({
  base: [
    "kg-chip-list__chip border-kg-ink",
    chip,
    "data-revealed:transition-[opacity,scale,rotate] data-revealed:duration-(--kg-duration-slow) data-revealed:ease-kg-spring",
    "data-revealed:starting:scale-85 data-revealed:starting:-rotate-6 data-revealed:starting:opacity-0",
  ],
  variants: {
    tone: {
      neutral: "bg-kg-surface",
      accent: "bg-kg-paper-sage",
      success: "bg-kg-paper-sage",
      warning: "bg-kg-paper-butter",
      danger: "bg-kg-paper-rose",
      info: "bg-kg-paper-sky",
    },
  },
  defaults: { tone: "neutral" },
})

export type ChipListSize = "sm" | "md"
export type ChipListTone = "neutral" | "accent" | "success" | "warning" | "danger" | "info"

export interface ChipListItem {
  label: string
  icon?: ReactNode
  tone?: ChipListTone
  key?: string
}

export interface ChipListLabels {
  /** Text for the overflow chip, given the hidden count. */
  more?: (count: number) => string
  less?: string
}

export interface ChipListProps extends HTMLAttributes<HTMLUListElement> {
  items: (string | ChipListItem)[]
  /** Chips shown before collapsing the rest into a “+N” chip. */
  max?: number
  size?: ChipListSize
  labels?: ChipListLabels
}

const normalize = (item: string | ChipListItem): ChipListItem =>
  typeof item === "string" ? { label: item } : item

/** A read-only set of chips that folds the overflow into an expandable “+N”. */
export const ChipList = forwardRef<HTMLUListElement, ChipListProps>(
  ({ items, max, size = "md", labels, className, ...props }, ref) => {
    const [open, setOpen] = useState(false)
    const all = items.map(normalize)
    const limit = max !== undefined && max >= 0 && all.length > max ? max : all.length
    const visible = open ? all : all.slice(0, limit)
    const hidden = all.length - limit
    const more = labels?.more ?? ((count: number) => `+${count}`)

    return (
      <ul
        ref={ref}
        className={listVariants({ size, className })}
        data-size={size}
        {...props}
      >
        {visible.map((item, index) => (
          <li
            key={item.key ?? `${item.label}-${index}`}
            className={chipVariants({ tone: item.tone ?? "neutral" })}
            data-tone={item.tone ?? "neutral"}
            data-revealed={open && index >= limit ? true : undefined}
          >
            {item.icon && (
              <span className="kg-chip-list__icon inline-flex [&_svg]:size-[0.875em]" aria-hidden="true">
                {item.icon}
              </span>
            )}
            {item.label}
          </li>
        ))}
        {hidden > 0 && (
          <li className="kg-chip-list__more-item inline-flex">
            <button
              type="button"
              className={cx(
                "kg-chip-list__more cursor-pointer border-dashed border-kg-ink bg-kg-muted tabular-nums",
                chip,
                "transition-[translate,box-shadow] duration-(--kg-duration-fast) ease-kg-out hover:-translate-px hover:shadow-kg-xs focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
              )}
              aria-expanded={open}
              aria-label={open ? (labels?.less ?? "Show fewer") : `Show ${hidden} more`}
              onClick={() => setOpen((value) => !value)}
            >
              {open ? (labels?.less ?? "Less") : more(hidden)}
            </button>
          </li>
        )}
      </ul>
    )
  },
)
ChipList.displayName = "ChipList"

components/choice-list/choice-list.tsx:
"use client"

import {
  forwardRef,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
  type Ref,
  useId,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"
import { variants } from "../../utils/variants.js"

export type ChoiceListLayout = "list" | "grid"
export type ChoiceListSize = "sm" | "md"

export interface ChoiceListOption<V extends string = string> {
  value: V
  label: ReactNode
  description?: ReactNode
  /** Decorative, shown in a tile before the text. */
  icon?: ReactNode
  /** Trailing detail such as a price, a count or a badge. */
  aside?: ReactNode
  disabled?: boolean
}

export interface ChoiceListProps<V extends string = string> extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  options: readonly ChoiceListOption<V>[]
  value?: V | null
  defaultValue?: V | null
  onValueChange?: (value: V) => void
  /** Names the group for assistive tech. */
  label?: string
  /** Groups the inputs in forms. Generated when omitted. */
  name?: string
  /** `list` stacks the cards, `grid` flows them into columns that fit. */
  layout?: ChoiceListLayout
  size?: ChoiceListSize
  disabled?: boolean
  required?: boolean
}

const listVariants = variants({
  base: "kg-choice-list grid min-w-0",
  variants: {
    layout: {
      list: "",
      grid: "grid-cols-[repeat(auto-fill,minmax(min(100%,14rem),1fr))]",
    },
    size: {
      sm: "gap-1.5 [--_pad:calc(var(--kg-space)*2.5)] [--_tile:1.75rem]",
      md: "gap-2 [--_pad:calc(var(--kg-space)*3.5)] [--_tile:2.25rem]",
    },
  },
})

/*
 * Paper Layers: each choice is a sheet in an ink frame. The picked one lifts onto sage with an
 * ink offset and its ring fills with ink, so the choice never rests on colour alone.
 */
const optionClass = [
  "kg-choice-list__option group/choice relative flex min-w-0 cursor-pointer items-center gap-3",
  "rounded-kg-lg border-2 border-kg-ink bg-kg-surface p-(--_pad) pe-[calc(var(--_pad)+1.75rem)] text-kg-fg",
  "[-webkit-tap-highlight-color:transparent] transition-[translate,box-shadow,background-color] duration-(--kg-duration-fast) ease-kg-out",
  "hover:not-data-disabled:not-data-checked:-translate-px hover:not-data-disabled:not-data-checked:shadow-kg-xs",
  "data-checked:-translate-px data-checked:bg-kg-paper-sage data-checked:shadow-kg-sm",
  "has-focus-visible:outline-2 has-focus-visible:outline-offset-2 has-focus-visible:outline-kg-ring",
  "data-disabled:cursor-not-allowed data-disabled:opacity-55",
].join(" ")

const markClass = [
  "kg-choice-list__mark absolute end-(--_pad) top-1/2 size-4 -translate-y-1/2 rounded-full border-2 border-kg-ink",
  "transition-[background-color,box-shadow] duration-(--kg-duration-fast) ease-kg-out",
  "group-data-checked/choice:bg-kg-ink group-data-checked/choice:shadow-[inset_0_0_0_3px_var(--kg-paper-sage)]",
].join(" ")

const ChoiceListImpl = <V extends string = string>(
  {
    options,
    value: valueProp,
    defaultValue = null,
    onValueChange,
    label,
    name: nameProp,
    layout = "list",
    size = "md",
    disabled = false,
    required = false,
    className,
    ...props
  }: ChoiceListProps<V>,
  ref: Ref<HTMLDivElement>,
) => {
  const fallbackName = useId()
  const name = nameProp ?? fallbackName
  const [value, setValue] = useControllableState<V | null>({
    value: valueProp,
    defaultValue,
    onChange: onValueChange as ((value: V | null) => void) | undefined,
  })

  return (
    <div
      ref={ref}
      role="radiogroup"
      aria-label={label}
      aria-required={required || undefined}
      aria-disabled={disabled || undefined}
      className={listVariants({ layout, size, className })}
      data-layout={layout}
      data-size={size}
      {...props}
    >
      {options.map((option) => {
        const id = `${name}-${option.value}`
        const checked = value === option.value
        const off = disabled || option.disabled
        return (
          <label
            key={option.value}
            className={optionClass}
            data-checked={checked || undefined}
            data-disabled={off || undefined}
          >
            <input
              type="radio"
              className="kg-choice-list__input absolute inset-0 m-0 size-full cursor-[inherit] opacity-0"
              name={name}
              value={option.value}
              checked={checked}
              disabled={off}
              required={required}
              aria-describedby={option.description != null ? `${id}-description` : undefined}
              onChange={() => setValue(option.value)}
            />
            {option.icon != null && (
              <span
                className={cx(
                  "kg-choice-list__icon grid size-(--_tile) shrink-0 place-items-center rounded-kg-md border-2 border-kg-ink [&_svg]:size-1/2",
                  checked ? "bg-kg-surface text-kg-fg" : "bg-kg-surface-sunken text-kg-fg-muted",
                )}
                aria-hidden="true"
              >
                {option.icon}
              </span>
            )}
            <span className="kg-choice-list__text grid min-w-0 flex-auto gap-0.5">
              <span className="kg-choice-list__label text-kg-base font-[580] leading-[1.35]">
                {option.label}
              </span>
              {option.description != null && (
                <span
                  className={cx(
                    "kg-choice-list__description text-kg-sm leading-[1.45]",
                    checked ? "text-kg-fg" : "text-kg-fg-muted",
                  )}
                  id={`${id}-description`}
                >
                  {option.description}
                </span>
              )}
            </span>
            {option.aside != null && (
              <span className="kg-choice-list__aside shrink-0 text-kg-sm font-[560] tabular-nums">{option.aside}</span>
            )}
            <span className={markClass} aria-hidden="true" />
          </label>
        )
      })}
    </div>
  )
}

/**
 * A single choice presented as cards: plans, report periods, export formats. Native radio
 * inputs underneath, so arrow keys, forms and validation behave as the platform does.
 */
export const ChoiceList = forwardRef(ChoiceListImpl) as (<V extends string = string>(
  props: ChoiceListProps<V> & { ref?: Ref<HTMLDivElement> },
) => ReactElement | null) & { displayName?: string }

ChoiceList.displayName = "ChoiceList"

