import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  useId,
} from "react"
import { cx } from "../../utils/cx.js"

export type CircularTextDirection = "clockwise" | "counterclockwise"
export type CircularTextHover = "speed-up" | "reverse" | "pause" | "none"

export interface CircularTextProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children"
> {
  /** Set once around the circle. Include your own separators, e.g. "FREE RETURNS ✦ ". */
  text: string
  /** Radius of the text baseline, in px. When omitted it is sized from the text. */
  radius?: number
  /** In px. */
  fontSize?: number
  /** Seconds per revolution. */
  duration?: number
  direction?: CircularTextDirection
  /** What happens while the pointer is over the badge. */
  hover?: CircularTextHover
  /** Rendered in the middle of the ring: an icon, a logo or a short label. */
  children?: ReactNode
}

// Average advance of an uppercase glyph with a little tracking, as a fraction of the font size.
const GLYPH_ADVANCE = 0.68

/** The radius at which `text` at `fontSize` wraps the circle once with even tracking. */
export const fitCircularTextRadius = (text: string, fontSize: number): number =>
  Math.max(
    fontSize * 1.5,
    (Array.from(text).length * fontSize * GLYPH_ADVANCE) / (2 * Math.PI),
  )

/*
 * Two nested turns: the outer one always runs, the inner one plays only while hovered. Pausing and
 * resuming never jumps the angle, so speeding up or reversing is seamless in pure CSS.
 */
const turn =
  "col-start-1 row-start-1 block size-full animate-[kg-spin_18s_linear_infinite] motion-reduce:animate-none"

/**
 * Text set on a circle that turns slowly and speeds up or reverses under the pointer. The text
 * is stretched to exactly one circumference (`textLength`), so it closes seamlessly whatever the
 * font. Server-safe: rotation and hover are pure CSS, and screen readers get the text once.
 */
export const CircularText = forwardRef<HTMLDivElement, CircularTextProps>(
  (
    {
      text,
      radius,
      fontSize = 13,
      duration = 18,
      direction = "clockwise",
      hover = "speed-up",
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const id = `kg-ring-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`
    const label = text.trim()
    // A trailing gap keeps the last glyph from kissing the first where the circle closes.
    const set = /\s$/.test(text) ? text : `${text} `
    const r = radius ?? fitCircularTextRadius(set, fontSize)
    const circumference = 2 * Math.PI * r
    const box = Math.ceil((r + fontSize * 1.25) * 2)
    const c = box / 2
    const ccw = direction === "counterclockwise"
    const boostReversed = (!ccw && hover === "reverse") || (ccw && hover === "speed-up")
    const path = `M ${c} ${c - r} a ${r} ${r} 0 1 1 0 ${2 * r} a ${r} ${r} 0 1 1 0 ${-2 * r}`

    return (
      <div
        ref={ref}
        className={cx("kg-circular-text group/ct relative inline-grid aspect-square w-(--_box) shrink-0 place-items-center rounded-full font-semibold tracking-[0.02em] text-kg-fg uppercase", className)}
        data-direction={direction}
        data-hover={hover}
        style={
          {
            "--_box": `${box}px`,
            "--_duration": `${Math.max(0.5, duration)}s`,
            "--_inner": `${Math.max(0, (r - fontSize * 0.9) * 2)}px`,
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        <span className="kg-visually-hidden">{label}</span>
        <span
          className={cx(
            turn,
            "kg-circular-text__spin [animation-duration:var(--_duration)]",
            ccw && "[animation-direction:reverse]",
            hover === "pause" && "group-hover/ct:[animation-play-state:paused]",
          )}
          aria-hidden="true"
        >
          <span
            className={cx(
              turn,
              "kg-circular-text__boost [animation-duration:calc(var(--_duration)/2)] [animation-play-state:paused]",
              boostReversed && "[animation-direction:reverse]",
              (hover === "speed-up" || hover === "reverse") &&
                "group-hover/ct:[animation-play-state:running]",
            )}
          >
            <svg
              className="kg-circular-text__svg block size-full overflow-visible"
              viewBox={`0 0 ${box} ${box}`}
              width={box}
              height={box}
              focusable="false"
            >
              <path id={id} d={path} fill="none" />
              <text
                className="kg-circular-text__text fill-current [font-family:inherit] [font-weight:inherit]"
                fontSize={fontSize}
                textLength={circumference.toFixed(2)}
                lengthAdjust="spacing"
              >
                <textPath
                  href={`#${id}`}
                  textLength={circumference.toFixed(2)}
                  lengthAdjust="spacing"
                >
                  {set}
                </textPath>
              </text>
            </svg>
          </span>
        </span>
        {children !== undefined && (
          <span
            className={cx(
              "kg-circular-text__center col-start-1 row-start-1 grid max-h-(--_inner) max-w-(--_inner) place-items-center",
              "transition-[scale] duration-(--kg-duration-spring) ease-(--kg-ease-bounce) [&>svg]:h-auto [&>svg]:w-[40%] [&>svg]:min-w-5",
              hover !== "none" && "group-hover/ct:scale-108",
            )}
          >{children}</span>
        )}
      </div>
    )
  },
)

CircularText.displayName = "CircularText"

components/clamp/clamp.tsx:
"use client"

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  useEffect,
  useId,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"

export interface ClampLabels {
  more?: string
  less?: string
}

export interface ClampProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode
  /** Visible lines while collapsed. */
  lines?: number
  expanded?: boolean
  defaultExpanded?: boolean
  onExpandedChange?: (expanded: boolean) => void
  /** Hide the toggle, for a read-only clamp. */
  hideToggle?: boolean
  labels?: ClampLabels
}

/**
 * Clamps content to a number of lines with a soft fade, and offers a toggle only when the
 * content actually overflows.
 */
export const Clamp = forwardRef<HTMLDivElement, ClampProps>(
  (
    {
      children,
      lines = 3,
      expanded: expandedProp,
      defaultExpanded = false,
      onExpandedChange,
      hideToggle = false,
      labels,
      className,
      style,
      ...props
    },
    ref,
  ) => {
    const [expanded, setExpanded] = useControllableState({
      value: expandedProp,
      defaultValue: defaultExpanded,
      onChange: onExpandedChange,
    })
    const bodyRef = useRef<HTMLDivElement>(null)
    const [overflows, setOverflows] = useState(false)
    const id = useId()
    const words = { more: "Show more", less: "Show less", ...labels }

    useEffect(() => {
      const node = bodyRef.current
      if (!node) return
      const measure = () => {
        if (expanded) return
        setOverflows(node.scrollHeight - node.clientHeight > 1)
      }
      measure()
      if (typeof ResizeObserver === "undefined") return
      const observer = new ResizeObserver(measure)
      observer.observe(node)
      return () => observer.disconnect()
    }, [expanded, lines, children])

    const showToggle = !hideToggle && (overflows || expanded)

    return (
      <div
        ref={ref}
        className={cx("kg-clamp grid min-w-0 justify-items-start gap-1.5", className)}
        data-state={expanded ? "expanded" : "collapsed"}
        data-overflows={overflows || undefined}
        style={{ "--_lines": lines, ...style } as CSSProperties}
        {...props}
      >
        <div
          ref={bodyRef}
          id={id}
          className={cx(
            "kg-clamp__body min-w-0",
            !expanded && "line-clamp-(--_lines)",
            !expanded &&
              overflows &&
              "[mask-image:linear-gradient(to_bottom,black_calc(100%-1.4em),transparent)]",
          )}
        >
          {children}
        </div>
        {showToggle && (
          <button
            type="button"
            className="kg-clamp__toggle inline-flex cursor-pointer items-center gap-1 rounded-kg-xs border-0 bg-transparent py-0.5 text-kg-sm font-semibold text-kg-accent-strong underline-offset-[3px] hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring [&_svg]:size-3.5 [&_svg]:transition-transform [&_svg]:duration-(--kg-duration-base) [&_svg]:ease-kg-spring aria-expanded:[&_svg]:rotate-180"
            aria-expanded={expanded}
            aria-controls={id}
            onClick={() => setExpanded((value) => !value)}
          >
            {expanded ? words.less : words.more}
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path
                d="M4 6l4 4 4-4"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.75"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        )}
      </div>
    )
  },
)
Clamp.displayName = "Clamp"

components/click-spark/click-spark.tsx:
"use client"

import { forwardRef, type HTMLAttributes, useEffect, useRef } from "react"
import { useReducedMotion } from "../../hooks/use-reduced-motion.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"

export interface ClickSparkProps extends HTMLAttributes<HTMLDivElement> {
  /** Lines per burst. */
  count?: number
  /** How far each line travels, in px. */
  radius?: number
  /** Length of each line at the start, in px. */
  size?: number
  /** Burst length, in ms. */
  duration?: number
}

interface Spark {
  x: number
  y: number
  angle: number
  born: number
}

/**
 * Wraps any content and throws a small burst of sparks from every press, drawn on a canvas
 * that sits above the content without intercepting events. Off under reduced motion.
 */
export const ClickSpark = forwardRef<HTMLDivElement, ClickSparkProps>(
  (
    { count = 8, radius = 22, size = 10, duration = 420, className, children, ...props },
    forwardedRef,
  ) => {
    const local = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(local, forwardedRef)
    const canvasRef = useRef<HTMLCanvasElement>(null)
    const reduced = useReducedMotion()

    useEffect(() => {
      const root = local.current
      const canvas = canvasRef.current
      const ctx = canvas?.getContext?.("2d")
      if (!root || !canvas || !ctx || reduced) return
      let sparks: Spark[] = []
      let frame = 0
      let color = ""

      const resize = () => {
        const rect = root.getBoundingClientRect()
        const dpr = window.devicePixelRatio || 1
        canvas.width = Math.max(1, Math.round(rect.width * dpr))
        canvas.height = Math.max(1, Math.round(rect.height * dpr))
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      }

      const draw = (now: number) => {
        ctx.clearRect(0, 0, canvas.width, canvas.height)
        ctx.strokeStyle = color
        ctx.lineWidth = 2
        ctx.lineCap = "round"
        sparks = sparks.filter((spark) => now - spark.born < duration)
        for (const spark of sparks) {
          const t = Math.max(now - spark.born, 0) / duration
          const eased = 1 - (1 - t) ** 3
          const distance = eased * radius
          const length = size * (1 - eased)
          const cos = Math.cos(spark.angle)
          const sin = Math.sin(spark.angle)
          ctx.beginPath()
          ctx.moveTo(spark.x + distance * cos, spark.y + distance * sin)
          ctx.lineTo(spark.x + (distance + length) * cos, spark.y + (distance + length) * sin)
          ctx.stroke()
        }
        frame = sparks.length ? requestAnimationFrame(draw) : 0
      }

      const press = (event: PointerEvent) => {
        if (event.button !== 0) return
        resize()
        color = getComputedStyle(canvas).color
        const rect = root.getBoundingClientRect()
        const born = performance.now()
        for (let i = 0; i < count; i++) {
          sparks.push({
            x: event.clientX - rect.left,
            y: event.clientY - rect.top,
            angle: (Math.PI * 2 * i) / count,
            born,
          })
        }
        if (!frame) frame = requestAnimationFrame(draw)
      }

      root.addEventListener("pointerdown", press)
      return () => {
        cancelAnimationFrame(frame)
        root.removeEventListener("pointerdown", press)
        ctx.clearRect(0, 0, canvas.width, canvas.height)
      }
    }, [reduced, count, radius, size, duration])

    return (
      <div ref={ref} className={cx("kg-click-spark relative", className)} {...props}>
        {children}
        <canvas ref={canvasRef} className="kg-click-spark__canvas pointer-events-none absolute inset-0 size-full text-[color:var(--kg-click-spark-color,var(--kg-ink))]" aria-hidden="true" />
      </div>
    )
  },
)

ClickSpark.displayName = "ClickSpark"

