}

const dateInputClass = cx(
  "tabular-nums",
  "[&_.kg-input__control::-webkit-datetime-edit]:p-0 [&_.kg-input__control::-webkit-datetime-edit-fields-wrapper]:p-0",
  "[&_.kg-input__control:invalid::-webkit-datetime-edit]:text-kg-fg-faint",
