"use client"

import { Fragment, forwardRef, type HTMLAttributes, type ReactNode, useMemo, useState } from "react"
import { cx } from "../../utils/cx.js"
import { type DiffViewLine, diffLines, inlineChange } from "./diff.js"

export type DiffViewMode = "unified" | "split"

export interface DiffViewLabels {
  added?: string
  removed?: string
  /** Text of the button that reveals hidden unchanged lines. */
  expand?: (count: number) => string
}

export interface DiffViewProps extends Omit<HTMLAttributes<HTMLDivElement>, "title"> {
  before: string
  after: string
  mode?: DiffViewMode
  /** Unchanged lines kept around each change. `Infinity` shows everything. */
  context?: number
  /** Header text, such as a file path. */
  title?: ReactNode
  /** Accessible name of the diff table. */
  caption?: string
  /** Highlights the changed span inside a modified line. */
  inline?: boolean
  labels?: DiffViewLabels
}

type Pair = { left?: DiffViewLine; right?: DiffViewLine }

type Block =
  | { kind: "lines"; lines: DiffViewLine[] }
  | { kind: "gap"; id: number; lines: DiffViewLine[] }

/** Folds long unchanged stretches into expandable gaps. */
const toBlocks = (lines: DiffViewLine[], context: number): Block[] => {
  if (!Number.isFinite(context)) return [{ kind: "lines", lines }]
  const keep = new Array<boolean>(lines.length).fill(false)
  lines.forEach((line, index) => {
    if (line.type === "equal") return
    for (let j = Math.max(0, index - context); j <= Math.min(lines.length - 1, index + context); j++)
      keep[j] = true
  })
  const blocks: Block[] = []
  let gapId = 0
  let index = 0
  while (index < lines.length) {
    const visible = keep[index] as boolean
    const run: DiffViewLine[] = []
    while (index < lines.length && keep[index] === visible) run.push(lines[index++] as DiffViewLine)
    if (visible || run.length < 2) blocks.push({ kind: "lines", lines: run })
    else blocks.push({ kind: "gap", id: gapId++, lines: run })
  }
  return blocks
}

/** Pairs consecutive removals with additions so split view lines them up. */
const toPairs = (lines: DiffViewLine[]): Pair[] => {
  const pairs: Pair[] = []
  let index = 0
  while (index < lines.length) {
    const line = lines[index] as DiffViewLine
    if (line.type === "equal") {
      pairs.push({ left: line, right: line })
      index++
      continue
    }
    const removed: DiffViewLine[] = []
    const added: DiffViewLine[] = []
    while (lines[index]?.type === "remove") removed.push(lines[index++] as DiffViewLine)
    while (lines[index]?.type === "add") added.push(lines[index++] as DiffViewLine)
    for (let j = 0; j < Math.max(removed.length, added.length); j++) {
      const pair: Pair = {}
      if (removed[j]) pair.left = removed[j]
      if (added[j]) pair.right = added[j]
      pairs.push(pair)
    }
  }
  return pairs
}

type CellType = DiffViewLine["type"] | "empty" | undefined

/* Night paper with success/danger tints; changed lines also carry a +/− marker and a spoken word. */
const ROW_FILL: Record<string, string> = {
  equal: "",
  add: "bg-[color-mix(in_oklab,var(--kg-success)_16%,transparent)]",
  remove: "bg-[color-mix(in_oklab,var(--kg-danger)_16%,transparent)]",
  empty: "bg-kg-surface-sunken",
}
const NUM_FILL: Record<string, string> = {
  equal: "bg-kg-surface-sunken",
  add: "bg-[color-mix(in_oklab,var(--kg-success)_26%,var(--kg-surface-sunken))]",
  remove: "bg-[color-mix(in_oklab,var(--kg-danger)_24%,var(--kg-surface-sunken))]",
  empty: "bg-kg-surface-sunken",
}
const SIGN_INK: Record<string, string> = {
  equal: "text-kg-fg-faint",
  add: "font-bold text-[color-mix(in_oklab,var(--kg-success)_85%,var(--kg-fg))]",
  remove: "font-bold text-[color-mix(in_oklab,var(--kg-danger)_85%,var(--kg-fg))]",
  empty: "",
}

/** A line-level diff of two strings, unified or side by side, computed in the browser. */
export const DiffView = forwardRef<HTMLDivElement, DiffViewProps>(
  (
    {
      before,
      after,
      mode = "unified",
      context = 3,
      title,
      caption = "Changes",
      inline = true,
      labels,
      className,
      ...props
    },
    ref,
  ) => {
    const lines = useMemo(() => diffLines(before, after), [before, after])
    const blocks = useMemo(() => toBlocks(lines, context), [lines, context])
    const [opened, setOpened] = useState<Set<number>>(() => new Set())
    const words = {
      added: "added",
      removed: "removed",
      expand: (count: number) => `${count} unchanged lines`,
      ...labels,
    }
    const additions = lines.filter((line) => line.type === "add").length
    const removals = lines.filter((line) => line.type === "remove").length

    /** Partner line for inline highlighting: the n-th removal pairs with the n-th addition. */
    const partners = useMemo(() => {
      const map = new Map<DiffViewLine, DiffViewLine>()
      for (const pair of toPairs(lines)) {
        if (pair.left && pair.right && pair.left !== pair.right) {
          map.set(pair.left, pair.right)
          map.set(pair.right, pair.left)
        }
      }
      return map
    }, [lines])

    const text = (line: DiffViewLine | undefined) => {
      if (!line) return null
      const partner = inline ? partners.get(line) : undefined
      if (!partner) return line.text || " "
      const parts =
        line.type === "remove"
          ? inlineChange(line.text, partner.text).from
          : inlineChange(partner.text, line.text).to
      return (
        <>
          {parts[0]}
          {parts[1] && <span
              className={cx(
                "kg-diff-view__word rounded-[2px]",
                line.type === "remove"
                  ? "bg-[color-mix(in_oklab,var(--kg-danger)_34%,transparent)] line-through decoration-[color-mix(in_oklab,var(--kg-danger)_70%,var(--kg-fg))]"
                  : "bg-[color-mix(in_oklab,var(--kg-success)_34%,transparent)]",
              )}
            >
              {parts[1]}
            </span>}
          {parts[2]}
        </>
      )
    }

    const sign = (line: DiffViewLine | undefined) =>
      !line || line.type === "equal" ? (
        <span aria-hidden="true"> </span>
      ) : (
        <>
          <span aria-hidden="true">{line.type === "add" ? "+" : "\u2212"}</span>
          <span className="kg-diff-view__sr sr-only">
            {line.type === "add" ? words.added : words.removed}
          </span>
        </>
      )

    const columns = mode === "split" ? 6 : 4
    const split = mode === "split"
    const num = (type: CellType, right?: boolean) =>
      cx(
        "kg-diff-view__num w-12 px-2 text-end align-top text-kg-fg-faint select-none",
        NUM_FILL[type ?? "equal"],
        right && "border-s border-kg-border",
      )
    const signCell = (type: CellType) =>
      cx(
        "kg-diff-view__sign w-6 ps-2 align-top select-none",
        ROW_FILL[type ?? "equal"],
        SIGN_INK[type ?? "equal"],
      )
    const code = (type: CellType) =>
      cx(
        "kg-diff-view__code pe-4",
        split ? "[overflow-wrap:anywhere] whitespace-pre-wrap" : "whitespace-pre",
        ROW_FILL[type ?? "equal"],
      )

    const renderLines = (chunk: DiffViewLine[]) =>
      mode === "split"
        ? toPairs(chunk).map((pair, index) => (
            <tr key={index} className="kg-diff-view__row">
              <td className={num(pair.left?.type)} data-type={pair.left?.type} aria-hidden="true">
                {pair.left?.oldNumber}
              </td>
              <td className={signCell(pair.left?.type ?? "empty")} data-type={pair.left?.type ?? "empty"}>
                {sign(pair.left)}
              </td>
              <td className={code(pair.left?.type ?? "empty")} data-type={pair.left?.type ?? "empty"}>
                {text(pair.left)}
              </td>
              <td className={num(pair.right?.type, true)} data-type={pair.right?.type} data-side="right" aria-hidden="true">
                {pair.right?.newNumber}
              </td>
              <td className={signCell(pair.right?.type ?? "empty")} data-type={pair.right?.type ?? "empty"}>
                {sign(pair.right)}
              </td>
              <td className={code(pair.right?.type ?? "empty")} data-type={pair.right?.type ?? "empty"}>
                {text(pair.right)}
              </td>
            </tr>
          ))
        : chunk.map((line, index) => (
            <tr key={index} className="kg-diff-view__row" data-type={line.type}>
              <td className={num(line.type)} data-type={line.type} aria-hidden="true">
                {line.oldNumber}
              </td>
              <td className={num(line.type)} data-type={line.type} aria-hidden="true">
                {line.newNumber}
              </td>
              <td className={signCell(line.type)} data-type={line.type}>
                {sign(line)}
              </td>
              <td className={code(line.type)} data-type={line.type}>
                {text(line)}
              </td>
            </tr>
          ))

    return (
      <div
        ref={ref}
        className={cx(
          "kg-diff-view grid min-w-0 overflow-hidden rounded-kg-xl border-2 border-kg-ink bg-kg-bg shadow-kg-sm",
          className,
        )}
        data-mode={mode}
        {...props}
      >
        {title != null && (
          <div
            data-theme="dark"
            className="kg-diff-view__header flex items-center gap-2 border-b-2 border-kg-border bg-kg-surface px-4 py-2.5 text-kg-xs text-kg-fg"
          >
            <span className="kg-diff-view__title min-w-0 flex-1 overflow-hidden font-kg-mono font-medium text-ellipsis whitespace-nowrap">
              {title}
            </span>
            <span
              className="kg-diff-view__stat font-kg-mono font-semibold text-[color-mix(in_oklab,var(--kg-success)_80%,var(--kg-fg))]"
              data-type="add"
            >
              +{additions}
            </span>
            <span
              className="kg-diff-view__stat font-kg-mono font-semibold text-[color-mix(in_oklab,var(--kg-danger)_80%,var(--kg-fg))]"
              data-type="remove"
            >
              {"\u2212"}
              {removals}
            </span>
          </div>
        )}
        {/* biome-ignore lint/a11y/noNoninteractiveTabindex: scrollable regions must be keyboard reachable. */}
        <div
          data-theme="dark"
          className="kg-diff-view__scroll overflow-auto bg-kg-bg text-kg-fg [scrollbar-width:thin] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-kg-ring"
          tabIndex={0}
        >
          <table
            className={cx(
              "kg-diff-view__table w-full border-collapse font-kg-mono text-kg-xs leading-[1.7]",
              split && "table-fixed",
            )}
          >
            <caption className="kg-diff-view__sr sr-only">{caption}</caption>
            <tbody>
              {blocks.map((block, index) =>
                block.kind === "lines" || opened.has(block.id) ? (
                  <Fragment key={index}>{renderLines(block.lines)}</Fragment>
                ) : (
                  <tr key={index} className="kg-diff-view__gap">
                    <td colSpan={columns} className="bg-kg-surface-sunken p-0">
                      <button
                        type="button"
                        className="kg-diff-view__expand flex w-full cursor-pointer items-center gap-2 border-0 bg-transparent px-4 py-1 text-start text-kg-fg-muted [font:inherit] hover:bg-kg-muted hover:text-kg-fg focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-kg-ring [&_svg]:size-3.5"
                        onClick={() =>
                          setOpened((current) => new Set(current).add(block.id))
                        }
                      >
                        <svg viewBox="0 0 16 16" aria-hidden="true">
                          <path
                            d="M5 6l3-3 3 3M5 10l3 3 3-3"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="1.5"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                          />
                        </svg>
                        {words.expand(block.lines.length)}
                      </button>
                    </td>
                  </tr>
                ),
              )}
            </tbody>
          </table>
        </div>
      </div>
    )
  },
)
DiffView.displayName = "DiffView"

components/diff-view/diff.ts:
export type DiffViewLineType = "equal" | "add" | "remove"

export interface DiffViewLine {
  type: DiffViewLineType
  text: string
  /** 1-based line in the old text; absent for additions. */
  oldNumber?: number
  /** 1-based line in the new text; absent for removals. */
  newNumber?: number
}

const splitLines = (text: string) => (text === "" ? [] : text.replace(/\n$/, "").split("\n"))

/**
 * Myers' O(ND) shortest edit script over lines. Keeps a copy of the frontier per step so the
 * path can be walked back; memory is O(D²), fine for review-sized inputs.
 */
export const diffLines = (before: string, after: string): DiffViewLine[] => {
  const a = splitLines(before)
  const b = splitLines(after)
  const n = a.length
  const m = b.length
  const max = n + m
  const offset = max + 1
  let v = new Int32Array(2 * max + 3)
  const trace: Int32Array[] = []

  outer: for (let d = 0; d <= max; d++) {
    trace.push(v.slice())
    const next = v.slice()
    for (let k = -d; k <= d; k += 2) {
      const down = k === -d || (k !== d && (v[offset + k - 1] as number) < (v[offset + k + 1] as number))
      let x = down ? (v[offset + k + 1] as number) : (v[offset + k - 1] as number) + 1
      let y = x - k
      while (x < n && y < m && a[x] === b[y]) {
        x++
        y++
      }
      next[offset + k] = x
      if (x >= n && y >= m) {
        trace.push(next)
        break outer
      }
    }
    v = next
  }

  const out: DiffViewLine[] = []
  let x = n
  let y = m
  for (let d = trace.length - 2; d >= 0; d--) {
    const frontier = trace[d] as Int32Array
    const k = x - y
    const down =
      k === -d || (k !== d && (frontier[offset + k - 1] as number) < (frontier[offset + k + 1] as number))
    const prevK = down ? k + 1 : k - 1
    const prevX = d === 0 ? 0 : (frontier[offset + prevK] as number)
    const prevY = d === 0 ? 0 : prevX - prevK
    while (x > prevX && y > prevY) {
      out.push({ type: "equal", text: a[x - 1] as string, oldNumber: x, newNumber: y })
      x--
      y--
    }
    if (d === 0) break
    if (down) {
      out.push({ type: "add", text: b[y - 1] as string, newNumber: y })
      y--
    } else {
      out.push({ type: "remove", text: a[x - 1] as string, oldNumber: x })
      x--
    }
  }
  return out.reverse()
}

/** Splits a changed pair into common prefix, changed middle and common suffix. */
export const inlineChange = (from: string, to: string) => {
  let start = 0
  const limit = Math.min(from.length, to.length)
  while (start < limit && from[start] === to[start]) start++
  let end = 0
  while (
    end < limit - start &&
    from[from.length - 1 - end] === to[to.length - 1 - end]
  )
    end++
  return {
    from: [from.slice(0, start), from.slice(start, from.length - end), from.slice(from.length - end)],
    to: [to.slice(0, start), to.slice(start, to.length - end), to.slice(to.length - end)],
  } as { from: [string, string, string]; to: [string, string, string] }
}

components/dither/dither.tsx:
"use client"

import { forwardRef, type HTMLAttributes, type ReactNode, useRef } from "react"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { backdropRoot, hasChildren } from "../aurora/internal/backdrop.js"
import { useCanvasStage } from "../backdrop-kit/stage.js"

export interface DitherProps extends HTMLAttributes<HTMLDivElement> {
  /** Any CSS color for lit pixels. Defaults to ink. */
  color?: string
  /** Size of one dither pixel, in CSS px (2–12). */
  pixelSize?: number
  /** Size of the flowing shapes; larger is broader. */
  scale?: number
  /** Flow speed multiplier; 0 holds the field still. */
  speed?: number
  /** Brighten the field around the pointer. */
  interactive?: boolean
  children?: ReactNode
}

/** 8×8 Bayer threshold matrix, normalised to 0–1. */
const BAYER = (() => {
  const m = [0, 2, 3, 1]
  let size = 2
  let matrix = m
  while (size < 8) {
    const next: number[] = new Array(size * size * 4)
    for (let y = 0; y < size * 2; y++) {
      for (let x = 0; x < size * 2; x++) {
        const base = (matrix[(y % size) * size + (x % size)] as number) * 4
        const quadrant = (m[(y >= size ? 2 : 0) + (x >= size ? 1 : 0)] as number)
        next[y * size * 2 + x] = base + quadrant
      }
    }
    matrix = next
    size *= 2
  }
  return matrix.map((v) => (v + 0.5) / 64)
})()

/**
 * A flowing gradient field rendered through an ordered (Bayer) dither at a coarse pixel size,
 * like a print or an early screen. Three tones, written straight into an ImageData buffer at
 * the dither resolution, so it costs a fraction of a full-resolution canvas.
 */
export const Dither = forwardRef<HTMLDivElement, DitherProps>(
  (
    {
      color = "var(--kg-ink)",
      pixelSize = 3,
      scale = 1,
      speed = 1,
      interactive = true,
      className,
      children,
      ...props
    },
    forwardedRef,
  ) => {
    const root = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(root, forwardedRef)
    const canvasRef = useRef<HTMLCanvasElement>(null)
    const wrapper = hasChildren(children)
    const pixel = Math.min(Math.max(Math.round(pixelSize), 2), 12)
    const buffer = useRef<ImageData | null>(null)

    useCanvasStage(root, canvasRef, {
      dprCap: 1,
      scale: 1 / pixel,
      pointer: interactive,
      deps: [pixel],
      draw: ({ ctx, width, pixelWidth: w, pixelHeight: h, time, pointer, color: resolve }) => {
        if (!buffer.current || buffer.current.width !== w || buffer.current.height !== h) {
          buffer.current = ctx.createImageData(w, h)
        }
        const image = buffer.current
        const data = image.data
        const c = resolve(color)
        const full = Math.round(c.a * 255)
        const half = Math.round(c.a * 120)
        const t = (time / 1000) * speed
        const k = 1 / Math.max(scale, 0.1)
        const aspect = w / Math.max(h, 1)
        const ratio = w / Math.max(width, 1)
        const px = pointer.x * ratio
        const py = pointer.y * ratio
        const reach = (Math.min(w, h) * 0.35) ** 2
        const rowA = new Float32Array(h)
        const rowB = new Float32Array(h)
        for (let y = 0; y < h; y++) {
          const v = y / h
          rowA[y] = Math.cos(v * 2.6 * k - t * 0.4)
          rowB[y] = 1 - v
        }
        for (let x = 0; x < w; x++) {
          const u = (x / w) * aspect
          const colA = Math.sin(u * 2.2 * k + t * 0.55)
          const colB = Math.sin(u * 1.3 * k - t * 0.3)
          for (let y = 0; y < h; y++) {
            let value =
              0.5 +
              0.3 * colA * (rowA[y] as number) +
              0.2 * Math.sin(colB * 2 + (rowB[y] as number) * 3.2 * k + t * 0.7)
            value = value * 0.7 + (rowB[y] as number) * 0.25 - 0.28
            if (pointer.inside) {
              const dx = x - px
              const dy = y - py
              value += 0.5 * Math.exp(-(dx * dx + dy * dy) / reach)
            }
            const threshold = BAYER[(y & 7) * 8 + (x & 7)] as number
            const level = value * 2
            const index = (y * w + x) * 4
            const alpha =
              level - 1 > threshold ? full : level > threshold ? half : 0
            data[index] = c.r
            data[index + 1] = c.g
            data[index + 2] = c.b
            data[index + 3] = alpha
          }
        }
        ctx.putImageData(image, 0, 0)
      },
    })

    return (
      <div ref={ref} {...backdropRoot("kg-dither absolute inset-0 overflow-hidden pointer-events-none data-wrapper:relative data-wrapper:inset-auto data-wrapper:isolate data-wrapper:pointer-events-auto", className, wrapper)} {...props}>
        <div className="kg-dither__layer pointer-events-none absolute inset-0 z-0 overflow-hidden" aria-hidden="true">
          <canvas ref={canvasRef} className="kg-dither__canvas block size-full [image-rendering:pixelated]" />
        </div>
        {wrapper && <div className="kg-dither__content relative z-1">{children}</div>}
      </div>
    )
  },
)

Dither.displayName = "Dither"

components/dock/dock.css:
/*
 * The backdrop is pre-sized for the widest the row can get and clipped back to the resting size;
 * JS opens the clip by --_grow. Clip-paths on pseudo-elements do not fit in utilities.
 */
@layer kg.components {
  .kg-dock__backdrop {
    &::before,
    &::after {
      --_clip: max(0px, calc(var(--_reserve, 0px) - var(--_grow, 0px)));

      content: "";
      position: absolute;
      inset: 0;
    }

    &::before {
      background: var(--kg-ink);
      clip-path: inset(0 var(--_clip) round var(--_radius));
    }

    &::after {
      background: var(--kg-surface);
      clip-path: inset(2px calc(var(--_clip) + 2px) round calc(var(--_radius) - 2px));
    }

    [data-orientation="vertical"] > & {
      &::before {
        clip-path: inset(var(--_clip) 0 round var(--_radius));
      }

      &::after {
        clip-path: inset(calc(var(--_clip) + 2px) 2px round calc(var(--_radius) - 2px));
      }
    }
  }
}

components/dock/dock.tsx:
"use client"

import {
  type ButtonHTMLAttributes,
  type CSSProperties,
  createContext,
  type FocusEvent as ReactFocusEvent,
  forwardRef,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
  useContext,
  useEffect,
  useId,
  useRef,
} from "react"
import { useIsomorphicLayoutEffect } from "../../hooks/use-isomorphic-layout-effect.js"
import { useReducedMotion } from "../../hooks/use-reduced-motion.js"
import { ROVING_ITEM_SELECTOR, useRovingFocus } from "../../hooks/use-roving-focus.js"
import { createSpring } from "../../hooks/use-spring.js"
import { Slot } from "../../primitives/slot.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"

export type DockOrientation = "horizontal" | "vertical"

export interface DockProps extends HTMLAttributes<HTMLDivElement> {
  /** Scale of the item right under the pointer. 1 turns magnification off. */
  magnification?: number
  /** How far from the pointer items still grow, in px. */
  distance?: number
  /** Resting item size, in px. */
  baseSize?: number
  orientation?: DockOrientation
  /** Accessible name of the toolbar. */
  label?: string
}

export interface DockItemProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Shown as a tooltip on hover and focus, and used as the accessible name. */
  label: string
  icon?: ReactNode
  /** Shows the indicator dot, e.g. for an open app or the current page. */
  active?: boolean
  /** Render the child element (e.g. a link) as the item instead of a <button>. */
  asChild?: boolean
}

export type DockSeparatorProps = HTMLAttributes<HTMLDivElement>

const OrientationContext = createContext<DockOrientation>("horizontal")

interface Part {
  node: HTMLElement
  item: boolean
  center: number
}

/** Cosine falloff: 1 under the pointer, easing to 0 at `distance`. */
const falloff = (offset: number, distance: number) =>
  offset >= distance ? 0 : (Math.cos((offset / distance) * Math.PI) + 1) / 2

/**
 * A macOS-style dock. Items grow with pointer proximity through springs; neighbours are pushed
 * aside with transforms, and the backdrop widens with a clip-path, so nothing triggers layout.
 */
export const Dock = forwardRef<HTMLDivElement, DockProps>(
  (
    {
      magnification = 1.8,
      distance = 140,
      baseSize = 48,
      orientation = "horizontal",
      label,
      className,
      style,
      onKeyDown,
      children,
      ...props
    },
    forwardedRef,
  ) => {
    const local = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(local, forwardedRef)
    const backdrop = useRef<HTMLSpanElement>(null)
    const reduced = useReducedMotion()
    const vertical = orientation === "vertical"
    const roving = useRovingFocus({ orientation })
    const enabled = !reduced && magnification > 1
    // Upper bound on how far the row can grow per side, so the backdrop is pre-sized for it.
    const reserve = Math.max(0, ((magnification - 1) * (distance + baseSize)) / 2)

    // A toolbar is a single tab stop: only the most recently focused item is tabbable.
    useIsomorphicLayoutEffect(() => {
      const node = local.current
      if (!node) return
      const items = Array.from(node.querySelectorAll<HTMLElement>(ROVING_ITEM_SELECTOR))
      const current =
        items.find((item) => item.dataset.dockCurrent !== undefined) ?? items[0]
      for (const item of items) item.tabIndex = item === current ? 0 : -1
    })

    const handleFocus = (event: ReactFocusEvent<HTMLDivElement>) => {
      const target = event.target as HTMLElement
      if (!target.matches(ROVING_ITEM_SELECTOR)) return
      const items =
        event.currentTarget.querySelectorAll<HTMLElement>(ROVING_ITEM_SELECTOR)
      for (const item of items) {
        if (item === target) {
          item.dataset.dockCurrent = ""
          item.tabIndex = 0
        } else {
          delete item.dataset.dockCurrent
          item.tabIndex = -1
        }
      }
    }

    const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(event)
      if (!event.defaultPrevented) roving(event)
    }

    useEffect(() => {
      const node = local.current
      if (!node || !enabled) return
      let parts: Part[] = []

      const measure = () => {
        const found = node.querySelectorAll<HTMLElement>(":scope > [data-dock-part]")
        parts = Array.from(found, (part) => ({
          node: part,
          item: part.dataset.dockPart === "item",
          // Offsets ignore transforms, so these are the resting centres.
          center: vertical
            ? part.offsetTop + part.offsetHeight / 2
            : part.offsetLeft + part.offsetWidth / 2,
        }))
      }

      const write = () => {
        const at = pointer.get()
        const amount = engage.get()
        let total = 0
        const extras = parts.map((part) => {
          if (!part.item) return 0
          const proximity = falloff(Math.abs(at - part.center), distance)
          const scale = 1 + (magnification - 1) * proximity * amount
          part.node.style.setProperty("--_s", scale.toFixed(4))
          const extra = (scale - 1) * baseSize
          total += extra
          return extra
        })
        // Each part shifts by the growth before it, re-centred so the row grows both ways.
        let before = 0
        parts.forEach((part, index) => {
          const extra = extras[index] ?? 0
          const offset = before + extra / 2 - total / 2
          part.node.style.setProperty("--_offset", `${offset.toFixed(2)}px`)
          before += extra
        })
        backdrop.current?.style.setProperty("--_grow", `${(total / 2).toFixed(2)}px`)
      }

      const pointer = createSpring(0, write, {
        stiffness: 320,
        damping: 32,
        precision: 0.1,
      })
      const engage = createSpring(0, write, {
        stiffness: 240,
        damping: 26,
        precision: 0.002,
      })

      const track = (position: number) => {
        // Arriving from outside: start under the pointer, not sweeping in from the last spot.
        if (engage.get() < 0.02) pointer.jump(position)
        else pointer.set(position)
        engage.set(1)
      }

      const handleMove = (event: PointerEvent) => {
        if (event.pointerType === "touch") return
        const box = node.getBoundingClientRect()
        track(
          vertical
            ? event.clientY - box.top - node.clientTop
            : event.clientX - box.left - node.clientLeft,
        )
      }
      const handleEnter = (event: PointerEvent) => {
        if (event.pointerType !== "touch") measure()
      }
      const release = () => engage.set(0)
      const handleFocusIn = (event: FocusEvent) => {
        const target = event.target as HTMLElement
        if (!target.matches(":focus-visible")) return
        const part = target.closest<HTMLElement>("[data-dock-part]")
        measure()
        const match = parts.find((entry) => entry.node === part)
        if (match) track(match.center)
      }
      const handleFocusOut = (event: FocusEvent) => {
        if (!node.contains(event.relatedTarget as Node | null)) release()
      }

      measure()
      node.addEventListener("pointerenter", handleEnter)
      node.addEventListener("pointermove", handleMove, { passive: true })
      node.addEventListener("pointerleave", release)
      node.addEventListener("focusin", handleFocusIn)
      node.addEventListener("focusout", handleFocusOut)
      return () => {
        pointer.stop()
        engage.stop()
        node.removeEventListener("pointerenter", handleEnter)
        node.removeEventListener("pointermove", handleMove)
        node.removeEventListener("pointerleave", release)
        node.removeEventListener("focusin", handleFocusIn)
        node.removeEventListener("focusout", handleFocusOut)
        for (const part of parts) {
          part.node.style.removeProperty("--_s")
          part.node.style.removeProperty("--_offset")
        }
        backdrop.current?.style.removeProperty("--_grow")
      }
    }, [enabled, vertical, magnification, distance, baseSize])

    return (
      <OrientationContext.Provider value={orientation}>
        <div
          ref={ref}
          role="toolbar"
          aria-label={label}
          aria-orientation={orientation}
          className={cx(
            "kg-dock relative isolate inline-flex items-end gap-[var(--kg-dock-gap,calc(var(--kg-space)*2.5))] p-2 data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-start",
            "[--_radius:var(--kg-dock-radius,calc(var(--kg-dock-size)*0.36+var(--kg-space)*2))]",
            className,
          )}
          data-orientation={orientation}
          data-magnify={enabled || undefined}
          style={
            {
              "--kg-dock-size": `${baseSize}px`,
              "--_reserve": `${reserve.toFixed(1)}px`,
              ...style,
            } as CSSProperties
          }
          onKeyDown={handleKeyDown}
          onFocus={handleFocus}
          {...props}
        >
          <span
            ref={backdrop}
            className={cx(
              "kg-dock__backdrop pointer-events-none absolute -z-1 drop-shadow-[4px_4px_0_var(--kg-ink)]",
              vertical
                ? "inset-x-0 inset-y-[calc(var(--_reserve,0px)*-1)]"
                : "inset-y-0 inset-x-[calc(var(--_reserve,0px)*-1)]",
            )}
            aria-hidden="true"
          />
          {children}
        </div>
      </OrientationContext.Provider>
    )
  },
)

Dock.displayName = "Dock"

export const DockItem = forwardRef<HTMLButtonElement, DockItemProps>(
