        "[scale:var(--_s,1)] transition-colors duration-(--kg-duration-fast) ease-kg-out interactive:hover:bg-kg-paper-sage",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
