              : "bottom-full left-1/2 [translate:-50%_calc((var(--_s,1)-1)*var(--kg-dock-size)*-1-var(--kg-space)*2.5)]",
          )}
        >
          {label}
        </span>
        {active && (
          <span
            className={cx(
