                ? "top-1/2 left-[calc(var(--kg-space)*-1-2px)] -translate-y-1/2"
                : "bottom-[calc(var(--kg-space)*-1-2px)] left-1/2 -translate-x-1/2",
            )}
            aria-hidden="true"
          />
        )}
