      onSelect,
      closeOnSelect = true,
      textValue,
      onClick,
      onPointerMove,
      onPointerLeave,
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const behaviour = useItemBehaviour("DropdownMenuItem", {
      disabled,
      closeOnSelect,
      onSelect,
      onClick,
      onPointerMove,
      onPointerLeave,
    })
