"use client"

import {
  createContext,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  useContext,
  useId,
  useState,
} from "react"
import { cx } from "../../utils/cx.js"

export interface FieldContextValue {
  /** Id the control should put on its focusable element so the label targets it. */
  id: string
  /** Id of the rendered label, for controls a `<label for>` cannot name (groups, sliders). */
  labelId: string | undefined
  /** Space-separated ids of the description and, while invalid, the error message. */
  describedBy: string | undefined
  /** Id of the error message while one is shown, for `aria-errormessage`. */
  errorId: string | undefined
  invalid: boolean
  disabled: boolean
  required: boolean
}

/** @internal Composite controls reset it to `null` so their items don't claim the field id. */
export const FieldContext = createContext<FieldContextValue | null>(null)

/** The surrounding Field's wiring, or `null` outside one. Use it to build custom controls. */
export const useField = (): FieldContextValue | null => useContext(FieldContext)

export interface FieldProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  label?: ReactNode
  /** Helper text shown under the label and announced with the control. */
  description?: ReactNode
  /** Shown below the control. Any truthy value also marks the field invalid. */
  error?: ReactNode
  /** Marks the field invalid without a message, e.g. while the error is shown elsewhere. */
  invalid?: boolean
  required?: boolean
  disabled?: boolean
  /** Id for the control. Generated when omitted. */
  controlId?: string
  children?: ReactNode
}

// Danger pulled toward the text colour, so the message stays AA on the page as well as on sheets.
const errorClass = cx(
  "kg-field__error flex items-start gap-[0.4em] m-0 text-kg-sm font-medium leading-[1.45]",
  "text-[color-mix(in_oklab,var(--kg-danger),var(--kg-fg)_30%)]",
)

/** A glyph beside the text, so the state is never conveyed by colour alone. */
const ErrorIcon = () => (
  <svg
    className="kg-field__error-icon shrink-0 size-[1em] mt-[0.22em] text-kg-danger"
    viewBox="0 0 16 16"
    aria-hidden="true"
    focusable="false"
  >
    <circle cx="8" cy="8" r="8" fill="currentColor" />
    <path d="M8 4.2v4.6" stroke="var(--kg-danger-fg)" strokeWidth="1.8" strokeLinecap="round" />
    <circle cx="8" cy="11.6" r="1.1" fill="var(--kg-danger-fg)" />
  </svg>
)

const messageKey = (error: ReactNode): string =>
  typeof error === "string" || typeof error === "number" ? `m:${error}` : "message"

export const Field = forwardRef<HTMLDivElement, FieldProps>(
  (
    {
      label,
      description,
      error,
      invalid: invalidProp = false,
      required = false,
      disabled = false,
      controlId,
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const generated = useId()
    const id = controlId ?? `${generated}-control`
    const labelId = label != null ? `${generated}-label` : undefined
    const descriptionId = description != null ? `${generated}-description` : undefined
    const hasError = error != null && error !== false && error !== ""
    const errorId = hasError ? `${generated}-error` : undefined
    const invalid = invalidProp || hasError

    // Keeps the last message on screen while the region collapses, so the exit can animate.
    const [lastError, setLastError] = useState<ReactNode>(hasError ? error : null)
    if (hasError && error !== lastError) setLastError(error)

    const value: FieldContextValue = {
      id,
      labelId,
      describedBy: [descriptionId, errorId].filter(Boolean).join(" ") || undefined,
      errorId,
      invalid,
      disabled,
      required,
    }

    return (
      <div
        ref={ref}
        className={cx("kg-field grid gap-1.5 min-w-0 text-kg-fg", className)}
        data-invalid={invalid || undefined}
        data-disabled={disabled || undefined}
        {...props}
      >
        {label != null && (
          <label
            id={labelId}
            htmlFor={id}
            className={cx(
              "kg-field__label inline-flex items-baseline gap-[0.2em] justify-self-start cursor-default",
              "text-kg-sm font-semibold leading-[1.35] tracking-[-0.005em] text-kg-fg",
              disabled && "opacity-50",
            )}
          >
            {label}
            {required && (
              <span className="kg-field__required font-semibold text-kg-danger" aria-hidden="true">
                *
              </span>
            )}
          </label>
        )}
        {description != null && (
          <p
            id={descriptionId}
            className={cx(
              "kg-field__description m-0 -mt-0.5 text-kg-sm leading-[1.45] text-kg-fg-muted",
              disabled && "opacity-50",
            )}
          >
            {description}
          </p>
        )}
        <FieldContext.Provider value={value}>{children}</FieldContext.Provider>
        <div
          className={cx(
            "kg-field__error-region grid transition-[grid-template-rows,margin-top,opacity,visibility] duration-(--kg-duration-base) ease-kg-out",
            hasError ? "grid-rows-[1fr] mt-0 opacity-100 visible" : "grid-rows-[0fr] -mt-1.5 opacity-0 invisible",
          )}
          data-state={hasError ? "open" : "closed"}
          aria-live="polite"
        >
          <div className="kg-field__error-clip min-h-0 overflow-hidden">
            {hasError ? (
              // A new key per message remounts the node, so the live region announces it again.
              <p key={messageKey(error)} id={errorId} className={errorClass}>
                <ErrorIcon />
                {error}
              </p>
            ) : (
              lastError != null && (
                <p key="stale" className={errorClass} aria-hidden="true">
                  <ErrorIcon />
                  {lastError}
                </p>
              )
            )}
          </div>
        </div>
      </div>
    )
  },
)

Field.displayName = "Field"

interface FieldControlInput {
  id?: string | undefined
  disabled?: boolean | undefined
  required?: boolean | undefined
  invalid?: boolean | undefined
  "aria-describedby"?: string | undefined
  "aria-errormessage"?: string | undefined
}

export interface ResolvedFieldControl {
  id: string | undefined
  labelId: string | undefined
  disabled: boolean
  required: boolean
  invalid: boolean
  describedBy: string | undefined
  errorMessage: string | undefined
}

export const joinIds = (
  ...ids: (string | undefined | false | null)[]
): string | undefined => ids.filter(Boolean).join(" ") || undefined

/**
 * @internal Merges a control's own props with the surrounding Field. Explicit props win, ids
 * are concatenated so both the control's and the field's descriptions are announced.
 */
export const resolveFieldControl = (
  field: FieldContextValue | null,
  props: FieldControlInput,
): ResolvedFieldControl => {
  const invalid = props.invalid ?? field?.invalid ?? false
  return {
    id: props.id ?? field?.id,
    labelId: field?.labelId,
    disabled: props.disabled ?? field?.disabled ?? false,
    required: props.required ?? field?.required ?? false,
    invalid,
    describedBy: joinIds(field?.describedBy, props["aria-describedby"]),
    errorMessage: props["aria-errormessage"] ?? (invalid ? field?.errorId : undefined),
  }
}

components/file-dropzone/file-dropzone.t:
"use client"

import {
  type CSSProperties,
  type DragEvent as ReactDragEvent,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  useEffect,
  useId,
  useRef,
  useState,
} from "react"
import { cx } from "../../utils/cx.js"
import { XIcon } from "../combobox/internal.js"

export type FileDropzoneStatus = "uploading" | "done" | "error"

export interface FileDropzoneItem {
  id: string
  name: string
  /** Bytes. */
  size: number
  type?: string
  /** 0 to 100 while uploading. */
  progress?: number
  status?: FileDropzoneStatus
  error?: string
  previewUrl?: string
}

export type FileDropzoneRejectReason = "type" | "size" | "count"

export interface FileDropzoneRejection {
  file: File
  reason: FileDropzoneRejectReason
}

export interface FileDropzoneLabels {
  title: ReactNode
  /** Short constraint line, e.g. "PNG or JPG, up to 5 MB". */
  hint?: ReactNode
  dropping: ReactNode
  remove: (name: string) => string
  rejected: (reason: FileDropzoneRejectReason) => string
}

export interface FileDropzoneProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "onDrop" | "children"> {
  /** Same syntax as the input's `accept`: `image/*,.pdf`. */
  accept?: string
  multiple?: boolean
  /** Bytes. */
  maxSize?: number
  maxFiles?: number
  onFilesAccepted?: (files: File[]) => void
  onFilesRejected?: (rejections: FileDropzoneRejection[]) => void
  /** Rows to show. Pass them to drive progress yourself; leave unset to list accepted files. */
  items?: readonly FileDropzoneItem[]
  onRemove?: (id: string) => void
  labels?: Partial<FileDropzoneLabels>
  disabled?: boolean
  name?: string
  /** Extra content inside the drop target, below the title. */
  children?: ReactNode
}

const defaultLabels: FileDropzoneLabels = {
  title: "Drop files or browse",
  dropping: "Release to add",
  remove: (name) => `Remove ${name}`,
  rejected: (reason) =>
    reason === "type" ? "File type not allowed" : reason === "size" ? "File too large" : "Too many files",
}

const units = ["B", "KB", "MB", "GB"]
export const formatBytes = (bytes: number): string => {
  let value = bytes
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit++
  }
  return `${value >= 10 || unit === 0 ? Math.round(value) : value.toFixed(1)} ${units[unit]}`
}

export const matchesAccept = (file: { name: string; type: string }, accept?: string): boolean => {
  if (!accept) return true
  const name = file.name.toLowerCase()
  const type = file.type.toLowerCase()
  return accept
    .split(",")
    .map((rule) => rule.trim().toLowerCase())
    .filter(Boolean)
    .some((rule) =>
      rule.startsWith(".")
        ? name.endsWith(rule)
        : rule.endsWith("/*")
          ? type.startsWith(rule.slice(0, -1))
          : type === rule,
    )
}

const UploadIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true">
    <path d="M12 15V4m0 0L8 8m4-4 4 4" strokeLinecap="round" strokeLinejoin="round" />
    <path d="M4 15v3a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-3" strokeLinecap="round" />
  </svg>
)

const FileIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true">
    <path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8l-5-5Z" strokeLinejoin="round" />
    <path d="M14 3v5h5" strokeLinejoin="round" />
  </svg>
)

let counter = 0

const errorText = "text-[color-mix(in_oklab,var(--kg-danger),var(--kg-fg)_30%)]"
const focusRing =
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring"

/**
 * A drop target with a real button for browsing, type and size checks, image previews and a
 * progress row per file. Drive `items` to show upload progress from your own uploader.
 */
export const FileDropzone = forwardRef<HTMLDivElement, FileDropzoneProps>(
  (
    {
      accept,
      multiple = true,
      maxSize,
      maxFiles,
      onFilesAccepted,
      onFilesRejected,
      items: itemsProp,
      onRemove,
      labels: labelsProp,
      disabled = false,
      name,
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const labels = { ...defaultLabels, ...labelsProp }
    const inputRef = useRef<HTMLInputElement>(null)
    const [dragging, setDragging] = useState<"accept" | "reject" | null>(null)
    const [own, setOwn] = useState<FileDropzoneItem[]>([])
    const [notice, setNotice] = useState("")
    const depth = useRef(0)
    const urls = useRef(new Set<string>())
    const hintId = useId()
    const items = itemsProp ?? own

    useEffect(
      () => () => {
        for (const url of urls.current) URL.revokeObjectURL(url)
      },
      [],
    )

    const take = (list: FileList | null) => {
      if (!list || disabled) return
      const accepted: File[] = []
      const rejected: FileDropzoneRejection[] = []
      const room = maxFiles === undefined ? Number.POSITIVE_INFINITY : maxFiles - items.length
      for (const file of Array.from(list)) {
        if (!matchesAccept(file, accept)) rejected.push({ file, reason: "type" })
        else if (maxSize !== undefined && file.size > maxSize) rejected.push({ file, reason: "size" })
        else if (accepted.length >= room || (!multiple && accepted.length >= 1))
          rejected.push({ file, reason: "count" })
        else accepted.push(file)
      }
      if (accepted.length) {
        onFilesAccepted?.(accepted)
        if (itemsProp === undefined) {
          const rows = accepted.map((file) => {
            const previewUrl =
              file.type.startsWith("image/") && typeof URL.createObjectURL === "function"
                ? URL.createObjectURL(file)
                : undefined
            if (previewUrl) urls.current.add(previewUrl)
            return {
              id: `file-${++counter}`,
              name: file.name,
              size: file.size,
              type: file.type,
              status: "done" as const,
              previewUrl,
            }
          })
          setOwn((prev) => (multiple ? [...prev, ...rows] : rows))
        }
      }
      if (rejected.length) onFilesRejected?.(rejected)
      const first = rejected[0]
      setNotice(first ? `${first.file.name}: ${labels.rejected(first.reason)}` : "")
    }

    const remove = (item: FileDropzoneItem) => {
      onRemove?.(item.id)
      if (itemsProp !== undefined) return
      if (item.previewUrl) {
        URL.revokeObjectURL(item.previewUrl)
        urls.current.delete(item.previewUrl)
      }
      setOwn((prev) => prev.filter((row) => row.id !== item.id))
    }

    const dragProps = {
      onDragEnter: (event: ReactDragEvent<HTMLDivElement>) => {
        if (disabled || !event.dataTransfer.types.includes("Files")) return
        event.preventDefault()
        depth.current++
        const types = Array.from(event.dataTransfer.items ?? []).map((item) => item.type)
        const ok = types.length === 0 || types.every((type) => matchesAccept({ name: "", type }, accept) || !type)
        setDragging(ok || !accept ? "accept" : "reject")
      },
      onDragOver: (event: ReactDragEvent<HTMLDivElement>) => {
        if (disabled) return
        event.preventDefault()
        event.dataTransfer.dropEffect = "copy"
      },
      // Child elements fire their own enter and leave, so count depth instead of trusting one.
      onDragLeave: () => {
        depth.current = Math.max(0, depth.current - 1)
        if (depth.current === 0) setDragging(null)
      },
      onDrop: (event: ReactDragEvent<HTMLDivElement>) => {
        event.preventDefault()
        depth.current = 0
        setDragging(null)
        take(event.dataTransfer.files)
      },
    }

    return (
      <div
        ref={ref}
        className={cx("kg-file-dropzone grid gap-2 w-full data-disabled:opacity-50", className)}
        data-disabled={disabled || undefined}
        {...props}
      >
        <div
          className={cx(
            "kg-file-dropzone__target relative grid justify-items-center gap-1.5 px-5 py-8 text-center",
            "bg-kg-surface border-2 border-dashed border-kg-ink rounded-kg-xl",
            "transition-[background-color,border-color,box-shadow] duration-(--kg-duration-base) ease-kg-out",
            "has-[>button:enabled:hover]:shadow-kg-sm",
            "data-[dragging=accept]:border-solid data-[dragging=accept]:bg-kg-paper-sage data-[dragging=accept]:shadow-kg-md",
            "data-[dragging=reject]:border-solid data-[dragging=reject]:border-kg-danger data-[dragging=reject]:bg-kg-paper-rose",
            "data-[dragging=reject]:shadow-[5px_5px_0_var(--kg-danger)]",
          )}
          data-dragging={dragging ?? undefined}
          {...dragProps}
        >
          <span
            className={cx(
              "kg-file-dropzone__orbit grid place-items-center size-11 mb-1 [&_svg]:size-5",
              "text-kg-fg bg-kg-surface border-2 border-kg-ink rounded-full shadow-kg-xs",
              "transition-[translate,rotate] duration-(--kg-duration-base) ease-kg-spring",
              "[[data-dragging=accept]>&]:-translate-y-1 [[data-dragging=accept]>&]:-rotate-8",
            )}
            aria-hidden="true"
          >
            <UploadIcon />
          </span>
          <button
            type="button"
            className={cx(
              "kg-file-dropzone__browse p-0 border-0 bg-transparent rounded-kg-xs cursor-pointer [font-family:inherit]",
              "text-kg-base font-semibold text-kg-fg underline-offset-[0.25em] interactive:hover:underline",
              // The whole target is clickable; the button stays the single focus stop.
              "after:absolute after:inset-0 after:rounded-kg-xl",
              "focus-visible:outline-none focus-visible:after:outline-2 focus-visible:after:outline-offset-2 focus-visible:after:outline-kg-ring",
              "disabled:cursor-not-allowed",
            )}
            disabled={disabled}
            aria-describedby={labels.hint ? hintId : undefined}
            onClick={() => inputRef.current?.click()}
          >
            {dragging ? labels.dropping : labels.title}
          </button>
          {labels.hint && (
            <span id={hintId} className="kg-file-dropzone__hint text-kg-sm text-kg-fg-muted">
              {labels.hint}
            </span>
          )}
          {children}
          <input
            ref={inputRef}
            type="file"
            tabIndex={-1}
            hidden
            name={name}
            accept={accept}
            multiple={multiple}
            disabled={disabled}
            onChange={(event) => {
              take(event.target.files)
              event.target.value = ""
            }}
          />
        </div>
        <p className={cx("kg-file-dropzone__notice m-0 text-kg-xs empty:hidden", errorText)} role="status">
          {notice}
        </p>
        {items.length > 0 && (
          <ul className="kg-file-dropzone__list grid gap-2 m-0 p-0 list-none">
            {items.map((item) => (
              <li
                key={item.id}
                className={cx(
                  "kg-file-dropzone__item flex items-center gap-3 p-2.5",
                  "bg-kg-surface border-2 border-kg-ink rounded-kg-lg shadow-kg-xs",
                  "animate-[kg-pop-in_var(--kg-duration-base)_var(--kg-ease-out)]",
                  "data-[status=error]:border-kg-danger data-[status=error]:shadow-[2px_2px_0_var(--kg-danger)]",
                )}
                data-status={item.status ?? (item.progress !== undefined ? "uploading" : "done")}
              >
                <span
                  className={cx(
                    "kg-file-dropzone__thumb grid place-items-center shrink-0 size-10 overflow-hidden",
                    "text-kg-fg-muted bg-kg-muted rounded-kg-md",
                    "[&_img]:size-full [&_img]:object-cover [&_svg]:size-[1.125rem]",
                  )}
                  aria-hidden="true"
                >
                  {item.previewUrl ? <img src={item.previewUrl} alt="" /> : <FileIcon />}
                </span>
                <span className="kg-file-dropzone__meta grid gap-[0.2rem] flex-1 min-w-0">
                  <span className="kg-file-dropzone__name truncate text-kg-sm font-[550]">{item.name}</span>
                  <span
                    className={cx(
                      "kg-file-dropzone__detail text-kg-xs tabular-nums text-kg-fg-muted",
                      "[[data-status=error]_&]:text-[color-mix(in_oklab,var(--kg-danger),var(--kg-fg)_30%)]",
                    )}
                  >
                    {item.status === "error" && item.error ? item.error : formatBytes(item.size)}
                    {item.status === "uploading" && item.progress !== undefined && (
                      <span className="kg-file-dropzone__percent">{` ${Math.round(item.progress)}%`}</span>
                    )}
                  </span>
                  {item.status === "uploading" && (
                    <span
                      role="progressbar"
                      aria-label={`${item.name} upload`}
                      aria-valuemin={0}
                      aria-valuemax={100}
                      aria-valuenow={item.progress === undefined ? undefined : Math.round(item.progress)}
                      className={cx(
                        "kg-file-dropzone__progress relative block h-1.5 mt-0.5 overflow-hidden bg-kg-muted rounded-full",
                        "after:absolute after:inset-0 after:rounded-[inherit] after:bg-kg-accent",
                        "after:origin-left rtl:after:origin-right after:scale-x-(--_progress)",
                        "after:transition-[scale] after:duration-(--kg-duration-base) after:ease-kg-out",
                      )}
                      style={{ "--_progress": (item.progress ?? 0) / 100 } as CSSProperties}
                    />
                  )}
                </span>
                <button
                  type="button"
                  className={cx(
                    "kg-file-dropzone__remove inline-grid place-items-center shrink-0 size-7 p-0 [&_svg]:size-3.5",
                    "text-kg-fg-muted bg-transparent border-0 rounded-full cursor-pointer",
                    "transition-[background-color,color] duration-(--kg-duration-fast) ease-kg-out",
                    "interactive:hover:text-kg-fg interactive:hover:bg-kg-muted",
                    focusRing,
                  )}
                  aria-label={labels.remove(item.name)}
                  onClick={() => remove(item)}
                >
                  <XIcon />
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    )
  },
)

FileDropzone.displayName = "FileDropzone"

components/file-tree/file-tree.tsx:
"use client"

import { forwardRef, useMemo } from "react"
import { cx } from "../../utils/cx.js"
import { TreeView, type TreeViewNode, type TreeViewProps } from "../tree-view/tree-view.js"

export type FileTreeStatus = "added" | "modified" | "deleted" | "renamed"

export interface FileTreeProps
  extends Omit<
    TreeViewProps,
    "nodes" | "selected" | "defaultSelected" | "onSelectedChange" | "selectionMode" | "onAction"
  > {
  /** Slash-separated file paths. Folders are inferred; a trailing slash marks an empty folder. */
  paths: string[]
  /** Git-style markers shown beside files. */
  status?: Record<string, FileTreeStatus>
  /** `true` opens every folder. */
  expandAll?: boolean
  selectedPath?: string
  defaultSelectedPath?: string
  onSelectPath?: (path: string) => void
}

const STATUS_LETTER: Record<FileTreeStatus, string> = {
  added: "A",
  modified: "M",
  deleted: "D",
  renamed: "R",
}

const EXT_TONE: Record<string, string> = {
  ts: "fill-kg-info",
  tsx: "fill-kg-info",
  js: "fill-kg-warning",
  jsx: "fill-kg-warning",
  json: "fill-kg-warning",
  css: "fill-[color-mix(in_oklab,var(--kg-info)_50%,var(--kg-success))]",
  scss: "fill-[color-mix(in_oklab,var(--kg-info)_50%,var(--kg-success))]",
  md: "fill-kg-fg-muted",
  mdx: "fill-kg-fg-muted",
  png: "fill-kg-success",
  svg: "fill-kg-success",
  jpg: "fill-kg-success",
  html: "fill-kg-danger",
  rs: "fill-kg-danger",
}

/* Paper Layers: git markers are letter chips on the matching paper, so they stay AA on any row. */
const STATUS_PAPER: Record<FileTreeStatus, string> = {
  added: "bg-kg-paper-sage",
  modified: "bg-kg-paper-butter",
  deleted: "bg-kg-paper-rose",
  renamed: "bg-kg-paper-sky",
}

const Folder = ({ open }: { open: boolean }) => (
  <svg viewBox="0 0 16 16" data-file-icon="folder" className="text-kg-accent-strong">
    {open ? (
      <path
        d="M1.75 4.25c0-.69.56-1.25 1.25-1.25h2.6l1.4 1.5h4.5c.69 0 1.25.56 1.25 1.25v.75H4.6a1 1 0 0 0-.95.68L1.75 12.5z M3.65 7.18A1 1 0 0 1 4.6 6.5h9.15a.6.6 0 0 1 .57.79l-1.5 4.5a1 1 0 0 1-.95.71H2.2"
        fill="currentColor"
        fillOpacity="0.18"
        stroke="currentColor"
        strokeWidth="1.2"
        strokeLinejoin="round"
      />
    ) : (
      <path
        d="M1.75 4.25c0-.69.56-1.25 1.25-1.25h2.6l1.4 1.5h6c.69 0 1.25.56 1.25 1.25v5.75c0 .69-.56 1.25-1.25 1.25H3c-.69 0-1.25-.56-1.25-1.25z"
        fill="currentColor"
        fillOpacity="0.18"
        stroke="currentColor"
        strokeWidth="1.2"
        strokeLinejoin="round"
      />
    )}
  </svg>
)

const File = ({ ext }: { ext: string }) => (
  <svg viewBox="0 0 16 16" data-file-icon="file" data-ext={ext} className="text-kg-fg-muted">
    <path
      d="M4 1.75h5l3.25 3.25v8c0 .69-.56 1.25-1.25 1.25H4c-.69 0-1.25-.56-1.25-1.25V3c0-.69.56-1.25 1.25-1.25z"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.2"
      strokeLinejoin="round"
    />
    <path d="M9 1.75V5h3.25" fill="none" stroke="currentColor" strokeWidth="1.2" />
    <rect x="4.75" y="9" width="5" height="2.5" rx="1" className={`kg-file-tree__ext ${EXT_TONE[ext] ?? "fill-kg-fg-faint"}`} />
  </svg>
)

interface Draft {
  name: string
  path: string
  folder: boolean
  children: Map<string, Draft>
}

const build = (paths: string[], status: Record<string, FileTreeStatus> | undefined) => {
  const root: Draft = { name: "", path: "", folder: true, children: new Map() }
  for (const raw of paths) {
    const folderOnly = raw.endsWith("/")
    const parts = raw.split("/").filter(Boolean)
    let cursor = root
    parts.forEach((part, index) => {
      const path = parts.slice(0, index + 1).join("/")
      const folder = index < parts.length - 1 || folderOnly
      let next = cursor.children.get(part)
      if (!next) {
        next = { name: part, path, folder, children: new Map() }
        cursor.children.set(part, next)
      } else if (folder) next.folder = true
      cursor = next
    })
  }
  const folders: string[] = []
  const toNodes = (draft: Draft): TreeViewNode[] =>
    [...draft.children.values()]
      .sort((a, b) => Number(b.folder) - Number(a.folder) || a.name.localeCompare(b.name))
      .map((entry) => {
        if (entry.folder) {
          folders.push(entry.path)
          const node: TreeViewNode = {
            id: entry.path,
            label: entry.name,
            icon: <Folder open={false} />,
            expandedIcon: <Folder open />,
            children: toNodes(entry),
          }
          return node
        }
        const ext = entry.name.includes(".") ? (entry.name.split(".").pop() ?? "") : ""
        const mark = status?.[entry.path]
        const node: TreeViewNode = {
          id: entry.path,
          label: (
            <span
              data-status={mark}
              className={mark === "deleted" ? "line-through decoration-kg-fg-faint" : undefined}
            >
              {entry.name}
            </span>
          ),
          textValue: entry.name,
          icon: <File ext={ext.toLowerCase()} />,
        }
        if (mark)
          node.meta = (
            <span
              className={`kg-file-tree__status inline-grid h-4 min-w-4 place-items-center rounded-kg-xs border border-kg-ink px-0.5 font-kg-mono text-[0.6875rem] leading-none font-bold text-kg-fg no-underline ${STATUS_PAPER[mark]}`}
              data-status={mark}
              title={mark}
            >
              {STATUS_LETTER[mark]}
              <span className="kg-file-tree__sr sr-only"> {mark}</span>
            </span>
          )
        return node
      })
  const nodes = toNodes(root)
  return { nodes, folders }
}

/** A file explorer built on `TreeView`: give it paths, get folders, icons and git markers. */
export const FileTree = forwardRef<HTMLUListElement, FileTreeProps>(
  (
    {
      paths,
      status,
      expandAll = false,
      selectedPath,
      defaultSelectedPath,
      onSelectPath,
      defaultExpanded,
      className,
      ...props
    },
    ref,
  ) => {
    const { nodes, folders } = useMemo(() => build(paths, status), [paths, status])
    const isFolder = (id: string) => folders.includes(id)
    return (
      <TreeView
        ref={ref}
        className={cx("kg-file-tree [--_fs:var(--kg-text-sm)]", className)}
        nodes={nodes}
        selectionMode="single"
        defaultExpanded={defaultExpanded ?? (expandAll ? folders : [])}
        {...(selectedPath !== undefined ? { selected: [selectedPath] } : null)}
        defaultSelected={defaultSelectedPath ? [defaultSelectedPath] : []}
        onSelectedChange={(ids) => {
          const id = ids[ids.length - 1]
          if (id && !isFolder(id)) onSelectPath?.(id)
        }}
        {...props}
      />
    )
  },
)
FileTree.displayName = "FileTree"

components/filter-bar/filter-bar.tsx:
"use client"

import { forwardRef, type HTMLAttributes, type ReactNode } from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "../dropdown-menu/dropdown-menu.js"
import { Tag } from "../tag/tag.js"

export interface FilterBarFilter {
  id: string
  /** The dimension, e.g. "Region". */
  label: string
  /** What it is filtered to, e.g. "North, West". */
  value: string
  /** Set on this view alone rather than inherited from the page; drawn in the accent. */
  local?: boolean
}

export interface FilterBarScope {
  value: string
  label: string
}

export interface FilterBarLabels {
  /** Names the bar for assistive tech. */
  bar?: string
  filters?: string
  reset?: string
  remove?: (filter: FilterBarFilter) => string
}

export interface FilterBarProps extends HTMLAttributes<HTMLDivElement> {
  filters: readonly FilterBarFilter[]
  onRemove?: (id: string) => void
  /** Offered while a filter is applied or the scope differs from `defaultScope`. */
  onReset?: () => void
  /** Choices for the scope menu, such as stores, teams or date ranges. */
  scopes?: readonly FilterBarScope[]
  scope?: string
  defaultScope?: string
  onScopeChange?: (scope: string) => void
  /** The menu's heading and the word before the current scope, e.g. "Store". */
  scopeLabel?: string
  labels?: FilterBarLabels
  /** Extra controls at the end of the bar, such as a date picker. */
  children?: ReactNode
}

const Chevron = () => (
  <svg
    viewBox="0 0 16 16"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.75"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="m4 6 4 4 4-4" />
  </svg>
)

const scopeClass = [
  "kg-filter-bar__scope inline-flex h-kg-sm max-w-[18rem] cursor-pointer items-center gap-1.5 ps-3 pe-2.5",
  "rounded-full border-2 border-kg-ink bg-kg-surface font-[inherit] text-kg-fg",
  "transition-[translate,box-shadow] duration-(--kg-duration-fast) ease-kg-out",
  "hover:-translate-px hover:shadow-kg-xs active:translate-0 active:shadow-none aria-expanded:shadow-kg-xs",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
  "[&_svg]:size-[0.875rem] [&_svg]:shrink-0 [&_svg]:text-kg-fg-muted [&_svg]:transition-[rotate] [&_svg]:duration-(--kg-duration-base) [&_svg]:ease-kg-out",
  "aria-expanded:[&_svg]:rotate-180",
].join(" ")

const resetClass = [
  "kg-filter-bar__reset h-kg-sm cursor-pointer rounded-kg-md border-0 bg-transparent px-2.5 font-[inherit] font-[560] text-kg-fg-muted",
  "transition-colors duration-(--kg-duration-fast) ease-kg-out hover:bg-kg-muted hover:text-kg-fg",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
].join(" ")

/**
 * The filters a view is drawn under: a scope menu, one removable chip per applied filter and
 * a reset. Chips are a labelled list, each remove button names the filter it clears.
 */
export const FilterBar = forwardRef<HTMLDivElement, FilterBarProps>(
  (
    {
      filters,
      onRemove,
      onReset,
      scopes,
      scope: scopeProp,
      defaultScope,
      onScopeChange,
      scopeLabel = "Scope",
      labels,
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const initial = defaultScope ?? scopes?.[0]?.value ?? ""
    const [scope, setScope] = useControllableState({
      value: scopeProp,
      defaultValue: initial,
      onChange: onScopeChange,
    })
    const current = scopes?.find((option) => option.value === scope)
    const dirty = filters.length > 0 || (scopes !== undefined && scope !== initial)

    return (
      <div
        ref={ref}
        role="group"
        aria-label={labels?.bar ?? "Filters"}
        className={cx("kg-filter-bar flex min-w-0 flex-wrap items-center gap-2 text-kg-sm", className)}
        {...props}
      >
        {scopes && scopes.length > 0 && (
          <DropdownMenu>
            <DropdownMenuTrigger className={scopeClass}>
              <span className="kg-filter-bar__scope-label text-kg-fg-muted">{scopeLabel}</span>
              <span className="kg-filter-bar__scope-value min-w-0 truncate font-[580]">
                {current?.label ?? scope}
              </span>
              <Chevron />
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
              <DropdownMenuRadioGroup value={scope} onValueChange={setScope}>
                <DropdownMenuLabel>{scopeLabel}</DropdownMenuLabel>
                {scopes.map((option) => (
                  <DropdownMenuRadioItem
                    key={option.value}
                    value={option.value}
                    closeOnSelect
                  >
                    {option.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>
        )}
        {filters.length > 0 && (
          <ul
            className="kg-filter-bar__chips m-0 flex list-none flex-wrap gap-1.5 p-0"
            aria-label={labels?.filters ?? "Active filters"}>
            {filters.map((filter) => (
              <li key={filter.id}>
                <Tag
                  size="sm"
                  tone={filter.local ? "accent" : "neutral"}
                  onRemove={onRemove ? () => onRemove(filter.id) : undefined}
                  removeLabel={
                    labels?.remove?.(filter) ?? `Remove ${filter.label}: ${filter.value}`
                  }
                >
                  <span
                    className={cx(
                      "kg-filter-bar__chip-label inline-block",
                      filter.local ? undefined : "text-kg-fg-muted",
                    )}
                  >
                    {filter.label}
                  </span>
                  <span className="kg-filter-bar__chip-value ms-[0.3em] inline-block max-w-[12rem] truncate align-bottom font-[580]">
                    {filter.value}
                  </span>
                </Tag>
              </li>
            ))}
          </ul>
        )}
        {onReset && dirty && (
          <button type="button" className={resetClass} onClick={onReset}>
            {labels?.reset ?? "Reset"}
          </button>
        )}
        {children != null && <div className="kg-filter-bar__extra ms-auto flex flex-wrap items-center gap-2">{children}</div>}
      </div>
    )
  },
)

FilterBar.displayName = "FilterBar"

components/filter-chips/filter-chips.tsx:
"use client"

import {
  forwardRef,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
  type Ref,
  useMemo,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { useLocale } from "../../hooks/use-locale.js"
import { cx } from "../../utils/cx.js"
import { variants } from "../../utils/variants.js"

export type FilterChipsSize = "sm" | "md" | "lg"
export type FilterChipsSelectionMode = "multiple" | "single"

export interface FilterChipOption<V extends string = string> {
  value: V
  label: string
  /** Matching products, shown after the label. */
  count?: number
  icon?: ReactNode
  disabled?: boolean
}

export interface FilterChipsLabels {
  clearAll?: string
  /** Expander text while options are hidden. */
  more?: (hidden: number) => string
  less?: string
  /** Spoken after the label when a chip has a count. */
  count?: (count: number, formatted: string) => string
}

export interface FilterChipsProps<V extends string = string> extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  /** Names the group, e.g. "Material". */
  label: string
  options: readonly FilterChipOption<V>[]
  /** `single` still allows clearing by pressing the active chip again. */
  selectionMode?: FilterChipsSelectionMode
  value?: V[]
  defaultValue?: V[]
  onValueChange?: (value: V[]) => void
  /** Collapse to this many chips behind a "+N more" toggle. Selected chips always stay visible. */
  maxVisible?: number
  /** Show "Clear all" while anything is selected. */
  clearable?: boolean
  size?: FilterChipsSize
  locale?: string
  labels?: FilterChipsLabels
}

const EMPTY: never[] = []

const CheckIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.6"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
    focusable="false"
  >
    <path pathLength="1" d="m5 12.5 4.5 4.5L19 7.5" />
  </svg>
)

const rootVariants = variants({
  base: "kg-filter-chips flex flex-wrap items-center gap-2 text-(length:--_text)",
  variants: {
    size: {
      sm: "[--_height:calc(var(--kg-control-sm)-0.25rem)] [--_text:var(--kg-text-xs)] [--_pad:calc(var(--kg-space)*2.5)]",
      md: "[--_height:var(--kg-control-sm)] [--_text:var(--kg-text-sm)] [--_pad:calc(var(--kg-space)*3)]",
      lg: "[--_height:var(--kg-control-md)] [--_text:var(--kg-text-base)] [--_pad:calc(var(--kg-space)*4)]",
    },
  },
  defaults: { size: "md" },
})

const pill = [
  "inline-flex h-(--_height) cursor-pointer items-center rounded-full border-2 font-[inherit] text-(length:--_text) leading-none font-[550] whitespace-nowrap",
  "transition-[background-color,border-color,color,translate,box-shadow] duration-(--kg-duration-fast) ease-kg-out [-webkit-tap-highlight-color:transparent]",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
]

const chipClass = [
  pill,
  "group/chip border-kg-ink px-(--_pad) bg-kg-surface text-kg-fg interactive:hover:bg-kg-paper-sage interactive:active:translate-y-px",
  "data-selected:bg-kg-accent data-selected:text-kg-accent-fg data-selected:shadow-kg-xs interactive:data-selected:hover:bg-kg-accent",
  "disabled:cursor-not-allowed disabled:opacity-45",
]

const FilterChipsImpl = <V extends string = string>(
  {
    label,
    options,
    selectionMode = "multiple",
    value: valueProp,
    defaultValue = EMPTY,
    onValueChange,
    maxVisible,
    clearable = true,
    size = "md",
    locale,
    labels,
    className,
    ...props
  }: FilterChipsProps<V>,
  forwardedRef: Ref<HTMLDivElement>,
) => {
  const local = useRef<HTMLDivElement>(null)
  const ref = useComposedRefs(local, forwardedRef)
  const [value, setValue] = useControllableState<V[]>({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  })
  const [expanded, setExpanded] = useState(false)

  const resolvedLocale = useLocale(locale)
  const text = useMemo(() => {
    const plural = new Intl.PluralRules(resolvedLocale)
    return {
      clearAll: "Clear all",
      more: (hidden: number) => `+${hidden} more`,
      less: "Show less",
      count: (count: number, formatted: string) =>
        `${formatted} ${plural.select(count) === "one" ? "result" : "results"}`,
      ...labels,
    }
  }, [resolvedLocale, labels])
  const numbers = useMemo(() => new Intl.NumberFormat(resolvedLocale), [resolvedLocale])

  const selected = new Set<string>(value)
  const collapsible = maxVisible !== undefined && options.length > maxVisible
  const visible =
    collapsible && !expanded
      ? options.filter(
          (option, index) => index < maxVisible || selected.has(option.value),
        )
      : options
  const hidden = options.length - visible.length

  const toggle = (option: FilterChipOption<V>) => {
    const on = selected.has(option.value)
    if (selectionMode === "single") setValue(on ? [] : [option.value])
    else
      setValue(
        on ? value.filter((item) => item !== option.value) : [...value, option.value],
      )
  }

  const clear = () => {
    setValue([])
    // The button disappears with the selection, so hand focus to the first chip instead.
    local.current
      ?.querySelector<HTMLButtonElement>(".kg-filter-chips__chip:not(:disabled)")
      ?.focus()
  }

  return (
    <div
      ref={ref}
      role="group"
      aria-label={label}
      className={rootVariants({ size, className })}
      data-size={size}
      {...props}
    >
      {visible.map((option) => {
        const on = selected.has(option.value)
        const formatted =
          option.count === undefined ? undefined : numbers.format(option.count)
        return (
          <button
            key={option.value}
            type="button"
            className={cx("kg-filter-chips__chip", chipClass)}
            aria-pressed={on}
            aria-label={
              option.count === undefined || formatted === undefined
                ? undefined
                : `${option.label}, ${text.count(option.count, formatted)}`
            }
            data-selected={on || undefined}
            disabled={option.disabled}
            onClick={() => toggle(option)}
          >
            <span
              className="kg-filter-chips__check inline-grid grid-cols-[0fr] transition-[grid-template-columns] duration-(--kg-duration-base) ease-kg-out group-data-selected/chip:grid-cols-[1fr] [&_svg]:me-[0.35em] [&_svg]:size-[1em] [&_path]:[stroke-dasharray:1] [&_path]:[stroke-dashoffset:1] [&_path]:transition-[stroke-dashoffset] [&_path]:delay-(--kg-duration-instant) [&_path]:duration-(--kg-duration-slow) [&_path]:ease-kg-out group-data-selected/chip:[&_path]:[stroke-dashoffset:0]"
              aria-hidden="true"
            >
              <span className="inline-grid min-w-0 overflow-hidden">
                <CheckIcon />
              </span>
            </span>
            {option.icon && (
              <span
                className="kg-filter-chips__icon me-[0.4em] inline-grid [&_svg]:size-[1.1em]"
                aria-hidden="true"
              >
                {option.icon}
              </span>
            )}
            <span className="kg-filter-chips__label">{option.label}</span>
            {formatted !== undefined && (
              <span
                className="kg-filter-chips__count ms-[0.45em] text-[0.92em] font-[450] tabular-nums opacity-75"
                aria-hidden="true"
              >
                {formatted}
              </span>
            )}
          </button>
        )
      })}
      {collapsible && (hidden > 0 || expanded) && (
        <button
          type="button"
          className={cx(
            "kg-filter-chips__more",
            pill,
            "border-dashed border-kg-ink bg-transparent px-(--_pad) text-kg-fg hover:bg-kg-paper-sage",
          )}
          aria-expanded={expanded}
          onClick={() => setExpanded((open) => !open)}
        >
          {expanded ? text.less : text.more(hidden)}
        </button>
      )}
      {clearable && value.length > 0 && (
        <button
          type="button"
          className={cx(
            "kg-filter-chips__clear",
            pill,
            "animate-[kg-fade-in_var(--kg-duration-base)_var(--kg-ease-out)] border-transparent bg-transparent px-[calc(var(--_pad)*0.6)] text-kg-fg-muted underline underline-offset-[0.2em] hover:text-kg-fg",
          )}
          onClick={clear}
        >
          {text.clearAll}
        </button>
      )}
    </div>
  )
}

/** Toggle-button filters for collection pages, with counts, a check animation and Clear all. */
export const FilterChips = forwardRef(FilterChipsImpl) as (<V extends string = string>(
  props: FilterChipsProps<V> & { ref?: Ref<HTMLDivElement> },
) => ReactElement | null) & { displayName?: string }

FilterChips.displayName = "FilterChips"

components/filter-sheet/filter-sheet.tsx:
"use client"

import {
  forwardRef,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
  useId,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"
import { Button } from "../button/button.js"
import {
  Drawer,
  DrawerBody,
  DrawerContent,
  type DrawerContentProps,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "../drawer/drawer.js"

export interface FilterSheetProps extends Omit<
  DrawerContentProps,
  "children" | "title" | "open"
> {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Replaces the built-in trigger button, which then opens the sheet via `asChild`. */
  trigger?: ReactElement | null
  triggerLabel?: string
  title?: ReactNode
  description?: ReactNode
  /** How many filters are applied: shown on the trigger and in the footer. */
  activeCount?: number
  /** Runs before the sheet closes from the Apply button. */
  onApply?: () => void
  /** Shows a Reset button, enabled while anything is active. */
  onReset?: () => void
  applyLabel?: ReactNode
  resetLabel?: ReactNode
  /** Builds the footer readout, e.g. "3 active". */
  formatCount?: (count: number) => string
  children?: ReactNode
}

const FilterIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    aria-hidden="true"
  >
    <path d="M4 6h16M7 12h10M10 18h4" />
  </svg>
)

const defaultFormat = (count: number) => `${count} active`

/** A side sheet of filter fields with a sticky apply and reset footer, built on Drawer. */
export const FilterSheet = forwardRef<HTMLDialogElement, FilterSheetProps>(
  (
    {
      open: openProp,
      defaultOpen = false,
      onOpenChange,
      trigger,
      triggerLabel = "Filters",
      title = "Filters",
      description,
      activeCount = 0,
      onApply,
      onReset,
      applyLabel = "Apply filters",
      resetLabel = "Reset",
      formatCount = defaultFormat,
      side = "right",
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const [open, setOpen] = useControllableState({
      value: openProp,
      defaultValue: defaultOpen,
      onChange: onOpenChange,
    })

    return (
      <Drawer open={open} onOpenChange={setOpen}>
        {trigger !== null && (
          <DrawerTrigger asChild>
            {trigger ?? (
              <Button
                variant="outline"
                leading={<FilterIcon />}
                aria-label={
                  activeCount > 0 ? `${triggerLabel}, ${activeCount} active` : undefined
                }
                className="kg-filter-sheet__trigger"
              >
                {triggerLabel}
                {activeCount > 0 && (
                  <span
                    className={cx(
                      "kg-filter-sheet__count inline-grid place-items-center min-w-[1.25rem] h-[1.25rem] px-[5px] ms-0.5",
                      "text-kg-xs font-bold tabular-nums leading-none text-kg-accent-fg bg-kg-accent rounded-full",
                      "animate-[kg-pop-in_var(--kg-duration-base)_var(--kg-ease-out)]",
                    )}
                    aria-hidden="true"
                  >
                    {activeCount}
                  </span>
                )}
              </Button>
            )}
          </DrawerTrigger>
        )}
        <DrawerContent
          ref={ref}
          side={side}
          className={cx("kg-filter-sheet", className)}
          {...props}
        >
          <DrawerHeader>
            <DrawerTitle>{title}</DrawerTitle>
            {description != null && (
              <DrawerDescription>{description}</DrawerDescription>
            )}
          </DrawerHeader>
          <DrawerBody className="kg-filter-sheet__body grid content-start gap-6">{children}</DrawerBody>
          <DrawerFooter stretch={false} className="kg-filter-sheet__footer items-center">
            <span
              className="kg-filter-sheet__readout min-w-0 flex-auto text-kg-sm font-medium tabular-nums text-kg-fg data-empty:text-kg-fg-muted"
              data-empty={activeCount === 0 || undefined}
              aria-live="polite"
            >
              {formatCount(activeCount)}
            </span>
            {onReset && (
              <Button variant="ghost" disabled={activeCount === 0} onClick={onReset}>
                {resetLabel}
              </Button>
            )}
            <Button
              onClick={() => {
                onApply?.()
                setOpen(false)
              }}
            >
              {applyLabel}
            </Button>
          </DrawerFooter>
        </DrawerContent>
      </Drawer>
    )
  },
)

FilterSheet.displayName = "FilterSheet"

export interface FilterSheetSectionProps extends Omit<
  HTMLAttributes<HTMLElement>,
  "title"
> {
  title: string
  icon?: ReactNode
  /** Selected values in this section, shown beside the title. */
  count?: number
  /** Shows a Clear button while `count` is above zero. */
  onClear?: () => void
  clearLabel?: string
}

export const FilterSheetSection = forwardRef<HTMLElement, FilterSheetSectionProps>(
  (
    {
      title,
      icon,
      count = 0,
      onClear,
      clearLabel = "Clear",
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const id = useId()
    return (
      <section
        ref={ref}
        aria-labelledby={id}
        className={cx("kg-filter-sheet__section grid gap-3", className)}
        {...props}
      >
        <div className="kg-filter-sheet__section-head flex items-center gap-2 min-h-[1.5rem]">
          {icon != null && (
            <span
              className="kg-filter-sheet__section-icon grid place-items-center shrink-0 size-[1.375rem] text-kg-fg bg-kg-paper-sage rounded-kg-sm [&_svg]:size-[0.8125rem]"
              aria-hidden="true"
            >
              {icon}
            </span>
          )}
          <h3 id={id} className="kg-filter-sheet__section-title m-0 text-kg-sm font-semibold text-kg-fg">
            {title}
          </h3>
          {count > 0 && (
            <span className="kg-filter-sheet__section-count px-1.5 text-kg-xs font-semibold tabular-nums leading-[1.25rem] text-kg-fg bg-kg-paper-sage rounded-full">
              {count}
            </span>
          )}
          <span className="kg-filter-sheet__rule flex-1 min-w-3 h-px bg-kg-border" aria-hidden="true" />
          {onClear && count > 0 && (
            <button
              type="button"
              className={cx(
                "kg-filter-sheet__clear h-[1.5rem] px-2 [font-family:inherit] text-kg-xs font-medium text-kg-fg-muted",
                "bg-transparent border-0 rounded-kg-sm cursor-pointer transition-colors duration-(--kg-duration-fast) ease-kg-out",
                "hover:text-[color-mix(in_oklab,var(--kg-danger),var(--kg-fg)_30%)] hover:bg-kg-paper-rose",
                "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
              )}
              aria-label={`${clearLabel} ${title}`}
              onClick={onClear}
            >
              {clearLabel}
            </button>
          )}
        </div>
        {children}
