@layer kg.components {
  /* Glitches cluster in the first fifth of each cycle so the text rests between bursts. */
  @keyframes kg-glitch-a {
    0% { clip-path: inset(12% 0 70% 0); transform: translateX(calc(var(--_offset) * -1)); }
    4% { clip-path: inset(62% 0 18% 0); transform: translateX(var(--_offset)); }
    8% { clip-path: inset(34% 0 44% 0); transform: translateX(calc(var(--_offset) * -0.6)); }
    12% { clip-path: inset(80% 0 4% 0); transform: translateX(calc(var(--_offset) * 1.4)); }
    16% { clip-path: inset(4% 0 86% 0); transform: translateX(calc(var(--_offset) * -1.2)); }
    20%, 100% { clip-path: inset(50% 0 50% 0); transform: none; }
  }

  @keyframes kg-glitch-b {
    0% { clip-path: inset(70% 0 10% 0); transform: translateX(var(--_offset)); }
    5% { clip-path: inset(20% 0 64% 0); transform: translateX(calc(var(--_offset) * -1.3)); }
    10% { clip-path: inset(48% 0 30% 0); transform: translateX(calc(var(--_offset) * 0.8)); }
    15% { clip-path: inset(8% 0 78% 0); transform: translateX(calc(var(--_offset) * -0.7)); }
    20%, 100% { clip-path: inset(50% 0 50% 0); transform: none; }
  }
}

