@layer kg.components {
  /*
   * Each beam is a soft ellipse whose axis is pinned to the origin corner, with its first third
   * tucked off-canvas so the light appears to enter from outside the frame.
   */
  .kg-hero-spotlight__beam,
  .kg-hero-spotlight__core {
    --_angle: var(--kg-hero-spotlight-angle, 28deg);
    --_delay: var(--kg-hero-spotlight-delay, 0.25s);
    --_rest: rotate(var(--_angle)) translate(-30%, -50%) scale(1);

    transform: var(--_rest);
    animation: kg-hero-spotlight-in var(--kg-hero-spotlight-duration, 2s) var(--kg-ease-out)
      var(--_delay) both;
