"use client"

import { forwardRef, useDeferredValue, useEffect, useId, useState } from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"
import {
  Dialog,
  DialogBody,
  DialogContent,
  type DialogContentProps,
  DialogHeader,
  DialogTitle,
} from "../dialog/dialog.js"
import { Kbd } from "../kbd/kbd.js"

export interface KeyboardShortcut {
  /** One entry per key, in Kbd notation: `["mod", "k"]`. */
  keys: string[]
  label: string
}

export interface KeyboardShortcutGroup {
  title: string
  shortcuts: KeyboardShortcut[]
}

export interface KeyboardShortcutsDialogProps
  extends Omit<DialogContentProps, "title" | "children"> {
  groups: KeyboardShortcutGroup[]
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Printable key that opens the dialog from anywhere outside a text field. `null` disables. */
  hotkey?: string | null
  title?: string
  searchable?: boolean
  searchLabel?: string
  emptyLabel?: string
}

const searchClass = [
  "kg-shortcuts__search mt-1.5 h-kg-md w-full px-3 [font-family:inherit] text-kg-base text-kg-fg placeholder:text-kg-fg-muted",
  "bg-kg-surface border-2 border-kg-ink rounded-kg-md outline-none",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
]

const isTyping = (target: EventTarget | null) =>
  target instanceof HTMLElement &&
  (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName))

/** A searchable cheat sheet of keyboard shortcuts, summoned with `?`. */
export const KeyboardShortcutsDialog = forwardRef<
  HTMLDialogElement,
  KeyboardShortcutsDialogProps
>(
  (
    {
      groups,
      open: openProp,
      defaultOpen = false,
      onOpenChange,
      hotkey = "?",
      title = "Keyboard shortcuts",
      searchable = true,
      searchLabel = "Search shortcuts",
      emptyLabel = "No matches",
      size = "lg",
      className,
      ...props
    },
    ref,
  ) => {
    const [open, setOpen] = useControllableState({
      value: openProp,
      defaultValue: defaultOpen,
      onChange: onOpenChange,
    })
    const [query, setQuery] = useState("")
    const deferred = useDeferredValue(query).trim().toLowerCase()
    const id = useId()

    useEffect(() => {
      if (!hotkey) return
      const onKey = (event: KeyboardEvent) => {
        if (event.key !== hotkey || event.metaKey || event.ctrlKey || event.altKey) return
        if (isTyping(event.target)) return
        event.preventDefault()
        setOpen(true)
      }
      document.addEventListener("keydown", onKey)
      return () => document.removeEventListener("keydown", onKey)
    }, [hotkey, setOpen])

    useEffect(() => {
      if (!open) setQuery("")
    }, [open])

    const filtered = groups
      .map((group) => ({
        ...group,
        shortcuts: group.shortcuts.filter(
          (shortcut) =>
            !deferred ||
            shortcut.label.toLowerCase().includes(deferred) ||
            group.title.toLowerCase().includes(deferred),
        ),
      }))
      .filter((group) => group.shortcuts.length > 0)

    return (
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent
          ref={ref}
          size={size}
          className={cx("kg-shortcuts", className)}
          {...props}
        >
          <DialogHeader className="kg-shortcuts__header">
            <DialogTitle>{title}</DialogTitle>
            {searchable && (
              <input
                type="search"
                className={cx(searchClass)}
                aria-label={searchLabel}
                aria-controls={`${id}-results`}
                placeholder={searchLabel}
                value={query}
                onChange={(event) => setQuery(event.target.value)}
              />
            )}
          </DialogHeader>
          <DialogBody id={`${id}-results`} className="kg-shortcuts__body max-h-[min(28rem,60dvh)]">
            {filtered.length === 0 ? (
              <p className="kg-shortcuts__empty m-0 py-8 text-center text-kg-fg-muted" role="status">
                {emptyLabel}
              </p>
            ) : (
              <div className="kg-shortcuts__groups [columns:2_16rem] gap-x-8">
                {filtered.map((group, index) => (
                  <section
                    key={group.title}
                    className="kg-shortcuts__group mb-5 break-inside-avoid"
                    aria-labelledby={`${id}-g${index}`}
                  >
                    <h3 id={`${id}-g${index}`} className="kg-shortcuts__group-title m-0 mb-2 text-kg-xs font-semibold tracking-[0.04em] text-kg-fg-muted uppercase">
                      {group.title}
                    </h3>
                    <dl className="kg-shortcuts__list m-0 grid">
                      {group.shortcuts.map((shortcut) => (
                        <div key={shortcut.label} className="kg-shortcuts__row flex items-center justify-between gap-4 border-b border-kg-border py-2 last:border-b-0">
                          <dt className="text-kg-sm text-kg-fg">{shortcut.label}</dt>
                          <dd className="m-0 shrink-0">
                            <Kbd keys={shortcut.keys} size="sm" />
                          </dd>
                        </div>
                      ))}
                    </dl>
                  </section>
                ))}
              </div>
            )}
          </DialogBody>
        </DialogContent>
      </Dialog>
    )
  },
)

KeyboardShortcutsDialog.displayName = "KeyboardShortcutsDialog"

components/knob/knob.tsx:
"use client"

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  useRef,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"
import { variants } from "../../utils/variants.js"
import { clamp, roundToStep } from "../../utils/math.js"
import { useField } from "../field/field.js"

export type KnobSize = "sm" | "md" | "lg"

export interface KnobProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "defaultValue" | "onChange"> {
  value?: number
  defaultValue?: number
  onValueChange?: (value: number) => void
  /** Called once a drag or key press settles. */
  onValueCommit?: (value: number) => void
  min?: number
  max?: number
  step?: number
  size?: KnobSize
  /** Shows the value in the centre. */
  showValue?: boolean
  formatValue?: (value: number) => string
  /** Pixels of vertical drag that cover the full range. */
  dragRange?: number
  disabled?: boolean
}

const SWEEP = 270
const ARC = "M 21.716 78.284 A 40 40 0 1 1 78.284 78.284"

const knobVariants = variants({
  base: [
    "kg-knob group relative inline-grid place-items-center shrink-0 rounded-full",
    "cursor-ns-resize touch-none select-none [-webkit-tap-highlight-color:transparent]",
    "*:col-start-1 *:row-start-1",
    "focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-kg-ring",
    "data-disabled:cursor-not-allowed data-disabled:opacity-50",
  ],
  variants: {
    size: {
      sm: "size-[3.75rem]",
      md: "size-[5.5rem]",
      lg: "size-[7.5rem]",
    },
  },
  defaults: { size: "md" },
})

/**
 * A rotary control on the WAI-ARIA slider pattern. Drag up or down to turn it, or use the
 * arrow, Page, Home and End keys. The arc fills along a 270 degree sweep.
 */
export const Knob = forwardRef<HTMLDivElement, KnobProps>(
  (
    {
      value: valueProp,
      defaultValue,
      onValueChange,
      onValueCommit,
      min = 0,
      max = 100,
      step = 1,
      size = "md",
      showValue = true,
      formatValue = (v) => String(v),
      dragRange = 180,
      disabled: disabledProp,
      className,
      style,
      onKeyDown,
      onKeyUp,
      "aria-labelledby": labelledBy,
      ...props
    },
    ref,
  ) => {
    const field = useField()
    const disabled = disabledProp ?? field?.disabled ?? false
    const [value, setValue] = useControllableState({
      value: valueProp,
      defaultValue: defaultValue ?? min,
      onChange: onValueChange,
    })
    const drag = useRef<{ y: number; start: number } | null>(null)
    const latest = useRef(value)
    latest.current = value

    const set = (next: number) => {
      const snapped = clamp(roundToStep(next, step, min), min, max)
      latest.current = snapped
      setValue(snapped)
      return snapped
    }
    const fraction = (value - min) / (max - min || 1)

    const handleKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(event)
      if (event.defaultPrevented || disabled) return
      const page = Math.max(step, (max - min) / 10)
      const moves: Record<string, number> = {
        ArrowUp: value + step,
        ArrowRight: value + step,
        ArrowDown: value - step,
        ArrowLeft: value - step,
        PageUp: value + page,
        PageDown: value - page,
        Home: min,
        End: max,
      }
      const next = moves[event.key]
      if (next === undefined) return
      event.preventDefault()
      set(next)
    }

    const handlePointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
      if (disabled || event.button !== 0) return
      event.preventDefault()
      event.currentTarget.focus()
      event.currentTarget.setPointerCapture(event.pointerId)
      drag.current = { y: event.clientY, start: value }
    }
    const handlePointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
      const state = drag.current
      if (!state) return
      // Shift slows the turn for fine adjustment.
      const scale = event.shiftKey ? 0.2 : 1
      const delta = ((state.y - event.clientY) / dragRange) * (max - min) * scale
      set(state.start + delta)
    }
    const endDrag = () => {
      if (!drag.current) return
      drag.current = null
      onValueCommit?.(latest.current)
    }

    return (
      <div
        ref={ref}
        role="slider"
        tabIndex={disabled ? -1 : 0}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={value}
        aria-valuetext={formatValue(value)}
        aria-disabled={disabled || undefined}
        aria-labelledby={labelledBy ?? field?.labelId}
        aria-orientation="vertical"
        className={knobVariants({ size, className })}
        data-size={size}
        data-disabled={disabled || undefined}
        style={
          {
            ...style,
            "--_turn": `${-SWEEP / 2 + fraction * SWEEP}deg`,
          } as CSSProperties
        }
        onKeyDown={handleKeyDown}
        onKeyUp={(event) => {
          onKeyUp?.(event)
          if (event.key.startsWith("Arrow") || event.key.startsWith("Page") || event.key === "Home" || event.key === "End")
            onValueCommit?.(latest.current)
        }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={endDrag}
