    scale: -1 1;
  }

  @media (prefers-reduced-motion: reduce) {
    .kg-orbit-rings__sweep {
      animation: none;
    }
  }

  [data-kg-motion="reduce"] .kg-orbit-rings__sweep {
    animation: none;
  }

  @keyframes kg-orbit-rings-spin {
    to {
      transform: rotate(1turn);
    }
  }
}

