"use client"

import {
  type FieldsetHTMLAttributes,
  forwardRef,
  type ReactNode,
  useEffect,
  useId,
  useRef,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"

export interface PaymentMethodSelectorMethod {
  id: string
  label: string
  /** One short line, e.g. "Visa ending 4242" or "Pay in 4". */
  description?: ReactNode
  /** Announced text at the end of the row, such as a price. */
  aside?: ReactNode
  /** Brand marks or an icon, shown at the end of the row. Decorative. */
  icon?: ReactNode
  /** Revealed under the row while selected, such as card fields. */
  content?: ReactNode
  disabled?: boolean
}

export interface PaymentMethodSelectorProps extends Omit<
  FieldsetHTMLAttributes<HTMLFieldSetElement>,
  "defaultValue" | "onChange"
> {
  methods: readonly PaymentMethodSelectorMethod[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  /** The group's legend. */
  label?: string
  showLabel?: boolean
  name?: string
}

// `inert` is set imperatively: React 18 and 19 disagree on how the attribute is passed.
const Reveal = ({ open, children }: { open: boolean; children: ReactNode }) => {
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => {
    ref.current?.toggleAttribute("inert", !open)
  }, [open])
  return (
    <div
      ref={ref}
      className="kg-payment-methods__reveal grid grid-rows-[0fr] transition-[grid-template-rows] duration-[var(--kg-duration-slow)] ease-kg-out group-data-[state=checked]/method:grid-rows-[1fr]"
    >
      <div className="kg-payment-methods__content min-h-0 overflow-hidden px-4 opacity-0 transition-opacity duration-(--kg-duration-base) ease-kg-out group-data-[state=checked]/method:pb-4 group-data-[state=checked]/method:opacity-100">
        {children}
      </div>
    </div>
  )
}

/**
 * Payment options as a stack of radio rows. The chosen row expands to reveal its fields, the
 * way Shopify and Stripe present cards, wallets and pay-later side by side.
 */
export const PaymentMethodSelector = forwardRef<HTMLFieldSetElement, PaymentMethodSelectorProps>(
  (
    {
      methods,
      value: valueProp,
      defaultValue,
      onValueChange,
      label = "Payment method",
      showLabel = false,
      name,
      className,
      ...props
    },
    ref,
  ) => {
    const generated = useId()
    const groupName = name ?? generated
    const [value, setValue] = useControllableState<string | undefined>({
      value: valueProp,
      defaultValue: defaultValue ?? methods.find((method) => !method.disabled)?.id,
      onChange: onValueChange as ((id: string | undefined) => void) | undefined,
    })

    return (
      <fieldset ref={ref} className={cx("kg-payment-methods m-0 min-w-0 border-0 p-0 text-kg-fg", className)} {...props}>
        <legend
          className={
            showLabel
              ? "kg-payment-methods__legend mb-3 p-0 text-kg-md font-semibold"
              : "kg-visually-hidden"
          }
        >
          {label}
        </legend>
        <div className="kg-payment-methods__stack grid gap-2">
          {methods.map((method) => {
            const selected = value === method.id
            const inputId = `${generated}-${method.id}`
            return (
              <div
                key={method.id}
                className={cx(
                  "kg-payment-methods__method group/method relative rounded-kg-lg border-2 bg-kg-surface",
                  "transition-[border-color,box-shadow,background-color] duration-(--kg-duration-fast) ease-kg-out",
                  "data-[state=unchecked]:border-kg-border data-disabled:opacity-50",
                  "data-[state=checked]:border-kg-ink data-[state=checked]:bg-kg-paper-sage data-[state=checked]:shadow-kg-sm",
                )}
                data-state={selected ? "checked" : "unchecked"}
                data-disabled={method.disabled || undefined}
              >
                <label
                  className="kg-payment-methods__row flex min-h-14 cursor-pointer items-center gap-3 px-4 py-3 group-data-disabled/method:cursor-not-allowed"
                  htmlFor={inputId}
                >
                  <input
                    id={inputId}
                    type="radio"
                    className="kg-payment-methods__input peer absolute m-0 size-px opacity-0"
                    name={groupName}
                    value={method.id}
                    checked={selected}
                    disabled={method.disabled}
                    onChange={() => setValue(method.id)}
                  />
                  <span
                    className={cx(
                      "kg-payment-methods__radio grid size-[1.125rem] shrink-0 place-items-center rounded-full border-2 border-kg-ink bg-kg-surface",
                      "after:size-2 after:scale-0 after:rounded-full after:bg-kg-accent-fg after:transition-[scale] after:duration-(--kg-duration-base) after:ease-kg-out",
                      "peer-checked:bg-kg-accent peer-checked:after:scale-100",
                      "peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-kg-ring",
                    )}
                    aria-hidden="true"
                  />
                  <span className="kg-payment-methods__text grid min-w-0 flex-1">
                    <span className="kg-payment-methods__label text-kg-sm font-semibold">{method.label}</span>
                    {method.description != null && (
                      <span className="kg-payment-methods__description text-kg-xs text-kg-fg-muted">
                        {method.description}
                      </span>
                    )}
                  </span>
                  {method.aside != null && (
                    <span className="kg-payment-methods__aside text-kg-sm font-semibold tabular-nums">{method.aside}</span>
                  )}
                  {method.icon != null && (
                    <span
                      className="kg-payment-methods__icon inline-flex gap-1 text-kg-fg-muted [&_svg]:h-5 [&_svg]:w-auto"
                      aria-hidden="true"
                    >
                      {method.icon}
                    </span>
                  )}
                </label>
                {method.content != null && (
                  <Reveal open={selected}>{method.content}</Reveal>
                )}
              </div>
            )
          })}
        </div>
      </fieldset>
    )
  },
)

PaymentMethodSelector.displayName = "PaymentMethodSelector"

components/permission-matrix/permission-:
"use client"

import {
  forwardRef,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
  useId,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"
import { Checkbox } from "../checkbox/checkbox.js"
import { Switch } from "../switch/switch.js"

export type PermissionMatrixControl = "checkbox" | "switch"
/** Granted permission ids per role id: `{ admin: ["billing", "export"] }`. */
export type PermissionMatrixValue = Record<string, readonly string[]>

export interface PermissionMatrixRole {
  id: string
  label: ReactNode
  description?: ReactNode
}

export interface PermissionMatrixPermission {
  id: string
  label: ReactNode
  description?: ReactNode
  /** Permissions sharing a group sit under one group heading, in first-seen order. */
  group?: string
}

export interface PermissionMatrixLabels {
  /** Read before a role name on the column toggle, e.g. "Grant all to". */
  allFor?: string
  permission?: string
}

export interface PermissionMatrixProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  roles: readonly PermissionMatrixRole[]
  permissions: readonly PermissionMatrixPermission[]
  value?: PermissionMatrixValue
  defaultValue?: PermissionMatrixValue
  onValueChange?: (value: PermissionMatrixValue) => void
  /** Cells that can't change, in the same shape as `value`. */
  locked?: PermissionMatrixValue
  control?: PermissionMatrixControl
  /** A checkbox per role header that grants or clears the whole column. */
  columnToggles?: boolean
  disabled?: boolean
  caption?: ReactNode
  hideCaption?: boolean
  labels?: PermissionMatrixLabels
}

interface Cell {
  row: number
  col: number
}

const headCell =
  "px-3 py-2 align-bottom text-kg-xs font-[560] tracking-[0.01em] text-kg-fg-muted border-b-2 border-kg-ink"

/* Rows rule off in hairlines, the last row of the last group closes without one. */
const rowClass = [
  "kg-permission-matrix__row transition-colors duration-(--kg-duration-fast) ease-kg-out",
  "*:border-b *:border-kg-border hover:bg-kg-muted/70 has-focus-visible:bg-kg-muted/70",
].join(" ")

const has = (value: PermissionMatrixValue | undefined, role: string, permission: string) =>
  value?.[role]?.includes(permission) ?? false

/**
 * Roles across, permissions down, a checkbox or switch in every cell. A WAI-ARIA grid: one
 * Tab stop, arrows move between cells, Home and End go to the row ends, Ctrl+Home and Ctrl+End
 * to the corners, Space toggles. Each cell is named by its permission and role headers.
 */
export const PermissionMatrix = forwardRef<HTMLDivElement, PermissionMatrixProps>(
  (
    {
      roles,
      permissions,
      value: valueProp,
      defaultValue = {},
      onValueChange,
      locked,
      control = "checkbox",
      columnToggles = false,
      disabled = false,
      caption,
      hideCaption = false,
      labels,
      className,
      ...props
    },
    forwardedRef,
  ) => {
    const id = useId()
    const table = useRef<HTMLTableElement>(null)
    const local = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(local, forwardedRef)
    const [value, setValue] = useControllableState<PermissionMatrixValue>({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    })
    const firstRow = columnToggles ? 0 : 1
    const [active, setActive] = useState<Cell>({ row: firstRow, col: 0 })

    const groups: { name: string | undefined; items: PermissionMatrixPermission[] }[] = []
    for (const permission of permissions) {
      const group = groups.find((entry) => entry.name === permission.group)
      if (group) group.items.push(permission)
      else groups.push({ name: permission.group, items: [permission] })
    }
    const ordered = groups.flatMap((group) => group.items)
    const lastRow = ordered.length

    const setCell = (role: string, permission: string, on: boolean) =>
      setValue((current) => {
        const granted = current[role] ?? []
        const next = on
          ? [...granted.filter((p) => p !== permission), permission]
          : granted.filter((p) => p !== permission)
        return { ...current, [role]: next }
      })

    const setColumn = (role: string, on: boolean) =>
      setValue((current) => {
        const granted = current[role] ?? []
        const keep = ordered
          .filter((p) => has(locked, role, p.id) && granted.includes(p.id))
          .map((p) => p.id)
        const open = ordered.filter((p) => !has(locked, role, p.id)).map((p) => p.id)
        const outside = granted.filter((p) => !ordered.some((o) => o.id === p))
        return { ...current, [role]: [...outside, ...keep, ...(on ? open : [])] }
      })

    const focusCell = (row: number, col: number, rowStep: number, colStep: number) => {
      let r = row
      let c = col
      while (r >= firstRow && r <= lastRow && c >= 0 && c < roles.length) {
        const input = table.current?.querySelector<HTMLInputElement>(
          `[data-row="${r}"][data-col="${c}"]`,
        )
        if (input && !input.disabled) {
          input.focus()
          return
        }
        r += rowStep
        c += colStep
        if (rowStep === 0 && colStep === 0) return
      }
    }

    const onKeyDown = (event: KeyboardEvent<HTMLTableElement>) => {
      const target = event.target as HTMLElement
      if (target.dataset.row === undefined) return
      const row = Number(target.dataset.row)
      const col = Number(target.dataset.col)
      const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
      const right = rtl ? -1 : 1
      const end = roles.length - 1
      const moves: Record<string, () => void> = {
        ArrowRight: () => focusCell(row, col + right, 0, right),
        ArrowLeft: () => focusCell(row, col - right, 0, -right),
        ArrowDown: () => focusCell(row + 1, col, 1, 0),
        ArrowUp: () => focusCell(row - 1, col, -1, 0),
        Home: () =>
          event.ctrlKey ? focusCell(firstRow, 0, 0, 1) : focusCell(row, 0, 0, 1),
        End: () =>
          event.ctrlKey ? focusCell(lastRow, end, 0, -1) : focusCell(row, end, 0, -1),
      }
      const move = moves[event.key]
      if (!move) return
      event.preventDefault()
      move()
    }

    const enabled = (row: number, col: number) => {
      const role = roles[col]
      if (disabled || !role) return false
      if (row === 0) return columnToggles
      const permission = ordered[row - 1]
      return permission !== undefined && !has(locked, role.id, permission.id)
    }
    // The grid keeps exactly one Tab stop, even when the remembered cell becomes locked.
    let stop: Cell | undefined = enabled(active.row, active.col) ? active : undefined
    for (let row = firstRow; !stop && row <= lastRow; row++)
      for (let col = 0; !stop && col < roles.length; col++)
        if (enabled(row, col)) stop = { row, col }

    const cellProps = (row: number, col: number) => ({
      "data-row": row,
      "data-col": col,
      tabIndex: stop?.row === row && stop.col === col ? 0 : -1,
      onFocus: () => setActive({ row, col }),
    })

    const Control = control === "switch" ? Switch : Checkbox

    return (
      <div ref={ref} className={cx("kg-permission-matrix min-w-0 overflow-x-auto text-kg-sm text-kg-fg", className)} {...props}>
        <span id={`${id}-all`} hidden>
          {labels?.allFor ?? "Grant all to"}
        </span>
        <table
          ref={table}
          role="grid"
          className="kg-permission-matrix__table w-full border-separate border-spacing-0"
          onKeyDown={onKeyDown}
          aria-disabled={disabled || undefined}
        >
          {caption != null && (
            <caption
              className={cx(
                "kg-permission-matrix__caption pb-3 text-start font-semibold",
                hideCaption && "kg-visually-hidden",
              )}
            >
              {caption}
            </caption>
          )}
          <thead>
            <tr>
              <th scope="col" className={cx("kg-permission-matrix__corner text-start", headCell)}>
                {labels?.permission ?? "Permission"}
              </th>
              {roles.map((role, col) => {
                const granted = ordered.filter((p) => has(value, role.id, p.id)).length
                return (
                  <th
                    key={role.id}
                    scope="col"
                    className={cx("kg-permission-matrix__role w-[7rem] text-center", headCell)}
                  >
                    <span className="kg-permission-matrix__role-text grid gap-0.5">
                      <span
                        id={`${id}-role-${col}`}
                        className="kg-permission-matrix__role-label text-kg-sm font-semibold text-kg-fg"
                      >
                        {role.label}
                      </span>
                      {role.description != null && (
                        <span className="kg-permission-matrix__role-description font-normal text-kg-fg-faint">
                          {role.description}
                        </span>
                      )}
                    </span>
                    {columnToggles && (
                      <Checkbox
                        size="sm"
                        className="kg-permission-matrix__toggle mx-auto mt-2"
                        aria-labelledby={`${id}-all ${id}-role-${col}`}
                        checked={ordered.length > 0 && granted === ordered.length}
                        indeterminate={granted > 0 && granted < ordered.length}
                        disabled={disabled}
                        onCheckedChange={(on) => setColumn(role.id, on)}
                        {...cellProps(0, col)}
                      />
                    )}
                  </th>
                )
              })}
            </tr>
          </thead>
          {groups.map((group, groupIndex) => (
            <tbody key={group.name ?? `group-${groupIndex}`} className="kg-permission-matrix__group last:[&>tr:last-child>*]:border-b-0">
              {group.name !== undefined && (
                <tr className="kg-permission-matrix__group-row">
                  <th
                    scope="colgroup"
                    colSpan={roles.length + 1}
                    className="px-3 pt-4 pb-1.5 text-start text-kg-xs font-semibold tracking-[0.04em] uppercase text-kg-fg-faint"
                  >
                    {group.name}
                  </th>
                </tr>
              )}
              {group.items.map((permission) => {
                const row = ordered.indexOf(permission) + 1
                const headerId = `${id}-perm-${row}`
                return (
                  <tr key={permission.id} className={rowClass}>
                    <th scope="row" className="kg-permission-matrix__permission px-3 py-2.5 text-start font-medium">
                      <span id={headerId} className="kg-permission-matrix__permission-label block">
                        {permission.label}
                      </span>
                      {permission.description != null && (
                        <span className="kg-permission-matrix__permission-description mt-0.5 block text-kg-xs font-normal text-kg-fg-faint">
                          {permission.description}
                        </span>
                      )}
                    </th>
                    {roles.map((role, col) => {
                      const isLocked = has(locked, role.id, permission.id)
                      return (
                        <td
                          key={role.id}
                          className="kg-permission-matrix__cell px-3 py-2 text-center align-middle"
                          data-locked={isLocked || undefined}
                        >
                          <Control
                            size="sm"
                            className="mx-auto"
                            aria-labelledby={`${headerId} ${id}-role-${col}`}
                            checked={has(value, role.id, permission.id)}
                            disabled={disabled || isLocked}
                            onCheckedChange={(on) => setCell(role.id, permission.id, on)}
                            {...cellProps(row, col)}
                          />
                        </td>
                      )
                    })}
                  </tr>
                )
              })}
            </tbody>
          ))}
        </table>
      </div>
    )
  },
)

PermissionMatrix.displayName = "PermissionMatrix"

components/phone-input/phone-input.tsx:
"use client"

import {
  type ClipboardEvent,
  forwardRef,
  type InputHTMLAttributes,
  useMemo,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"
import { resolveFieldControl, useField } from "../field/field.js"
import {
  type InputGroupSize,
  inputGroupControl,
  inputGroupVariants,
} from "../input-group/input-group.js"
import { SearchSelect } from "../search-select/search-select.js"
import {
  formatPhone,
  maxDigits,
  type PhoneInputCountry,
  phoneInputCountries,
} from "./countries.js"

export interface PhoneInputProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "value" | "defaultValue" | "onChange" | "size" | "type"
> {
  /** E.164, e.g. `+14155550123`. Empty string while no digits are typed. */
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  country?: string
  defaultCountry?: string
  onCountryChange?: (code: string) => void
  countries?: readonly PhoneInputCountry[]
  countryLabel?: string
  size?: InputGroupSize
  invalid?: boolean
}

const digitsOf = (text: string) => text.replace(/\D/g, "")

/** The country whose calling code starts an international number, longest code first. */
const matchDial = (
  digits: string,
  countries: readonly PhoneInputCountry[],
  preferred?: string,
) =>
  [...countries]
    .sort(
      (a, b) =>
        b.dial.length - a.dial.length ||
        Number(b.code === preferred) - Number(a.code === preferred),
    )
    .find((country) => digits.startsWith(country.dial))

/**
 * A national number field with a searchable country code. It formats as you type, accepts
 * pasted international numbers and reports E.164. No phone metadata is bundled.
 */
export const PhoneInput = forwardRef<HTMLInputElement, PhoneInputProps>(
  (
    {
      value: valueProp,
      defaultValue = "",
      onValueChange,
      country: countryProp,
      defaultCountry = "US",
      onCountryChange,
      countries = phoneInputCountries,
      countryLabel = "Country code",
      size = "md",
      invalid,
      disabled,
      required,
      placeholder,
      id,
      className,
      style,
      onPaste,
      "aria-describedby": describedBy,
      "aria-errormessage": errorMessage,
      ...props
    },
    ref,
  ) => {
    const control = resolveFieldControl(useField(), {
      id,
      disabled,
      required,
      invalid,
      "aria-describedby": describedBy,
      "aria-errormessage": errorMessage,
    })
    const initialDigits = digitsOf(valueProp ?? defaultValue)
    const [code, setCode] = useControllableState({
      value: countryProp,
      defaultValue: initialDigits
        ? (matchDial(initialDigits, countries, defaultCountry)?.code ?? defaultCountry)
        : defaultCountry,
      onChange: onCountryChange,
    })
    const [value, setValue] = useControllableState({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    })
    const country = countries.find((c) => c.code === code) ?? countries[0]
    const dial = country?.dial ?? ""
    const pattern = country?.pattern ?? "###############"
    const allDigits = digitsOf(value)
    const national = allDigits.startsWith(dial) ? allDigits.slice(dial.length) : allDigits

    const emit = (digits: string, target = country) =>
      setValue(
        digits && target
          ? `+${target.dial}${digits.slice(0, maxDigits(target.pattern))}`
          : "",
      )

    const options = useMemo(
      () =>
        countries.map((c) => ({
          value: c.code,
          label: c.name,
          aside: `+${c.dial}`,
          keywords: [c.code, c.dial],
        })),
      [countries],
    )

    const handlePaste = (event: ClipboardEvent<HTMLInputElement>) => {
      onPaste?.(event)
      const text = event.clipboardData.getData("text").trim()
      if (!text.startsWith("+") && !text.startsWith("00")) return
      const digits = digitsOf(text).replace(/^00/, "")
      const match = matchDial(digits, countries, code)
      if (!match) return
      event.preventDefault()
      setCode(match.code)
      emit(digits.slice(match.dial.length), match)
    }

    return (
      <div
        className={inputGroupVariants({
          size,
          className: cx(
            "kg-phone-input data-size:gap-1.5 data-size:ps-1",
            "[--_bare-h:calc(var(--_h)-var(--kg-space)*2)]",
            className,
          ),
        })}
        style={style}
        data-size={size}
        data-invalid={control.invalid || undefined}
        data-disabled={control.disabled || undefined}
      >
        <SearchSelect
          variant="bare"
          size={size}
          aria-label={countryLabel}
          options={options}
          value={country?.code ?? null}
          onValueChange={(next) => {
            const target = countries.find((c) => c.code === next)
            setCode(next)
            if (target && national) emit(national, target)
          }}
          disabled={control.disabled}
          renderValue={(option) => (
            <span className="kg-phone-input__country inline-flex items-baseline gap-1.5 tabular-nums">
              <span className="kg-phone-input__iso font-kg-mono text-[0.8em] font-semibold tracking-[0.04em] text-kg-fg-muted">
                {option.value}
              </span>
              <span className="kg-phone-input__dial">{option.aside}</span>
            </span>
          )}
        />
        <span
          className="kg-phone-input__divider self-stretch w-[2px] my-2 shrink-0 bg-kg-ink"
          aria-hidden="true"
        />
        <input
          ref={ref}
          id={control.id}
          type="tel"
          inputMode="tel"
          autoComplete="tel-national"
          className={cx(inputGroupControl, "kg-phone-input__input tabular-nums tracking-[0.01em]")}
          placeholder={placeholder ?? pattern.replace(/#/g, "0")}
          disabled={control.disabled}
          aria-describedby={control.describedBy}
          aria-invalid={control.invalid || undefined}
          aria-errormessage={control.errorMessage}
          aria-required={control.required || undefined}
          value={formatPhone(national, pattern)}
          onChange={(event) => emit(digitsOf(event.target.value))}
          onPaste={handlePaste}
          {...props}
        />
      </div>
    )
  },
)

PhoneInput.displayName = "PhoneInput"

