"use client"

import { type CSSProperties, forwardRef, type HTMLAttributes, useRef } from "react"
import { usePointerVars } from "../../hooks/use-pointer-vars.js"
import { Slot } from "../../primitives/slot.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"

export type PointerLightBlend =
  "normal" | "soft-light" | "overlay" | "plus-lighter" | "screen"

export interface PointerLightProps extends HTMLAttributes<HTMLDivElement> {
  /** Any CSS color. Defaults to a soft sage paper light. */
  color?: string
  /** Radius of the light, in px. */
  size?: number
  /** Strength, 0–1. */
  intensity?: number
  /** How the light combines with the content beneath it. */
  blend?: PointerLightBlend
  /** Light the child element itself instead of wrapping it in a div. */
  asChild?: boolean
}

const lightClass = cx(
  "kg-pointer-light relative isolate",
  "after:pointer-events-none after:absolute after:inset-0 after:z-1 after:rounded-[inherit] after:opacity-0 after:content-['']",
  "after:bg-[radial-gradient(var(--kg-pointer-light-size,280px)_circle_at_var(--kg-pointer-x,50%)_var(--kg-pointer-y,50%),var(--kg-pointer-light-color,color-mix(in_oklab,var(--kg-paper-sage)_70%,transparent)),transparent_70%)]",
  "after:transition-opacity after:duration-(--kg-duration-slow) after:ease-kg-out",
  "data-[pointer=in]:after:opacity-(--kg-pointer-light-intensity)",
  "data-[blend=soft-light]:after:mix-blend-soft-light data-[blend=overlay]:after:mix-blend-overlay",
  "data-[blend=plus-lighter]:after:mix-blend-plus-lighter data-[blend=screen]:after:mix-blend-screen",
)

/**
 * A light that follows the cursor over any surface: an image, a chart, a panel. Unlike a
 * spotlight card it brings no styling of its own and sits over the content, not behind it.
 * One style write per frame, no re-renders.
 */
export const PointerLight = forwardRef<HTMLDivElement, PointerLightProps>(
  (
    {
      color,
      size = 280,
      intensity = 1,
      blend = "normal",
      asChild = false,
      className,
      style,
      ...props
    },
    forwardedRef,
  ) => {
    const local = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(local, forwardedRef)
    usePointerVars(local)
    const Component = asChild ? Slot : "div"

    return (
      <Component
        ref={ref}
        className={cx(lightClass, className)}
        data-blend={blend}
        style={
          {
            ...(color ? { "--kg-pointer-light-color": color } : null),
            "--kg-pointer-light-size": `${Math.max(size, 0)}px`,
            "--kg-pointer-light-intensity": Math.min(Math.max(intensity, 0), 1),
            ...style,
          } as CSSProperties
        }
        {...props}
      />
    )
  },
)

PointerLight.displayName = "PointerLight"

components/pointer-trail/pointer-trail.t:
"use client"

import { forwardRef, type HTMLAttributes, useEffect, useRef } from "react"
import { useReducedMotion } from "../../hooks/use-reduced-motion.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"

export interface PointerTrailProps extends HTMLAttributes<HTMLDivElement> {
  /** How long a point of the trail lives, in ms. */
  life?: number
  /** Width of the trail at its head, in px. */
  width?: number
  /** Paint under the content instead of over it. */
  behind?: boolean
}

interface Point {
  x: number
  y: number
  t: number
}

/**
 * A ribbon of light that follows the pointer across the area and tapers away behind it. Drawn
 * on a canvas only while there is a trail, so an idle area costs nothing. Off under reduced
 * motion and for touch.
 */
export const PointerTrail = forwardRef<HTMLDivElement, PointerTrailProps>(
  (
    { life = 520, width = 14, behind = false, className, children, ...props },
    forwardedRef,
  ) => {
    const local = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(local, forwardedRef)
    const canvasRef = useRef<HTMLCanvasElement>(null)
    const reduced = useReducedMotion()

    useEffect(() => {
      const root = local.current
      const canvas = canvasRef.current
      const ctx = canvas?.getContext?.("2d")
      if (!root || !canvas || !ctx || reduced) return
      const points: Point[] = []
      let frame = 0
      let color = ""
      let size = { w: 0, h: 0 }

      const resize = () => {
        const rect = root.getBoundingClientRect()
        const dpr = Math.min(window.devicePixelRatio || 1, 2)
        size = { w: rect.width, h: rect.height }
        canvas.width = Math.max(1, Math.round(rect.width * dpr))
        canvas.height = Math.max(1, Math.round(rect.height * dpr))
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
        color = getComputedStyle(canvas).color
      }

      const draw = (now: number) => {
        ctx.clearRect(0, 0, size.w, size.h)
        while (points.length && now - (points[0] as Point).t > life) points.shift()
        ctx.lineCap = "round"
        ctx.strokeStyle = color
        for (let i = 1; i < points.length; i++) {
          const a = points[i - 1] as Point
          const b = points[i] as Point
          const age = 1 - Math.min(Math.max(now - b.t, 0) / life, 1)
          ctx.globalAlpha = age * age * 0.9
          ctx.lineWidth = Math.max(width * age, 0.5)
          ctx.beginPath()
          ctx.moveTo(a.x, a.y)
          ctx.lineTo(b.x, b.y)
          ctx.stroke()
        }
        ctx.globalAlpha = 1
        frame = points.length > 1 ? requestAnimationFrame(draw) : 0
        if (!frame) ctx.clearRect(0, 0, size.w, size.h)
      }

      const move = (event: PointerEvent) => {
        if (event.pointerType === "touch") return
        if (!size.w) resize()
        const rect = root.getBoundingClientRect()
        points.push({ x: event.clientX - rect.left, y: event.clientY - rect.top, t: performance.now() })
        if (points.length > 64) points.shift()
        if (!frame) frame = requestAnimationFrame(draw)
      }

      const observer =
        typeof ResizeObserver === "undefined" ? null : new ResizeObserver(resize)
      observer?.observe(root)
      root.addEventListener("pointermove", move, { passive: true })
      return () => {
        cancelAnimationFrame(frame)
        observer?.disconnect()
        root.removeEventListener("pointermove", move)
      }
    }, [reduced, life, width])

    return (
      <div
        ref={ref}
        className={cx("kg-pointer-trail group/trail relative isolate", className)}
        data-behind={behind || undefined}
        {...props}
      >
        <canvas ref={canvasRef} className="kg-pointer-trail__canvas pointer-events-none absolute inset-0 z-1 size-full text-[color:var(--kg-pointer-trail-color,var(--kg-ink))] group-data-behind/trail:-z-1" aria-hidden="true" />
        {children}
      </div>
    )
  },
)

PointerTrail.displayName = "PointerTrail"

