import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
} from "react"
import { cx } from "../../utils/cx.js"
import { variants } from "../../utils/variants.js"
import { discountPercent } from "../../utils/money.js"
import { AddToCartButton } from "../add-to-cart-button/add-to-cart-button.js"
import { Badge, type BadgeTone } from "../badge/badge.js"
import { Price } from "../price/price.js"
import { Rating } from "../rating/rating.js"
import { Skeleton } from "../skeleton/skeleton.js"
import { WishlistButton } from "../wishlist-button/wishlist-button.js"

export type ProductCardVariant = "default" | "minimal" | "horizontal"
export type ProductCardHeadingLevel = "h2" | "h3" | "h4" | "h5" | "h6"

export interface ProductCardImage {
  src: string
  alt: string
  width?: number
  height?: number
}

export interface ProductCardBadge {
  label: string
  tone?: BadgeTone
}

export interface ProductCardSwatch {
  label: string
  /** Any CSS color or gradient. */
  color: string
}

export interface ProductCardLabels {
  /** Visible quick-add text. */
  quickAdd?: ReactNode
  /** Accessible names, which include the product title so every card's buttons are distinct. */
  quickAddLabel?: (title: string) => string
  quickView?: (title: string) => string
  wishlist?: (title: string) => string
  soldOut?: string
  /** Names the swatch list, e.g. "5 colors". */
  colors?: (count: number) => string
  /** Spoken for the "+3" overflow. */
  moreColors?: (count: number) => string
  /** The discount badge text. */
  discount?: (percent: number) => string
}

export interface ProductCardProps extends Omit<HTMLAttributes<HTMLElement>, "title"> {
  title: string
  /** Makes the whole card one link; buttons inside stay separately clickable. */
  href?: string
  vendor?: string
  image?: ProductCardImage
  /** Cross-fades in on hover (fine pointers only). */
  hoverImage?: ProductCardImage
  price?: number
  compareAt?: number
  currency?: string
  locale?: string
  rating?: number
  reviewCount?: number
  badges?: (string | ProductCardBadge)[]
  /** Adds a discount badge when `compareAt` is higher than `price`. */
  showDiscount?: boolean
  soldOut?: boolean
  swatches?: ProductCardSwatch[]
  /** Swatches shown before collapsing the rest into "+N". */
  maxSwatches?: number
  /** Show the wishlist toggle. Implied by `onWishlistChange`. */
  wishlist?: boolean
  wishlisted?: boolean
  onWishlistChange?: (wishlisted: boolean) => void
  /** Shows a quick-add button that slides up over the image on hover and focus. */
  onQuickAdd?: () => void | Promise<unknown>
  onQuickView?: () => void
  variant?: ProductCardVariant
  /** Width / height of the media, e.g. `"4 / 5"`. */
  ratio?: number | string
  headingLevel?: ProductCardHeadingLevel
  /** Load the image eagerly with high priority: use for the first row above the fold. */
  priority?: boolean
  /** Render skeleton placeholders with the same footprint. */
  loading?: boolean
  labels?: ProductCardLabels
  /** Extra content under the price, e.g. a delivery promise. */
  children?: ReactNode
}

const defaultLabels: Required<ProductCardLabels> = {
  quickAdd: "Quick add",
  quickAddLabel: (title) => `Quick add: ${title}`,
  quickView: (title) => `Quick view: ${title}`,
  wishlist: (title) => `Add ${title} to wishlist`,
  soldOut: "Sold out",
  colors: (count) => `${count} colors`,
  moreColors: (count) => `and ${count} more`,
  discount: (percent) => `−${percent}%`,
}

const EyeIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.8"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
)

/* Paper Layers: the photo is a sheet with an ink edge; the actions rise from its bottom edge. */
const cardVariants = variants({
  base: [
    "kg-product-card group/card relative grid min-w-0 rounded-kg-xl text-kg-fg",
    "has-[.kg-product-card\\_\\_link:focus-visible]:outline-2 has-[.kg-product-card\\_\\_link:focus-visible]:outline-offset-4 has-[.kg-product-card\\_\\_link:focus-visible]:outline-kg-ring",
  ],
  variants: {
    variant: {
      default: "grid-rows-[auto_1fr] gap-3",
      minimal: "grid-rows-[auto_1fr] gap-2",
      horizontal: "grid-cols-[minmax(5rem,32%)_minmax(0,1fr)] items-start gap-4",
    },
  },
  defaults: { variant: "default" },
})

const mediaClass =
  "kg-product-card__media relative block aspect-(--_ratio) w-full overflow-hidden rounded-kg-xl border-2 border-kg-ink bg-kg-muted data-placeholder:bg-kg-paper-sage"

const imageClass = [
  "kg-product-card__image absolute inset-0 size-full object-cover",
  "transition-[opacity,scale] duration-(--kg-duration-slower) ease-kg-out pointer-fine:group-hover/card:scale-[1.04]",
  "group-data-sold-out/card:opacity-70 group-data-sold-out/card:[filter:grayscale(0.85)_contrast(0.92)]",
]

const toBadge = (badge: string | ProductCardBadge): ProductCardBadge =>
  typeof badge === "string" ? { label: badge } : badge

const bodyClass = "kg-product-card__body grid min-w-0 content-start px-0.5"

/**
 * A merchandising tile. Server-safe: the hover image, quick-add reveal and stretched link are
 * CSS, and only the wishlist and quick-add buttons hydrate.
 */
export const ProductCard = forwardRef<HTMLElement, ProductCardProps>(
  (
    {
      title,
      href,
      vendor,
      image,
      hoverImage,
      price,
      compareAt,
      currency,
      locale,
      rating,
      reviewCount,
      badges = [],
      showDiscount = true,
      soldOut = false,
      swatches,
      maxSwatches = 4,
      wishlist,
      wishlisted,
      onWishlistChange,
      onQuickAdd,
      onQuickView,
      variant = "default",
      ratio = "4 / 5",
      headingLevel: Heading = "h3",
      priority = false,
      loading = false,
      labels,
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const text = { ...defaultLabels, ...labels }
    const rootProps = {
      ref,
      className: cardVariants({ variant, className }),
      "data-variant": variant,
      style: { "--_ratio": ratio, ...style } as CSSProperties,
      ...props,
    }

    if (loading) {
      return (
        <article {...rootProps} data-loading="" aria-busy="true">
          <Skeleton
            shape="rect"
            className="kg-product-card__media block aspect-(--_ratio) w-full rounded-kg-xl"
            style={{ height: "auto" }}
          />
          <div className={cx(bodyClass, "gap-2")}>
            {vendor !== undefined && <Skeleton width="40%" />}
            <Skeleton width="80%" />
            <Skeleton width="30%" />
          </div>
        </article>
      )
    }

    const percent = price !== undefined ? discountPercent(price, compareAt) : 0
    const flags = [
      ...(soldOut ? [{ label: text.soldOut, tone: "neutral" as const }] : []),
      ...badges.map(toBadge),
      ...(showDiscount && percent > 0 && !soldOut
        ? [{ label: text.discount(percent), tone: "danger" as const }]
        : []),
    ]
    const shownSwatches = swatches?.slice(0, maxSwatches) ?? []
    const hiddenSwatches = (swatches?.length ?? 0) - shownSwatches.length
    const showWishlist = wishlist ?? onWishlistChange !== undefined
    const full = variant !== "minimal"

    return (
      <article {...rootProps} data-sold-out={soldOut || undefined}>
        <div className={mediaClass} data-placeholder={image ? undefined : ""}>
          {image && (
            <img
              className={cx(imageClass)}
              src={image.src}
              alt={image.alt}
              width={image.width}
              height={image.height}
              loading={priority ? "eager" : "lazy"}
              decoding="async"
              {...(priority ? { fetchPriority: "high" as const } : null)}
            />
          )}
          {hoverImage && (
            <img
              className={cx(imageClass, "opacity-0 pointer-fine:group-hover/card:opacity-100")}
              data-hover=""
              src={hoverImage.src}
              alt=""
              loading="lazy"
              decoding="async"
            />
          )}
          {flags.length > 0 && (
            <div className="kg-product-card__badges pointer-events-none absolute start-3 top-3 z-2 flex flex-wrap gap-1.5">
              {flags.map((flag) => (
                <Badge
                  key={flag.label}
                  size="sm"
                  variant="solid"
                  tone={flag.tone ?? "neutral"}
                >
                  {flag.label}
                </Badge>
              ))}
            </div>
          )}
          {showWishlist && (
            <div className="absolute end-2.5 top-2.5 z-2">
              <WishlistButton
                className="kg-product-card__wishlist"
                size="sm"
                pressed={wishlisted}
                onPressedChange={onWishlistChange}
                labels={{ label: text.wishlist(title) }}
              />
            </div>
          )}
          {(onQuickAdd || onQuickView) && (
            <div
              className={cx(
                "kg-product-card__actions absolute inset-x-2.5 bottom-2.5 z-2 gap-2",
                "transition-[translate,opacity] duration-(--kg-duration-base) ease-kg-out",
                "pointer-fine:translate-y-3 pointer-fine:opacity-0 pointer-fine:group-hover/card:translate-y-0 pointer-fine:group-hover/card:opacity-100 pointer-fine:focus-within:translate-y-0 pointer-fine:focus-within:opacity-100",
                variant === "horizontal" ? "hidden" : "flex",
              )}
            >
              {onQuickAdd && (
                <AddToCartButton
                  className="kg-product-card__quick-add flex-auto"
                  size="sm"
                  variant="solid"
                  soldOut={soldOut}
                  onAdd={onQuickAdd}
                  hideIcon
                  aria-label={text.quickAddLabel(title)}
                >
                  {text.quickAdd}
                </AddToCartButton>
              )}
              {onQuickView && (
                <button
                  type="button"
                  className={cx(
                    "kg-product-card__quick-view grid size-(--kg-control-sm) shrink-0 cursor-pointer place-items-center rounded-kg-md border-2 border-kg-ink bg-kg-surface p-0 text-kg-fg shadow-kg-xs",
                    "transition-[background-color,translate,box-shadow] duration-(--kg-duration-fast) ease-kg-out hover:bg-kg-paper-sage active:translate-x-[2px] active:translate-y-[2px] active:shadow-none",
                    "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring [&>svg]:size-[1.05rem]",
                  )}
                  aria-label={text.quickView(title)}
                  aria-haspopup="dialog"
                  onClick={onQuickView}
                >
                  <EyeIcon />
                </button>
              )}
            </div>
          )}
        </div>

        <div className={cx(bodyClass, "gap-1.5")}>
          {full && vendor && (
            <p className="kg-product-card__vendor m-0 text-[0.6875rem] leading-[1.2] font-semibold tracking-[0.09em] text-kg-fg-muted uppercase">
              {vendor}
            </p>
          )}
          <Heading
            className={cx(
              "kg-product-card__title m-0 leading-[1.3] font-semibold tracking-[-0.012em] text-balance",
              variant === "horizontal" ? "text-kg-md" : "text-kg-base",
            )}
          >
            {href ? (
              <a
                className="kg-product-card__link text-inherit no-underline outline-none group-hover/card:underline group-hover/card:decoration-1 group-hover/card:underline-offset-[0.2em] after:absolute after:inset-0 after:z-1 after:rounded-[inherit] after:content-['']"
                href={href}
              >
                {title}
              </a>
            ) : (
              title
            )}
          </Heading>
          {full && rating !== undefined && (
            <Rating
              className="kg-product-card__rating"
              value={rating}
              count={reviewCount}
              size="sm"
              locale={locale}
            />
          )}
          {price !== undefined && (
            <Price
              className="kg-product-card__price"
              amount={price}
              compareAt={compareAt}
              currency={currency}
              locale={locale}
              savings={false}
            />
          )}
          {full && shownSwatches.length > 0 && (
            <ul
              className="kg-product-card__swatches m-0 mt-1 flex list-none flex-wrap items-center gap-1.5 p-0"
              aria-label={text.colors(swatches?.length ?? 0)}
            >
              {shownSwatches.map((swatch) => (
                <li
                  key={swatch.label}
                  className="kg-product-card__swatch size-3 rounded-full border-[1.5px] border-kg-ink [background:var(--_swatch)]"
                  title={swatch.label}
                  style={{ "--_swatch": swatch.color } as CSSProperties}
                >
                  <span className="kg-visually-hidden">{swatch.label}</span>
                </li>
              ))}
              {hiddenSwatches > 0 && (
                <li className="kg-product-card__more text-kg-xs text-kg-fg-muted">
                  <span aria-hidden="true">+{hiddenSwatches}</span>
                  <span className="kg-visually-hidden">
                    {text.moreColors(hiddenSwatches)}
                  </span>
                </li>
              )}
            </ul>
          )}
          {children}
        </div>
      </article>
    )
  },
)

ProductCard.displayName = "ProductCard"

components/product-compare/product-compa:
"use client"

import { forwardRef, type HTMLAttributes, type ReactNode, useState } from "react"
import { cx } from "../../utils/cx.js"
import { Price } from "../price/price.js"
import { Switch } from "../switch/switch.js"

export type ProductCompareSpec = string | number | boolean | null | undefined

export interface ProductCompareProduct {
  id: string
  name: string
  image?: string
  href?: string
  price: number
  compareAt?: number
  /** Values keyed by attribute key. Booleans render as marks. */
  specs: Record<string, ProductCompareSpec>
}

export interface ProductCompareAttribute {
  key: string
  label: string
}

export interface ProductCompareLabels {
  caption?: string
  differences?: string
  remove?: (name: string) => string
  yes?: string
  no?: string
  attribute?: string
}

export interface ProductCompareProps extends HTMLAttributes<HTMLDivElement> {
  products: readonly ProductCompareProduct[]
  attributes: readonly ProductCompareAttribute[]
  currency?: string
  locale?: string
  onRemove?: (id: string) => void
  /** Footer cell per product, e.g. an add-to-cart button. */
  renderAction?: (product: ProductCompareProduct) => ReactNode
  defaultDifferencesOnly?: boolean
  labels?: ProductCompareLabels
}

const defaultLabels: Required<ProductCompareLabels> = {
  caption: "Compare products",
  differences: "Only differences",
  remove: (name) => `Remove ${name} from comparison`,
  yes: "Yes",
  no: "No",
  attribute: "Attribute",
}

/**
 * Side-by-side spec table. Rows where every product matches can be hidden, and rows that differ
 * are tinted so the eye lands on what actually separates the options.
 */
export const ProductCompare = forwardRef<HTMLDivElement, ProductCompareProps>(
  (
    {
      products,
      attributes,
      currency = "USD",
      locale,
      onRemove,
      renderAction,
      defaultDifferencesOnly = false,
      labels,
      className,
      ...props
    },
    ref,
  ) => {
    const text = { ...defaultLabels, ...labels }
    const [differencesOnly, setDifferencesOnly] = useState(defaultDifferencesOnly)
    const rows = attributes.map((attribute) => {
      const values = products.map((product) => product.specs[attribute.key])
      const differs = new Set(values.map((value) => String(value ?? ""))).size > 1
      return { attribute, values, differs }
    })
    const visible = differencesOnly ? rows.filter((row) => row.differs) : rows

    const cell = (value: ProductCompareSpec) =>
      value === true ? (
        <span
          className="kg-product-compare__mark inline-grid size-5 place-items-center rounded-full bg-kg-accent text-kg-accent-fg [&_svg]:size-[0.8rem]"
          data-value="yes"
        >
          <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
            <path d="m3.5 8.5 3 3 6-7" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <span className="kg-visually-hidden">{text.yes}</span>
        </span>
      ) : value === false || value == null ? (
        <span className="kg-product-compare__mark inline-grid place-items-center text-kg-fg-faint" data-value="no">
          <span aria-hidden="true">-</span>
          <span className="kg-visually-hidden">{text.no}</span>
        </span>
      ) : (
        value
      )

    return (
      <div ref={ref} className={cx("kg-product-compare grid gap-3 text-kg-fg", className)} {...props}>
        <div className="kg-product-compare__toolbar flex justify-end">
          <Switch
            size="sm"
            label={text.differences}
            checked={differencesOnly}
            onCheckedChange={setDifferencesOnly}
          />
        </div>
        <div className="kg-product-compare__scroll overflow-x-auto rounded-kg-xl border-2 border-kg-ink bg-kg-surface shadow-kg-sm">
          <table
            className="kg-product-compare__table w-full table-fixed border-collapse text-kg-sm"
            style={{ minWidth: `calc(9rem + ${products.length} * 10rem)` }}
          >
            <caption className="kg-visually-hidden">{text.caption}</caption>
            <thead>
              <tr>
                <td className="kg-product-compare__corner w-36 px-4 py-3 align-middle" />
                {products.map((product) => (
                  <th key={product.id} scope="col" className="kg-product-compare__product px-4 py-3 text-start align-top font-[inherit]">
                    <div className="kg-product-compare__head relative grid gap-1.5">
                      {onRemove && (
                        <button
                          type="button"
                          className="kg-product-compare__remove absolute end-1.5 top-1.5 z-1 grid size-7 cursor-pointer place-items-center rounded-full border-2 border-kg-ink bg-kg-surface p-0 text-kg-fg shadow-kg-xs transition-[translate,box-shadow] duration-(--kg-duration-fast) ease-kg-out hover:-translate-px hover:shadow-kg-sm active:translate-0 active:shadow-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring [&_svg]:size-[0.8rem]"
                          aria-label={text.remove(product.name)}
                          onClick={() => onRemove(product.id)}
                        >
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
                            <path d="M7 7l10 10M17 7 7 17" strokeLinecap="round" />
                          </svg>
                        </button>
                      )}
                      <span
                        className="kg-product-compare__image mb-1.5 block aspect-square overflow-hidden rounded-kg-lg border-2 border-kg-ink bg-kg-muted data-placeholder:bg-kg-paper-sage"
                        data-placeholder={product.image ? undefined : ""}
                      >
                        {product.image && (
                          <img className="kg-product-compare__img size-full object-cover" src={product.image} alt="" />
                        )}
                      </span>
                      {product.href ? (
                        <a
                          className="kg-product-compare__name rounded-kg-xs font-semibold text-inherit no-underline hover:underline hover:underline-offset-3 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring"
                          href={product.href}
                        >
                          {product.name}
                        </a>
                      ) : (
                        <span className="kg-product-compare__name font-semibold">{product.name}</span>
                      )}
                      <Price
                        amount={product.price}
                        compareAt={product.compareAt}
                        currency={currency}
                        locale={locale}
                        size="sm"
                        savings={false}
                      />
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {visible.map(({ attribute, values, differs }) => (
                <tr
                  key={attribute.key}
                  className="kg-product-compare__row group/row border-t border-kg-border"
                  data-differs={differs || undefined}
                >
                  <th
                    scope="row"
                    className="kg-product-compare__attribute px-4 py-3 align-middle text-start font-medium text-kg-fg-muted group-data-differs/row:bg-kg-paper-butter group-data-differs/row:text-kg-fg group-data-differs/row:shadow-[inset_3px_0_0_var(--kg-ink)]"
                  >
                    {attribute.label}
                  </th>
                  {values.map((value, index) => (
                    <td
                      key={products[index]?.id ?? index}
                      className="kg-product-compare__cell px-4 py-3 align-middle tabular-nums group-data-differs/row:bg-kg-paper-butter"
                    >
                      {cell(value)}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
            {renderAction && (
              <tfoot>
                <tr className="kg-product-compare__foot">
                  <td className="border-t border-kg-border" />
                  {products.map((product) => (
                    <td key={product.id} className="kg-product-compare__action border-t border-kg-border px-4 py-3 align-middle">
                      {renderAction(product)}
                    </td>
                  ))}
                </tr>
              </tfoot>
            )}
          </table>
        </div>
      </div>
    )
  },
)

ProductCompare.displayName = "ProductCompare"

components/product-gallery/product-galle:
"use client"

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type KeyboardEvent,
  type MouseEvent,
  type PointerEvent,
  useEffect,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { useReducedMotion } from "../../hooks/use-reduced-motion.js"
import { cx } from "../../utils/cx.js"
import { clamp } from "../../utils/math.js"
import { Dialog, DialogContent, DialogTitle } from "../dialog/dialog.js"
import { IconButton } from "../icon-button/icon-button.js"

const arrowSlot =
  "absolute top-1/2 z-2 -translate-y-1/2 opacity-0 transition-opacity duration-(--kg-duration-base) ease-kg-out group-hover/stage:opacity-100 group-focus-within/stage:opacity-100 [@media(hover:none)]:hidden"

export type ProductGalleryThumbnails = "horizontal" | "vertical" | "none"

export interface ProductGalleryImage {
  src: string
  alt: string
  width?: number
  height?: number
  /** Smaller file for the thumbnail strip. */
  thumbnail?: string
  /** Larger file for the hover zoom and the lightbox. */
  zoomSrc?: string
}

export interface ProductGalleryLabels {
  /** Names the carousel region. */
  region?: string
  previous?: string
  next?: string
  /** Slide names and the live status, e.g. "Image 2 of 6". */
  slide?: (position: number, total: number) => string
  thumbnail?: (position: number, total: number) => string
  open?: (position: number, total: number) => string
  lightbox?: string
  zoomIn?: string
  zoomOut?: string
  close?: string
}

export interface ProductGalleryProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  images: readonly ProductGalleryImage[]
  index?: number
  defaultIndex?: number
  onIndexChange?: (index: number) => void
  /** Width / height of the stage. Defaults to the first image's size, else 4 / 5. */
  ratio?: number | string
  thumbnails?: ProductGalleryThumbnails
  /** Magnify under the pointer on hover (mouse and trackpad only). */
  zoom?: boolean
  zoomScale?: number
  /** Open a fullscreen viewer on click. */
  lightbox?: boolean
  /** Load the first image eagerly with high priority (above-the-fold product pages). */
  priority?: boolean
  labels?: ProductGalleryLabels
}

const defaultLabels: Required<ProductGalleryLabels> = {
  region: "Product images",
  previous: "Previous image",
  next: "Next image",
  slide: (position, total) => `Image ${position} of ${total}`,
  thumbnail: (position, total) => `Show image ${position} of ${total}`,
  open: (position, total) => `Open image ${position} of ${total} in fullscreen`,
  lightbox: "Image viewer",
  zoomIn: "Zoom in",
  zoomOut: "Zoom out",
  close: "Close",
}

const Chevron = ({ flip = false }: { flip?: boolean }) => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
    style={flip ? { transform: "scaleX(-1)" } : undefined}
  >
    <path d="m9 6 6 6-6 6" />
  </svg>
)

const KEYS_NEXT = new Set(["ArrowRight", "ArrowDown"])
const KEYS_PREV = new Set(["ArrowLeft", "ArrowUp"])

const isRtl = (node: Element) => getComputedStyle(node).direction === "rtl"

/**
 * Product media: a scroll-snap stage (swipe on touch), arrows, thumbnails, keyboard support,
 * hover zoom on fine pointers and a fullscreen lightbox built on Dialog.
 */
export const ProductGallery = forwardRef<HTMLDivElement, ProductGalleryProps>(
  (
    {
      images,
      index: indexProp,
      defaultIndex = 0,
      onIndexChange,
      ratio,
      thumbnails = "horizontal",
      zoom = true,
      zoomScale = 2.2,
      lightbox = true,
      priority = false,
      labels,
      className,
      style,
      onKeyDown,
      ...props
    },
    ref,
  ) => {
    const text = { ...defaultLabels, ...labels }
    const total = images.length
    const [rawIndex, setIndex] = useControllableState({
      value: indexProp,
      defaultValue: defaultIndex,
      onChange: onIndexChange,
    })
    const index = clamp(rawIndex, 0, Math.max(total - 1, 0))
    const reduced = useReducedMotion()
    const track = useRef<HTMLDivElement>(null)
    const zoomPanes = useRef<(HTMLSpanElement | null)[]>([])
    const syncing = useRef<number | null>(null)
    const positioned = useRef(false)
    const [viewerOpen, setViewerOpen] = useState(false)
    const [zoomed, setZoomed] = useState(false)
    const viewerImage = useRef<HTMLImageElement>(null)

    const first = images[0]
    const stageRatio =
      ratio ??
      (first?.width && first.height ? `${first.width} / ${first.height}` : "4 / 5")

    const go = (next: number) => {
      if (total === 0) return
      setIndex(((next % total) + total) % total)
    }

    // Brings the scroller to `index` whenever it changes from outside a swipe.
    useEffect(() => {
      const node = track.current
      if (!node || !node.clientWidth) return
      const current = Math.round(Math.abs(node.scrollLeft) / node.clientWidth)
      const initial = !positioned.current
      positioned.current = true
      if (current === index) return
      syncing.current = index
      node.scrollTo?.({
        left: (isRtl(node) ? -1 : 1) * index * node.clientWidth,
        behavior: reduced || initial ? "auto" : "smooth",
      })
    }, [index, reduced])

    const handleScroll = () => {
      const node = track.current
      if (!node || !node.clientWidth) return
      const current = Math.round(Math.abs(node.scrollLeft) / node.clientWidth)
      if (syncing.current !== null) {
        if (current === syncing.current) syncing.current = null
        return
      }
      if (current !== index) setIndex(current)
    }

    const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(event)
      if (event.defaultPrevented) return
      const target = event.target as HTMLElement
      if (target.closest("input, textarea, select, [contenteditable]")) return
      const rtl = isRtl(event.currentTarget)
      let next: number | null = null
      if (event.key === "Home") next = 0
      else if (event.key === "End") next = total - 1
      else if (KEYS_NEXT.has(event.key))
        next = index + (rtl && event.key === "ArrowRight" ? -1 : 1)
      else if (KEYS_PREV.has(event.key))
        next = index - (rtl && event.key === "ArrowLeft" ? -1 : 1)
      if (next === null) return
      // Up/Down only drive the vertical thumbnail strip; elsewhere they keep scrolling the page.
      if (
        (event.key === "ArrowUp" || event.key === "ArrowDown") &&
        !(thumbnails === "vertical" && target.closest(".kg-product-gallery__thumbs"))
      ) {
        return
      }
      event.preventDefault()
      const resolved = ((next % total) + total) % total
      go(resolved)
      // Roving focus: keep the keyboard on the same kind of control for the new image.
      const part =
        target.closest<HTMLElement>("[data-gallery-part]")?.dataset.galleryPart
      if (part) {
        event.currentTarget
          .querySelector<HTMLElement>(
            `[data-gallery-part="${part}"][data-index="${resolved}"]`,
          )
          ?.focus({ preventScroll: true })
      }
    }

    const canZoom = (event: PointerEvent) =>
      zoom && event.pointerType === "mouse" && !reduced && !viewerOpen

    const moveZoom = (event: PointerEvent<HTMLElement>) => {
      const pane = zoomPanes.current[index]
      if (!pane || !canZoom(event)) return
      const rect = event.currentTarget.getBoundingClientRect()
      const x = clamp(((event.clientX - rect.left) / rect.width) * 100, 0, 100)
      const y = clamp(((event.clientY - rect.top) / rect.height) * 100, 0, 100)
      if (!pane.dataset.active) {
        const image = images[index]
        if (!image) return
        pane.style.backgroundImage = `url("${image.zoomSrc ?? image.src}")`
        pane.dataset.active = ""
      }
      pane.style.backgroundPosition = `${x}% ${y}%`
    }

    const endZoom = () => {
      for (const pane of zoomPanes.current) if (pane) delete pane.dataset.active
    }

    const openViewer = () => {
      endZoom()
      setZoomed(false)
      setViewerOpen(true)
    }

    const toggleViewerZoom = (event: MouseEvent<HTMLButtonElement>) => {
      const img = viewerImage.current
      if (img) {
        const rect = img.getBoundingClientRect()
        const x = rect.width ? ((event.clientX - rect.left) / rect.width) * 100 : 50
        const y = rect.height ? ((event.clientY - rect.top) / rect.height) * 100 : 50
        img.style.transformOrigin = `${clamp(x, 0, 100)}% ${clamp(y, 0, 100)}%`
      }
      setZoomed((value) => !value)
    }

    const panViewer = (event: PointerEvent<HTMLButtonElement>) => {
      const img = viewerImage.current
      if (!zoomed || !img) return
      const rect = event.currentTarget.getBoundingClientRect()
      const x = clamp(((event.clientX - rect.left) / rect.width) * 100, 0, 100)
      const y = clamp(((event.clientY - rect.top) / rect.height) * 100, 0, 100)
      img.style.transformOrigin = `${x}% ${y}%`
    }

    const current = images[index]
    const layout = total > 1 ? thumbnails : "none"
    const vertical = layout === "vertical"

    return (
      <div
        ref={ref}
        className={cx(
          "kg-product-gallery grid min-w-0 gap-3 [--_thumb:4.5rem]",
          vertical && "grid-cols-[var(--_thumb)_minmax(0,1fr)] items-start max-sm:grid-cols-[minmax(0,1fr)]",
          className,
        )}
        data-thumbnails={total > 1 ? thumbnails : "none"}
        role="region"
        aria-roledescription="carousel"
        aria-label={text.region}
        style={
          { "--_ratio": stageRatio, "--_zoom": zoomScale, ...style } as CSSProperties
        }
        onKeyDown={handleKeyDown}
        {...props}
      >
        <div
          className="kg-product-gallery__stage group/stage relative min-w-0 overflow-hidden rounded-[var(--_radius,var(--kg-radius-xl))] border-solid border-kg-ink [border-width:var(--_edge,2px)] bg-kg-muted data-placeholder:bg-kg-paper-sage"
          data-placeholder={total === 0 ? "" : undefined}
        >
          <div
            ref={track}
            className="kg-product-gallery__track flex aspect-(--_ratio) snap-x snap-mandatory overflow-x-auto overscroll-x-contain [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
            onScroll={handleScroll}
            onPointerDown={() => {
              syncing.current = null
            }}
            onWheel={() => {
              syncing.current = null
            }}
          >
            {images.map((image, i) => {
              const active = i === index
              const media = (
                <>
                  <img
                    className="kg-product-gallery__image block size-full object-cover select-none"
                    src={image.src}
                    alt={image.alt}
                    width={image.width}
                    height={image.height}
                    loading={Math.abs(i - index) <= 1 ? "eager" : "lazy"}
                    decoding="async"
                    draggable={false}
                    {...(priority && i === 0
                      ? { fetchPriority: "high" as const }
                      : null)}
                  />
                  {zoom && (
                    <span
                      ref={(node) => {
                        zoomPanes.current[i] = node
                      }}
                      className="kg-product-gallery__zoom pointer-events-none absolute inset-0 bg-kg-surface bg-[length:calc(var(--_zoom)*100%)] bg-no-repeat opacity-0 transition-opacity duration-(--kg-duration-base) ease-kg-out data-active:opacity-100"
                      aria-hidden="true"
                    />
                  )}
                </>
              )
              return (
                <div
                  key={`${image.src}-${i}`}
                  className="kg-product-gallery__slide relative shrink-0 grow-0 basis-full snap-center snap-always overflow-hidden"
                  role="group"
                  aria-roledescription="slide"
                  aria-label={text.slide(i + 1, total)}
                  aria-hidden={!active || undefined}
                  data-active={active || undefined}
                  onPointerMove={active ? moveZoom : undefined}
                  onPointerLeave={endZoom}
                >
                  {lightbox ? (
                    <button
                      type="button"
                      className="kg-product-gallery__open block size-full cursor-zoom-in border-0 bg-transparent p-0 outline-none focus-visible:rounded-kg-xl focus-visible:outline-2 focus-visible:-outline-offset-4 focus-visible:outline-kg-ring"
                      aria-label={text.open(i + 1, total)}
                      aria-haspopup="dialog"
                      tabIndex={active ? 0 : -1}
                      data-gallery-part="slide"
                      data-index={i}
                      onClick={openViewer}
                    >
                      {media}
                    </button>
                  ) : (
                    media
                  )}
                </div>
              )
            })}
          </div>

          {total > 1 && (
            <>
              {/* Touch devices swipe instead; the arrows would only cover the product. */}
              <div className={cx(arrowSlot, "start-3")}>
                <IconButton
                  className="kg-product-gallery__arrow rtl:[&_svg]:-scale-x-100"
                  data-direction="previous"
                  label={text.previous}
                  icon={<Chevron flip />}
                  variant="outline"
                  size="sm"
                  round
                  onClick={() => go(index - 1)}
                />
              </div>
              <div className={cx(arrowSlot, "end-3")}>
                <IconButton
                  className="kg-product-gallery__arrow rtl:[&_svg]:-scale-x-100"
                  data-direction="next"
                  label={text.next}
                  icon={<Chevron />}
                  variant="outline"
                  size="sm"
                  round
                  onClick={() => go(index + 1)}
                />
              </div>
              <div
                className={cx(
                  "kg-product-gallery__dots absolute bottom-3 left-1/2 -translate-x-1/2 gap-1.5 rounded-full border-2 border-kg-ink bg-kg-surface px-2.5 py-1.5",
                  layout === "none" ? "flex" : "hidden max-sm:flex",
                )}
                aria-hidden="true"
              >
                {images.map((image, i) => (
                  <span
                    key={`${image.src}-${i}`}
                    className="size-1.5 rounded-full bg-kg-fg opacity-30 transition-[opacity,scale] duration-(--kg-duration-base) ease-kg-out data-active:scale-[1.3] data-active:opacity-100"
                    data-active={i === index || undefined}
                  />
                ))}
              </div>
            </>
          )}
          <span className="kg-visually-hidden" aria-live="polite" aria-atomic="true">
            {total > 1 ? text.slide(index + 1, total) : ""}
          </span>
        </div>

        {total > 1 && thumbnails !== "none" && (
          <div
            className={cx(
              "kg-product-gallery__thumbs flex min-w-0 gap-2 p-[2px] [scrollbar-width:none] max-sm:hidden",
              vertical
                ? "col-start-1 row-start-1 flex-col self-stretch overflow-x-hidden overflow-y-auto [contain:size]"
                : "overflow-x-auto overflow-y-hidden",
            )}
          >
            {images.map((image, i) => (
              <button
                key={`${image.src}-${i}`}
                type="button"
                className={cx(
                  "kg-product-gallery__thumb aspect-(--_ratio) shrink-0 grow-0 basis-(--_thumb) cursor-pointer overflow-hidden rounded-kg-md border-2 border-kg-border bg-kg-muted p-0 opacity-65",
                  "transition-[opacity,border-color,box-shadow] duration-(--kg-duration-fast) ease-kg-out hover:opacity-100",
                  "aria-[current=true]:border-kg-ink aria-[current=true]:opacity-100 aria-[current=true]:shadow-kg-xs",
                  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring [&>img]:block [&>img]:size-full [&>img]:object-cover",
                )}
                aria-label={text.thumbnail(i + 1, total)}
                aria-current={i === index || undefined}
                tabIndex={i === index ? 0 : -1}
                data-gallery-part="thumb"
                data-index={i}
                onClick={() => go(i)}
              >
                <img
                  src={image.thumbnail ?? image.src}
                  alt=""
                  loading="lazy"
                  decoding="async"
                />
              </button>
            ))}
          </div>
        )}

        {lightbox && (
          <Dialog open={viewerOpen} onOpenChange={setViewerOpen}>
            <DialogContent
              size="full"
              className="kg-product-gallery__viewer [--_dialog-bg:var(--kg-bg)]"
              closeLabel={text.close}
              onKeyDown={(event) => {
                if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
                  event.preventDefault()
                  const rtl = isRtl(event.currentTarget)
                  const forward = (event.key === "ArrowRight") !== rtl
                  setZoomed(false)
                  go(index + (forward ? 1 : -1))
                }
              }}
            >
              <DialogTitle className="kg-visually-hidden">
                {text.lightbox}
              </DialogTitle>
              {current && (
                <button
                  type="button"
                  className={cx(
                    "kg-product-gallery__viewer-stage relative grid min-h-0 flex-auto cursor-zoom-in place-items-center overflow-hidden border-0 bg-transparent p-4 outline-none",
                    "focus-visible:outline-2 focus-visible:-outline-offset-4 focus-visible:outline-kg-ring data-zoomed:cursor-zoom-out data-zoomed:touch-none",
                    "[&>img]:absolute [&>img]:inset-0 [&>img]:size-full [&>img]:object-contain [&>img]:p-4 [&>img]:select-none",
                    "[&>img]:transition-[scale] [&>img]:duration-(--kg-duration-slow) [&>img]:ease-kg-out data-zoomed:[&>img]:scale-(--_zoom)",
                  )}
                  data-zoomed={zoomed || undefined}
                  aria-label={zoomed ? text.zoomOut : text.zoomIn}
                  aria-pressed={zoomed}
                  onClick={toggleViewerZoom}
                  onPointerMove={panViewer}
                >
                  <img
                    ref={viewerImage}
                    key={current.src}
                    src={current.zoomSrc ?? current.src}
                    alt={current.alt}
                    draggable={false}
                  />
                </button>
              )}
              {total > 1 && (
                <div className="kg-product-gallery__viewer-bar flex items-center justify-center gap-4 px-4 pt-3 pb-[max(calc(var(--kg-space)*4),env(safe-area-inset-bottom))]">
                  <IconButton
                    label={text.previous}
                    icon={<Chevron flip />}
                    variant="outline"
                    round
                    onClick={() => {
                      setZoomed(false)
                      go(index - 1)
                    }}
                  />
                  <span
                    className="kg-product-gallery__counter min-w-16 text-center text-kg-sm font-[550] text-kg-fg-muted tabular-nums"
                    aria-live="polite"
                  >
                    <span className="kg-visually-hidden">
                      {text.slide(index + 1, total)}
                    </span>
                    <span aria-hidden="true">
                      {index + 1} / {total}
                    </span>
                  </span>
                  <IconButton
                    label={text.next}
                    icon={<Chevron />}
                    variant="outline"
                    round
                    onClick={() => {
                      setZoomed(false)
                      go(index + 1)
                    }}
                  />
                </div>
              )}
            </DialogContent>
          </Dialog>
        )}
      </div>
    )
  },
)

