export const ProjectCard = forwardRef<HTMLElement, ProjectCardProps>(
  (
    { name, domain, href, icon, state, commit, branch, updated, actions, labels, className, ...props },
    ref,
  ) => {
    const nameId = useId()
    const words = { ...stateWords, ...labels }
    return (
      <article
        ref={ref}
        aria-labelledby={nameId}
        className={cx(
          /* Paper Layers: a white sheet; a linked card lifts on hover and the whole sheet is the hit area. */
          "kg-project-card relative grid min-w-0 gap-3 p-4",
          "rounded-kg-xl border-2 border-kg-ink bg-kg-surface text-kg-fg shadow-kg-sm",
          "transition-[translate,box-shadow] duration-(--kg-duration-base) ease-kg-out motion-reduce:transition-none",
          "data-linked:hover:-translate-y-0.5 data-linked:hover:shadow-kg-md",
          String.raw`has-[.kg-project-card\_\_link:focus-visible]:outline-2 has-[.kg-project-card\_\_link:focus-visible]:outline-offset-2 has-[.kg-project-card\_\_link:focus-visible]:outline-kg-ring`,
          className,
        )}
        data-state={state}
        data-linked={href ? "" : undefined}
        {...props}
      >
        <header className="kg-project-card__head flex min-w-0 items-center gap-3">
          <span
            className={cx(
              "kg-project-card__icon grid size-9 shrink-0 place-items-center rounded-full border-2 border-kg-ink",
              "text-kg-sm font-bold uppercase text-kg-fg [&_svg]:size-4.5",
              papers[hueFromString(name) % papers.length],
            )}
            aria-hidden="true"
          >
            {icon ?? name.trim()[0]}
          </span>
          <div className="kg-project-card__who grid min-w-0 flex-1">
            <h3 id={nameId} className="kg-project-card__name m-0 truncate text-kg-sm font-semibold text-kg-fg">
              {href ? (
                <a
                  className="kg-project-card__link text-inherit no-underline outline-none after:absolute after:inset-0 after:rounded-[inherit] after:content-['']"
                  href={href}
                >
                  {name}
                </a>
              ) : (
                name
              )}
            </h3>
            {domain && <span className="kg-project-card__domain truncate text-kg-xs text-kg-fg-muted">{domain}</span>}
          </div>
          {actions != null && <div className="kg-project-card__actions relative z-1 shrink-0">{actions}</div>}
        </header>
        {(commit != null || state) && (
          <div className="kg-project-card__deploy grid gap-1 rounded-kg-md bg-kg-surface-sunken px-3 py-2.5">
            {state && (
              <span
                className="kg-project-card__state inline-flex items-center gap-1.5 text-kg-xs font-semibold text-kg-fg"
                data-state={state}
              >
                <span
                  className={cx("kg-project-card__dot size-2 rounded-full", dotClass[state])}
                  aria-hidden="true"
                />
                {words[state]}
              </span>
            )}
            {commit != null && <span className="kg-project-card__commit truncate text-kg-xs text-kg-fg-muted">{commit}</span>}
          </div>
        )}
        {(branch != null || updated != null) && (
          <footer className="kg-project-card__foot flex items-center justify-between gap-2 text-kg-xs text-kg-fg-muted">
            {branch != null && (
              <span className="kg-project-card__branch inline-flex min-w-0 items-center gap-1.25 truncate font-kg-mono [&_svg]:size-3.5 [&_svg]:shrink-0">
                <svg viewBox="0 0 16 16" fill="none" aria-hidden="true">
                  <circle cx="4.5" cy="3.5" r="1.5" stroke="currentColor" strokeWidth="1.3" />
                  <circle cx="4.5" cy="12.5" r="1.5" stroke="currentColor" strokeWidth="1.3" />
                  <circle cx="11.5" cy="5.5" r="1.5" stroke="currentColor" strokeWidth="1.3" />
                  <path d="M4.5 5v6M11.5 7c0 2.5-3 2.5-7 4" stroke="currentColor" strokeWidth="1.3" />
                </svg>
                {branch}
              </span>
            )}
            {updated != null && <span className="kg-project-card__updated">{updated}</span>}
          </footer>
        )}
      </article>
    )
  },
)

ProjectCard.displayName = "ProjectCard"

components/prompt-input/prompt-input.tsx:
"use client"

import {
  type CSSProperties,
  type FormEvent,
  type FormHTMLAttributes,
  forwardRef,
  type KeyboardEvent,
  type ReactNode,
  type Ref,
  useRef,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { useIsomorphicLayoutEffect } from "../../hooks/use-isomorphic-layout-effect.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"
import { SendIcon } from "../chat-message/internal/icons.js"

export interface PromptInputProps extends Omit<
  FormHTMLAttributes<HTMLFormElement>,
  "onSubmit" | "onChange" | "defaultValue"
> {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Called with the text on Enter or the send button. Empty drafts never submit. */
  onSubmit?: (value: string) => void
  /** An answer is being written: the send button becomes a stop button. */
  streaming?: boolean
  onStop?: () => void
  /** Accessible name of the textarea. */
  label?: string
  placeholder?: string
  disabled?: boolean
  /** The textarea grows with its text up to this many rows, then scrolls. */
  maxRows?: number
  maxLength?: number
  /** Files or context chips, shown above the text. */
  attachments?: ReactNode
  /** Controls at the start of the footer, e.g. an attach button or a model picker. */
  toolbar?: ReactNode
  /** Quiet text in the footer. Defaults to the keyboard hint. */
  hint?: ReactNode
  sendLabel?: string
  stopLabel?: string
  /** Clear the draft after it submits. Uncontrolled only. */
  clearOnSubmit?: boolean
  inputRef?: Ref<HTMLTextAreaElement>
}

const supportsFieldSizing = (): boolean =>
  typeof CSS !== "undefined" && typeof CSS.supports === "function"
    ? CSS.supports("field-sizing", "content")
    : false

const button = cx(
  "kg-prompt-input__button grid size-(--kg-control-sm) shrink-0 cursor-pointer place-items-center rounded-full border-2 p-0 text-[1rem]",
  "transition-[background-color,scale] duration-(--kg-duration-fast) ease-kg-out interactive:active:scale-90",
  "animate-[kg-pop-in_var(--kg-duration-spring)_var(--kg-ease-spring)] motion-reduce:animate-none",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
)

/**
 * The box a question is typed into. Enter sends, Shift+Enter adds a line, and Enter while an
 * IME is composing picks the candidate instead. While an answer streams, send turns into stop.
 */
export const PromptInput = forwardRef<HTMLFormElement, PromptInputProps>(
  (
    {
      value: valueProp,
      defaultValue = "",
      onValueChange,
      onSubmit,
      streaming = false,
      onStop,
      label = "Message",
      placeholder = "Ask anything",
      disabled = false,
      maxRows = 8,
      maxLength,
      attachments,
      toolbar,
      hint = "Enter to send, Shift+Enter for a new line",
      sendLabel = "Send",
      stopLabel = "Stop",
      clearOnSubmit = true,
      inputRef,
      className,
      style,
      ...props
    },
    ref,
  ) => {
    const [value, setValue] = useControllableState({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    })
    const local = useRef<HTMLTextAreaElement>(null)
    const textareaRef = useComposedRefs(local, inputRef)
    const empty = value.trim().length === 0

    useIsomorphicLayoutEffect(() => {
      const node = local.current
      if (!node || supportsFieldSizing()) return
      const borders = node.offsetHeight - node.clientHeight
      node.style.height = "auto"
      node.style.height = `${node.scrollHeight + borders}px`
    }, [value])

    const send = () => {
      if (empty || streaming || disabled) return
      onSubmit?.(value)
      if (clearOnSubmit) setValue("")
    }

    const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault()
      send()
    }

    const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
      if (event.key !== "Enter" || event.shiftKey || event.nativeEvent.isComposing)
        return
      event.preventDefault()
      send()
    }

    return (
      <form
        ref={ref}
        className={cx(
          "kg-prompt-input flex w-full min-w-0 flex-col rounded-kg-2xl border-2 border-kg-ink bg-kg-surface text-kg-base text-kg-fg shadow-kg-sm",
          "transition-[box-shadow,background-color] duration-(--kg-duration-base) ease-kg-out",
          "focus-within:not-data-disabled:shadow-kg-md focus-within:outline-2 focus-within:outline-offset-2 focus-within:outline-kg-ring",
          "data-disabled:bg-kg-muted data-disabled:opacity-60 data-disabled:shadow-none",
          className,
        )}
        data-disabled={disabled || undefined}
        data-streaming={streaming || undefined}
        style={{ "--kg-prompt-rows": maxRows, ...style } as CSSProperties}
        onSubmit={handleSubmit}
        {...props}
      >
        {attachments != null && (
          <div className="kg-prompt-input__attachments flex flex-wrap gap-1.5 px-3 pt-2.5">{attachments}</div>
        )}
        <textarea
          ref={textareaRef}
          className="kg-prompt-input__textarea m-0 block max-h-[calc(1.5em*var(--kg-prompt-rows,8)+var(--kg-space)*4)] min-h-[calc(1.5em+var(--kg-space)*4)] w-full resize-none overflow-y-auto border-0 bg-transparent px-3.5 pt-3 pb-1 [font:inherit] leading-[1.5em] text-inherit outline-none [field-sizing:content] placeholder:text-kg-fg-faint disabled:cursor-not-allowed"
          aria-label={label}
          rows={1}
          value={value}
          maxLength={maxLength}
          placeholder={placeholder}
          disabled={disabled}
          onChange={(event) => setValue(event.currentTarget.value)}
          onKeyDown={handleKeyDown}
        />
        <div className="kg-prompt-input__footer flex items-center gap-2 px-2 pb-2">
          {toolbar != null && (
            <div className="kg-prompt-input__toolbar flex items-center gap-0.5">{toolbar}</div>
          )}
          <span className="kg-prompt-input__hint min-w-0 flex-1 truncate ps-1.5 text-kg-xs text-kg-fg-faint">{hint}</span>
          {maxLength !== undefined && value.length > maxLength * 0.8 && (
            <span className="kg-prompt-input__count text-kg-xs tabular-nums text-kg-fg-faint" aria-live="polite">
              {value.length}/{maxLength}
            </span>
          )}
          {streaming ? (
            <button
              type="button"
              className={cx(button, "border-kg-ink bg-kg-surface text-kg-fg interactive:hover:bg-kg-paper-sage")}
              data-action="stop"
              aria-label={stopLabel}
              onClick={onStop}
            >
              <span className="kg-prompt-input__stop size-[0.625rem] rounded-[3px] bg-current" aria-hidden="true" />
            </button>
          ) : (
            <button
              type="submit"
              className={cx(
                button,
                "border-kg-ink bg-kg-accent text-kg-accent-fg interactive:hover:bg-kg-accent-hover",
                "disabled:cursor-not-allowed disabled:border-kg-border disabled:bg-kg-muted disabled:text-kg-fg-faint",
              )}
              data-action="send"
              aria-label={sendLabel}
              disabled={empty || disabled}
            >
              <SendIcon />
            </button>
          )}
        </div>
      </form>
    )
  },
)

PromptInput.displayName = "PromptInput"

components/prose/prose.css:
/* Element selectors for HTML the caller does not control: no class to put a utility on. */
@layer kg.components {
  .kg-prose {
    --_flow: 1.15em;

    & :where(*) {
      margin-block: 0;
    }
    & :where(* + *) {
      margin-block-start: var(--_flow);
    }

    & :where(h1, h2, h3, h4) {
      color: var(--kg-fg);
      font-weight: 600;
      line-height: 1.25;
      letter-spacing: -0.015em;
      text-wrap: balance;
    }
    & :where(h1) {
      font-size: 2.1em;
      letter-spacing: -0.025em;
    }
    & :where(h2) {
      font-size: 1.5em;
    }
    & :where(h3) {
      font-size: 1.22em;
    }
    & :where(h4) {
      font-size: 1em;
    }
    /* More room above a heading than below, so it binds to the text it introduces. */
    & :where(* + :is(h1, h2, h3, h4)) {
      margin-block-start: 1.9em;
    }
    & :where(:is(h1, h2, h3, h4) + *) {
      margin-block-start: 0.6em;
    }

    & :where(p, li) {
      text-wrap: pretty;
    }
    & :where(strong) {
      color: var(--kg-fg);
      font-weight: 600;
    }

    & :where(a) {
      color: var(--kg-accent-strong);
      font-weight: 500;
      text-decoration-color: color-mix(in oklab, var(--kg-accent-strong) 40%, transparent);
      text-underline-offset: 0.22em;
    }
    & :where(a:hover) {
      text-decoration-color: currentColor;
    }
    & :where(a:focus-visible) {
      outline: 2px solid var(--kg-ring);
      outline-offset: 2px;
      border-radius: var(--kg-radius-xs);
    }

    & :where(ul, ol) {
      padding-inline-start: 1.4em;
    }
    & :where(li + li) {
      margin-block-start: 0.4em;
    }
    & :where(li > ul, li > ol) {
      margin-block-start: 0.4em;
    }
    & :where(ul > li)::marker {
      color: var(--kg-ink);
    }
    & :where(ol > li)::marker {
      color: var(--kg-fg-muted);
      font-variant-numeric: tabular-nums;
    }

    & :where(blockquote) {
      padding: 0.75em 1em;
      color: var(--kg-fg);
      font-style: italic;
      background: var(--kg-paper-sage);
      border-inline-start: 4px solid var(--kg-ink);
      border-radius: var(--kg-radius-sm);
    }

    & :where(code):not(:where(pre code)) {
      padding: 0.1em 0.35em;
      font-family: var(--kg-font-mono);
      font-size: 0.86em;
      color: var(--kg-fg);
      background: var(--kg-muted);
      border: 1px solid var(--kg-border);
      border-radius: var(--kg-radius-sm);
    }
    & :where(pre) {
      padding: 1em 1.15em;
      overflow-x: auto;
      font-family: var(--kg-font-mono);
      font-size: 0.84em;
      line-height: 1.6;
      color: var(--kg-fg);
      background: var(--kg-surface);
      border: 2px solid var(--kg-ink);
      border-radius: var(--kg-radius-lg);
      box-shadow: var(--kg-shadow-sm);
    }

    & :where(hr) {
      margin-block: 2.2em;
      border: 0;
      border-block-start: 2px solid var(--kg-border);
    }

    & :where(img, video, figure) {
      max-inline-size: 100%;
      height: auto;
      border-radius: var(--kg-radius-lg);
    }
    & :where(figcaption) {
      margin-block-start: 0.6em;
      font-size: 0.86em;
      color: var(--kg-fg-muted);
    }

    & :where(table) {
      inline-size: 100%;
      font-size: 0.92em;
      border-collapse: collapse;
      font-variant-numeric: tabular-nums;
    }
    & :where(th) {
      color: var(--kg-fg);
      font-weight: 600;
      text-align: start;
      border-block-end: 2px solid var(--kg-ink);
    }
    & :where(th, td) {
      padding: 0.55em 0.75em;
    }
    & :where(td) {
      border-block-end: 1px solid var(--kg-border);
    }

    & :where(kbd) {
      padding: 0.05em 0.35em;
      font-family: var(--kg-font-mono);
      font-size: 0.82em;
      color: var(--kg-fg);
      background: var(--kg-surface);
      border: 1px solid var(--kg-ink);
      border-radius: var(--kg-radius-sm);
      box-shadow: 0 2px 0 var(--kg-ink);
    }

    & :where(mark) {
      color: inherit;
      background: var(--kg-paper-butter);
      border-radius: var(--kg-radius-xs);
    }

    & > :where(:first-child) {
      margin-block-start: 0;
    }
  }
}

components/prose/prose.tsx:
import { type ElementType, forwardRef, type HTMLAttributes } from "react"
import { type VariantProps, variants } from "../../utils/variants.js"

const proseVariants = variants({
  base: "kg-prose text-[color-mix(in_oklab,var(--kg-fg)_88%,var(--kg-bg))] [overflow-wrap:break-word]",
  variants: {
    size: {
      sm: "text-kg-base leading-[1.65]",
      md: "text-kg-md leading-[1.7]",
      lg: "text-kg-lg leading-[1.75]",
    },
    measure: {
      true: "max-w-[68ch]",
      false: "",
    },
  },
  defaults: { size: "md", measure: true },
})

export type ProseSize = NonNullable<VariantProps<typeof proseVariants>["size"]>

export interface ProseProps extends HTMLAttributes<HTMLElement> {
  as?: ElementType
  size?: ProseSize
  /** Caps lines near 68 characters for comfortable reading. On by default. */
  measure?: boolean
}

/**
 * Typesets rendered HTML you do not control, such as Markdown or CMS output: headings, lists,
 * quotes, code, tables and media, with vertical rhythm.
 */
export const Prose = forwardRef<HTMLElement, ProseProps>(
  ({ as: Tag = "div", size = "md", measure = true, className, ...props }, ref) => (
    <Tag
      ref={ref}
      className={proseVariants({ size, measure, className })}
      data-size={size}
      data-measure={measure || undefined}
      {...props}
    />
  ),
)

Prose.displayName = "Prose"

components/qr-code/encode.ts:
export type QrCodeErrorLevel = "L" | "M" | "Q" | "H"

/** Error-correction codewords per block, indexed by version (index 0 unused). ISO/IEC 18004 Table 9. */
const ECC_PER_BLOCK: Record<QrCodeErrorLevel, number[]> = {
  L: [-1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28, 28, 28, 30, 30, 26, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
  M: [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28],
  Q: [-1, 13, 22, 18, 26, 18, 24, 18, 22, 20, 24, 28, 26, 24, 20, 30, 24, 28, 28, 26, 30, 28, 30, 30, 30, 30, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
  H: [-1, 17, 28, 22, 16, 22, 28, 26, 26, 24, 28, 24, 28, 22, 24, 24, 30, 28, 28, 26, 28, 30, 24, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
}

/** Number of error-correction blocks, indexed by version. */
const NUM_BLOCKS: Record<QrCodeErrorLevel, number[]> = {
  L: [-1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8, 8, 9, 9, 10, 12, 12, 12, 13, 14, 15, 16, 17, 18, 19, 19, 20, 21, 22, 24, 25],
  M: [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49],
  Q: [-1, 1, 1, 2, 2, 4, 4, 6, 6, 8, 8, 8, 10, 12, 16, 12, 17, 16, 18, 21, 20, 23, 23, 25, 27, 29, 34, 34, 35, 38, 40, 43, 45, 48, 51, 53, 56, 59, 62, 65, 68],
  H: [-1, 1, 1, 2, 4, 4, 4, 5, 6, 8, 8, 11, 11, 16, 16, 18, 16, 19, 21, 25, 25, 25, 34, 30, 32, 35, 37, 40, 42, 45, 48, 51, 54, 57, 60, 63, 66, 70, 74, 77, 81],
}

const FORMAT_BITS: Record<QrCodeErrorLevel, number> = { L: 1, M: 0, Q: 3, H: 2 }

const rawModules = (version: number) => {
  let result = (16 * version + 128) * version + 64
  if (version >= 2) {
    const align = Math.floor(version / 7) + 2
    result -= (25 * align - 10) * align - 55
    if (version >= 7) result -= 36
  }
  return result
}

const dataCodewords = (version: number, level: QrCodeErrorLevel) =>
  Math.floor(rawModules(version) / 8) -
  (ECC_PER_BLOCK[level][version] as number) * (NUM_BLOCKS[level][version] as number)

const gfMultiply = (x: number, y: number) => {
  let z = 0
  for (let i = 7; i >= 0; i--) {
    z = (z << 1) ^ ((z >>> 7) * 0x11d)
    z ^= ((y >>> i) & 1) * x
  }
  return z & 0xff
}

const rsDivisor = (degree: number) => {
  const result = new Array<number>(degree).fill(0)
  result[degree - 1] = 1
  let root = 1
  for (let i = 0; i < degree; i++) {
    for (let j = 0; j < degree; j++) {
      result[j] = gfMultiply(result[j] as number, root)
      if (j + 1 < degree) result[j] = (result[j] as number) ^ (result[j + 1] as number)
    }
    root = gfMultiply(root, 0x02)
  }
  return result
}

const rsRemainder = (data: number[], divisor: number[]) => {
  const result = new Array<number>(divisor.length).fill(0)
  for (const byte of data) {
    const factor = byte ^ (result.shift() as number)
    result.push(0)
    divisor.forEach((coef, i) => {
      result[i] = (result[i] as number) ^ gfMultiply(coef, factor)
    })
  }
  return result
}

const alignmentPositions = (version: number) => {
  if (version === 1) return []
  const count = Math.floor(version / 7) + 2
  const size = version * 4 + 17
  const step = version === 32 ? 26 : Math.ceil((version * 4 + 4) / (count * 2 - 2)) * 2
  const result = [6]
  for (let pos = size - 7; result.length < count; pos -= step) result.splice(1, 0, pos)
  return result
}

const MASKS: ((x: number, y: number) => boolean)[] = [
  (x, y) => (x + y) % 2 === 0,
  (_x, y) => y % 2 === 0,
  (x) => x % 3 === 0,
  (x, y) => (x + y) % 3 === 0,
  (x, y) => (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0,
  (x, y) => ((x * y) % 2) + ((x * y) % 3) === 0,
  (x, y) => (((x * y) % 2) + ((x * y) % 3)) % 2 === 0,
  (x, y) => (((x + y) % 2) + ((x * y) % 3)) % 2 === 0,
]

export interface QrCodeMatrix {
  size: number
  version: number
  mask: number
  /** Row-major: `modules[y][x]` is true for a dark module. */
  modules: boolean[][]
}

/**
 * Encodes text as a QR Code symbol in byte mode (UTF-8), picking the smallest version (1-40)
 * that fits and the mask with the lowest penalty score.
 */
export const encodeQr = (
  text: string,
  level: QrCodeErrorLevel = "M",
  /** Forces a mask pattern (0-7) instead of choosing by penalty. */
  forceMask?: number,
): QrCodeMatrix => {
  const bytes = Array.from(new TextEncoder().encode(text))
  let version = 1
  for (; version <= 40; version++) {
    const countBits = version <= 9 ? 8 : 16
    if (4 + countBits + bytes.length * 8 <= dataCodewords(version, level) * 8) break
  }
  if (version > 40) throw new RangeError("QrCode: data too long")

  // Bit stream: mode, length, payload, terminator, byte padding, pad codewords.
  const bits: number[] = []
  const put = (value: number, length: number) => {
    for (let i = length - 1; i >= 0; i--) bits.push((value >>> i) & 1)
  }
  put(0b0100, 4)
  put(bytes.length, version <= 9 ? 8 : 16)
  for (const byte of bytes) put(byte, 8)
  const capacity = dataCodewords(version, level) * 8
  put(0, Math.min(4, capacity - bits.length))
  put(0, (8 - (bits.length % 8)) % 8)
  for (let pad = 0xec; bits.length < capacity; pad ^= 0xec ^ 0x11) put(pad, 8)
  const data: number[] = []
  for (let i = 0; i < bits.length; i += 8) {
    let byte = 0
    for (let j = 0; j < 8; j++) byte = (byte << 1) | (bits[i + j] as number)
    data.push(byte)
  }

  // Split into blocks, append Reed-Solomon codewords, interleave.
  const blockCount = NUM_BLOCKS[level][version] as number
  const eccLength = ECC_PER_BLOCK[level][version] as number
  const raw = Math.floor(rawModules(version) / 8)
  const shortBlocks = blockCount - (raw % blockCount)
  const shortLength = Math.floor(raw / blockCount)
  const divisor = rsDivisor(eccLength)
  const blocks: number[][] = []
  for (let i = 0, k = 0; i < blockCount; i++) {
    const chunk = data.slice(k, k + shortLength - eccLength + (i < shortBlocks ? 0 : 1))
    k += chunk.length
    const ecc = rsRemainder(chunk, divisor)
    if (i < shortBlocks) chunk.push(0)
    blocks.push(chunk.concat(ecc))
  }
  const codewords: number[] = []
  for (let i = 0; i < (blocks[0] as number[]).length; i++) {
    blocks.forEach((block, j) => {
      if (i !== shortLength - eccLength || j >= shortBlocks) codewords.push(block[i] as number)
    })
  }

  const size = version * 4 + 17
  const modules = Array.from({ length: size }, () => new Array<boolean>(size).fill(false))
  const reserved = Array.from({ length: size }, () => new Array<boolean>(size).fill(false))
  const fn = (x: number, y: number, dark: boolean) => {
    ;(modules[y] as boolean[])[x] = dark
    ;(reserved[y] as boolean[])[x] = true
  }

  for (let i = 0; i < size; i++) {
    fn(6, i, i % 2 === 0)
    fn(i, 6, i % 2 === 0)
  }
  for (const [cx, cy] of [
    [3, 3],
    [size - 4, 3],
    [3, size - 4],
  ] as const) {
    for (let dy = -4; dy <= 4; dy++)
      for (let dx = -4; dx <= 4; dx++) {
        const x = cx + dx
        const y = cy + dy
        if (x < 0 || y < 0 || x >= size || y >= size) continue
        const d = Math.max(Math.abs(dx), Math.abs(dy))
        fn(x, y, d !== 2 && d !== 4)
      }
  }
  const align = alignmentPositions(version)
  align.forEach((ay, i) =>
    align.forEach((ax, j) => {
      const corner =
        (i === 0 && j === 0) ||
        (i === 0 && j === align.length - 1) ||
        (i === align.length - 1 && j === 0)
      if (corner) return
      for (let dy = -2; dy <= 2; dy++)
        for (let dx = -2; dx <= 2; dx++)
          fn(ax + dx, ay + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1)
    }),
  )

  const drawFormat = (mask: number) => {
    const value = (FORMAT_BITS[level] << 3) | mask
    let rem = value
    for (let i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537)
    const format = ((value << 10) | rem) ^ 0x5412
    const bit = (i: number) => ((format >>> i) & 1) === 1
    for (let i = 0; i <= 5; i++) fn(8, i, bit(i))
    fn(8, 7, bit(6))
    fn(8, 8, bit(7))
    fn(7, 8, bit(8))
    for (let i = 9; i < 15; i++) fn(14 - i, 8, bit(i))
    for (let i = 0; i < 8; i++) fn(size - 1 - i, 8, bit(i))
    for (let i = 8; i < 15; i++) fn(8, size - 15 + i, bit(i))
    fn(8, size - 8, true)
  }
  drawFormat(0)

  if (version >= 7) {
    let rem = version
    for (let i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >>> 11) * 0x1f25)
    const info = (version << 12) | rem
    for (let i = 0; i < 18; i++) {
      const dark = ((info >>> i) & 1) === 1
      const a = size - 11 + (i % 3)
      const b = Math.floor(i / 3)
      fn(a, b, dark)
      fn(b, a, dark)
    }
  }

  // Zigzag placement of codeword bits, two columns at a time, skipping the vertical timing line.
  let index = 0
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5
    for (let vert = 0; vert < size; vert++) {
      for (let j = 0; j < 2; j++) {
        const x = right - j
        const upward = ((right + 1) & 2) === 0
        const y = upward ? size - 1 - vert : vert
        if (!(reserved[y] as boolean[])[x] && index < codewords.length * 8) {
          ;(modules[y] as boolean[])[x] =
            (((codewords[index >>> 3] as number) >>> (7 - (index & 7))) & 1) === 1
          index++
        }
      }
    }
  }

  const applyMask = (mask: number) => {
    const test = MASKS[mask] as (x: number, y: number) => boolean
    for (let y = 0; y < size; y++)
      for (let x = 0; x < size; x++)
        if (!(reserved[y] as boolean[])[x] && test(x, y))
          (modules[y] as boolean[])[x] = !(modules[y] as boolean[])[x]
  }

  const penalty = () => {
    let score = 0
    const at = (x: number, y: number) => (modules[y] as boolean[])[x] as boolean
    const lines = (horizontal: boolean) => {
      for (let a = 0; a < size; a++) {
        let run = 1
        const seq: boolean[] = []
        for (let b = 0; b < size; b++) {
          const value = horizontal ? at(b, a) : at(a, b)
          seq.push(value)
          if (b > 0) {
            const prev = horizontal ? at(b - 1, a) : at(a, b - 1)
            if (value === prev) run++
            else {
              if (run >= 5) score += 3 + run - 5
              run = 1
            }
          }
        }
        if (run >= 5) score += 3 + run - 5
        // Finder-like 1:1:3:1:1 with four light modules on either side (light padding off-symbol).
        const padded = [false, false, false, false, ...seq, false, false, false, false]
        for (let i = 0; i + 11 <= padded.length; i++) {
          const w = padded.slice(i, i + 11).map((v) => (v ? 1 : 0)).join("")
          if (w === "10111010000" || w === "00001011101") score += 40
        }
      }
    }
    lines(true)
    lines(false)
    for (let y = 0; y < size - 1; y++)
      for (let x = 0; x < size - 1; x++) {
        const c = at(x, y)
        if (c === at(x + 1, y) && c === at(x, y + 1) && c === at(x + 1, y + 1)) score += 3
      }
    let dark = 0
    for (const row of modules) for (const cell of row) if (cell) dark++
    const total = size * size
    score += (Math.ceil(Math.abs(dark * 20 - total * 10) / total) - 1) * 10
    return score
  }

  let best = 0
  let bestScore = Number.POSITIVE_INFINITY
  for (let mask = 0; mask < 8; mask++) {
    applyMask(mask)
    drawFormat(mask)
    const score = penalty()
    if (score < bestScore) {
      bestScore = score
      best = mask
    }
    applyMask(mask)
  }
  if (forceMask !== undefined) best = forceMask
  applyMask(best)
  drawFormat(best)

  return { size, version, mask: best, modules }
}

