/* The travelling light and sheen are pseudo-element gradient stacks spun by a registered angle. */
@property --kg-shimmer-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@layer kg.components {
  .kg-shimmer-button {
    --_duration: var(--kg-shimmer-duration, 3s);

    /* The travelling light: a conic gradient spun by a registered angle, masked to the edge. */
    &::before {
      content: "";
      position: absolute;
      inset: 0;
      z-index: -1;
      padding: 2px;
      border-radius: inherit;
      background:
        conic-gradient(
          from var(--kg-shimmer-angle),
          transparent 0turn,
          transparent 0.5turn,
          color-mix(in oklab, var(--_shimmer) 35%, transparent) 0.78turn,
          var(--_shimmer) 0.97turn,
          transparent 1turn
        ),
        linear-gradient(
          color-mix(in oklab, var(--_shimmer) 22%, transparent),
          color-mix(in oklab, var(--_shimmer) 22%, transparent)
        );
      -webkit-mask:
        linear-gradient(#000 0 0) content-box,
        linear-gradient(#000 0 0);
      -webkit-mask-composite: xor;
      mask:
        linear-gradient(#000 0 0) content-box exclude,
        linear-gradient(#000 0 0);
      animation: kg-shimmer-spin var(--_duration) linear infinite;
    }

    /* The sheen: a diagonal band that crosses the surface once per lap, then rests. */
    &::after {
      content: "";
      position: absolute;
      inset: 0;
      z-index: -1;
      border-radius: inherit;
      background: linear-gradient(
          105deg,
          transparent 38%,
          color-mix(in oklab, var(--_shimmer) 30%, transparent) 50%,
          transparent 62%
        )
        no-repeat;
      background-size: 250% 100%;
      background-position: 130% 0;
      animation: kg-shimmer-sheen var(--_duration) var(--kg-ease-in-out) infinite;
    }

    &[data-paused]::before,
    &[data-paused]::after {
      animation-play-state: paused;
    }
  }

  @keyframes kg-shimmer-spin {
    to {
      --kg-shimmer-angle: 360deg;
    }
  }

  @keyframes kg-shimmer-sheen {
    0% {
      background-position: 130% 0;
    }
    45%,
    100% {
      background-position: -30% 0;
    }
  }

  /* Reduced motion: no travelling light, just a fixed highlight on the edge. */
  @media (prefers-reduced-motion: reduce) {
    .kg-shimmer-button::before {
      animation: none;
      background: linear-gradient(
        135deg,
        var(--_shimmer),
        color-mix(in oklab, var(--_shimmer) 20%, transparent) 45%,
        color-mix(in oklab, var(--_shimmer) 50%, transparent)
      );
    }

    .kg-shimmer-button::after {
      animation: none;
      opacity: 0;
    }
  }

  [data-kg-motion="reduce"] .kg-shimmer-button {
    &::before {
      animation: none;
      background: linear-gradient(
        135deg,
        var(--_shimmer),
        color-mix(in oklab, var(--_shimmer) 20%, transparent) 45%,
        color-mix(in oklab, var(--_shimmer) 50%, transparent)
      );
    }

    &::after {
      animation: none;
      opacity: 0;
    }
  }
}

"use client"

import {
  type ButtonHTMLAttributes,
  type CSSProperties,
  forwardRef,
  useRef,
} from "react"
import { Slot } from "../../primitives/slot.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { variants } from "../../utils/variants.js"
import { usePlayback } from "../marquee/use-playback.js"

/* A raised ink sheet like Button's solid variant; the light runs just inside its border. */
const shimmerButtonVariants = variants({
  base: [
    "kg-shimmer-button relative isolate inline-flex items-center justify-center gap-2 overflow-hidden",
    "rounded-[var(--kg-shimmer-radius,var(--kg-radius-full))] border-2 border-kg-ink",
    "bg-[var(--kg-shimmer-bg,var(--kg-ink))] text-[var(--kg-shimmer-fg,var(--kg-surface))]",
    "[--_shimmer:var(--kg-shimmer-color,var(--kg-paper-butter))] [--_lift:var(--kg-paper-sage)]",
    "font-semibold leading-none tracking-[-0.005em] whitespace-nowrap no-underline select-none cursor-pointer [-webkit-tap-highlight-color:transparent]",
    "shadow-[3px_3px_0_var(--_lift)] transition-[translate,box-shadow] duration-(--kg-duration-fast) ease-kg-out",
    "interactive:hover:-translate-px interactive:hover:shadow-[5px_5px_0_var(--_lift)]",
    "interactive:active:translate-x-[3px] interactive:active:translate-y-[3px] interactive:active:shadow-none",
    "focus-visible:outline-2 focus-visible:outline-offset-3 focus-visible:outline-kg-ring",
    "disabled:cursor-not-allowed disabled:opacity-50 disabled:shadow-none",
    "aria-disabled:cursor-not-allowed aria-disabled:opacity-50 aria-disabled:shadow-none",
    "[&_svg]:size-[1.15em] [&_svg]:shrink-0",
  ],
  variants: {
    size: {
      sm: "h-kg-sm px-3.5 text-kg-sm",
      md: "h-kg-md px-5 text-kg-base",
      lg: "h-kg-lg px-7 text-kg-md",
    },
  },
  defaults: { size: "md" },
})

export type ShimmerButtonSize = "sm" | "md" | "lg"

export interface ShimmerButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Colour of the travelling light. Any CSS colour; defaults to the butter paper. */
  shimmerColor?: string
  /** Seconds for one lap of the light around the border. */
  duration?: number
  /** Surface colour. Defaults to the ink, which inverts with the theme. */
  background?: string
  /** Corner radius: px, or any CSS length. Defaults to a pill. */
  radius?: number | string
  size?: ShimmerButtonSize
  /** Render the child element (e.g. a router link) with the effect, not a <button>. */
  asChild?: boolean
}

const toLength = (value: number | string) =>
  typeof value === "number" ? `${value}px` : value

/**
 * A call-to-action whose border carries a travelling light, with a sheen sweeping across the
 * surface. CSS-only animation that pauses offscreen and turns static under
 * reduced motion.
 */
export const ShimmerButton = forwardRef<HTMLButtonElement, ShimmerButtonProps>(
  (
    {
      shimmerColor,
      duration = 3,
      background,
      radius,
      size = "md",
      asChild = false,
      className,
      style,
      type,
      children,
      ...props
    },
    forwardedRef,
  ) => {
    const local = useRef<HTMLButtonElement>(null)
    const ref = useComposedRefs(local, forwardedRef)
    const playing = usePlayback(local)

    const shared = {
      className: shimmerButtonVariants({ size, className }),
      "data-size": size,
      "data-paused": !playing || undefined,
      style: {
        "--kg-shimmer-duration": `${duration}s`,
        ...(shimmerColor ? { "--kg-shimmer-color": shimmerColor } : null),
        ...(background ? { "--kg-shimmer-bg": background } : null),
        ...(radius !== undefined
          ? { "--kg-shimmer-radius": toLength(radius) }
          : null),
        ...style,
      } as CSSProperties,
    }

    if (asChild) {
      return (
        <Slot ref={ref} {...shared} {...props}>
          {children}
        </Slot>
      )
    }

    return (
      <button ref={ref} type={type ?? "button"} {...shared} {...props}>
        {children}
      </button>
    )
  },
)

ShimmerButton.displayName = "ShimmerButton"

components/shiny-text/shiny-text.css:
/*
 * The band's gradient stack and its off states stay here: the image is (2 + band) times the text's
 * width with the band at its centre, so stepping background-position from 100% to 0% carries it
 * from just past the start edge to just past the end edge, whatever its width.
 */
@layer kg.components {
  .kg-shiny-text {
    --_half: calc(var(--_band, 0.32) / (2 * (2 + var(--_band, 0.32))) * 100%);

    background-image: linear-gradient(
      100deg,
      var(--_base) calc(50% - var(--_half)),
      var(--_shine) 50%,
      var(--_base) calc(50% + var(--_half))
    );
    background-repeat: no-repeat;
    background-size: calc((2 + var(--_band, 0.32)) * 100%) 100%;
    background-position: 100% 0;
  }

  @keyframes kg-shiny-text {
    from {
      background-position: 100% 0;
    }
    62%,
    to {
      background-position: 0% 0;
    }
  }

  .kg-shiny-text[data-disabled] {
    animation: none;
    background: none;
    -webkit-text-fill-color: currentColor;
  }

  @media (prefers-reduced-motion: reduce) {
    .kg-shiny-text {
      animation: none;
      background: none;
      -webkit-text-fill-color: currentColor;
    }
  }

  [data-kg-motion="reduce"] .kg-shiny-text {
    animation: none;
    background: none;
    -webkit-text-fill-color: currentColor;
  }

  @media (forced-colors: active) {
    .kg-shiny-text {
      background: none;
      -webkit-text-fill-color: currentColor;
    }
  }
}

