"use client"

import { type ButtonHTMLAttributes, forwardRef } from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { type VariantProps, variants } from "../../utils/variants.js"

/*
 * Paper Layers: pressed is an ink fill with mint text. Ghost sits flat on the page; outline is
 * a raised sheet like an outline Button, and pressed it lifts on sage like a solid one.
 */
export const toggleVariants = variants({
  base: [
    "kg-toggle relative inline-flex items-center justify-center gap-1.5",
    "h-(--_size) min-w-(--_size) px-2.5 rounded-kg-md border-2",
    "font-medium leading-none select-none cursor-pointer [-webkit-tap-highlight-color:transparent]",
    "transition-[translate,scale,box-shadow,background-color,border-color,color] duration-(--kg-duration-fast) ease-kg-out",
    "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "aria-pressed:border-kg-accent aria-pressed:bg-kg-accent aria-pressed:text-kg-accent-fg",
    "[&_svg]:size-[1.1em] [&_svg]:shrink-0",
  ],
  variants: {
    variant: {
      ghost: [
        "border-transparent bg-transparent text-kg-fg-muted",
        "interactive:hover:not-aria-pressed:bg-kg-muted interactive:hover:not-aria-pressed:text-kg-fg",
        "interactive:active:scale-95",
      ],
      outline: [
        "border-kg-ink bg-kg-surface text-kg-fg shadow-[3px_3px_0_var(--_lift,var(--kg-ink))]",
        "aria-pressed:[--_lift:var(--kg-paper-sage)]",
        "interactive:hover:-translate-px interactive:hover:shadow-[5px_5px_0_var(--_lift,var(--kg-ink))]",
        "interactive:active:translate-x-[3px] interactive:active:translate-y-[3px] interactive:active:shadow-none",
        "disabled:shadow-none",
      ],
    },
    size: {
      sm: "[--_size:var(--kg-control-sm)] text-kg-xs",
      md: "[--_size:var(--kg-control-md)] text-kg-sm",
      lg: "[--_size:var(--kg-control-lg)] text-kg-base",
    },
  },
  defaults: { variant: "ghost", size: "md" },
})

type ToggleVariantProps = VariantProps<typeof toggleVariants>
export type ToggleSize = NonNullable<ToggleVariantProps["size"]>
export type ToggleVariant = NonNullable<ToggleVariantProps["variant"]>

export interface ToggleProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value"> {
  pressed?: boolean
  defaultPressed?: boolean
  onPressedChange?: (pressed: boolean) => void
  size?: ToggleSize
  variant?: ToggleVariant
}

/**
 * A two-state button (`aria-pressed`). For formatting bars, filters and view switches. Give
 * icon-only toggles an `aria-label`; it stays the same in both states.
 */
export const Toggle = forwardRef<HTMLButtonElement, ToggleProps>(
  (
    {
      pressed: pressedProp,
      defaultPressed = false,
      onPressedChange,
      size = "md",
      variant = "ghost",
      className,
      onClick,
      type = "button",
      ...props
    },
    ref,
  ) => {
    const [pressed, setPressed] = useControllableState({
      value: pressedProp,
      defaultValue: defaultPressed,
      onChange: onPressedChange,
    })
    return (
      <button
        ref={ref}
        type={type}
        aria-pressed={pressed}
        className={toggleVariants({ variant, size, className })}
        data-size={size}
        data-variant={variant}
        data-state={pressed ? "on" : "off"}
        onClick={(event) => {
          onClick?.(event)
          if (!event.defaultPrevented) setPressed(!pressed)
        }}
        {...props}
      />
    )
  },
)

Toggle.displayName = "Toggle"

components/toggle-group/toggle-group.tsx:
"use client"

import {
  type ButtonHTMLAttributes,
  createContext,
  forwardRef,
  type HTMLAttributes,
  useContext,
  useRef,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { useIsomorphicLayoutEffect } from "../../hooks/use-isomorphic-layout-effect.js"
import { ROVING_ITEM_SELECTOR, useRovingFocus } from "../../hooks/use-roving-focus.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"
import { type ToggleSize, type ToggleVariant, toggleVariants } from "../toggle/toggle.js"

interface ToggleGroupBaseProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "defaultValue" | "onChange"> {
  size?: ToggleSize
  variant?: ToggleVariant
  orientation?: "horizontal" | "vertical"
  disabled?: boolean
  /** Joins the items into one segmented bar. */
  attached?: boolean
}

export interface ToggleGroupSingleProps extends ToggleGroupBaseProps {
  type?: "single"
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (value: string | null) => void
  /** Keeps one item pressed: pressing the current item does nothing. */
  required?: boolean
}

export interface ToggleGroupMultipleProps extends ToggleGroupBaseProps {
  type: "multiple"
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
  required?: never
}

export type ToggleGroupProps = ToggleGroupSingleProps | ToggleGroupMultipleProps

export interface ToggleGroupItemProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "value"> {
  value: string
}

interface GroupContext {
  pressed: (value: string) => boolean
  toggle: (value: string) => void
  size: ToggleSize
  variant: ToggleVariant
  disabled: boolean
  attached: boolean
}

const Context = createContext<GroupContext | null>(null)

const toArray = (value: string | string[] | null | undefined) =>
  value == null ? [] : Array.isArray(value) ? value : [value]

/**
 * A set of toggle buttons with one tab stop and arrow-key navigation. `single` behaves like a
 * radio set that can be cleared; `multiple` like a row of checkboxes.
 */
export const ToggleGroup = forwardRef<HTMLDivElement, ToggleGroupProps>((props, ref) => {
  const {
    type = "single",
    value: valueProp,
    defaultValue,
    onValueChange,
    required = false,
    size = "md",
    variant = "ghost",
    orientation = "horizontal",
    disabled = false,
    attached = false,
    className,
    onKeyDown,
    onFocus,
    children,
    ...rest
  } = props
  const [value, setValue] = useControllableState<string[]>({
    value: valueProp === undefined ? undefined : toArray(valueProp),
    defaultValue: toArray(defaultValue),
    onChange: (next) => {
      if (type === "multiple") (onValueChange as ((v: string[]) => void) | undefined)?.(next)
      else (onValueChange as ((v: string | null) => void) | undefined)?.(next[0] ?? null)
    },
  })
  const roving = useRovingFocus({ orientation })

  const context: GroupContext = {
    pressed: (item) => value.includes(item),
    toggle: (item) => {
      if (type === "multiple") {
        setValue(value.includes(item) ? value.filter((v) => v !== item) : [...value, item])
      } else if (value[0] === item) {
        if (!required) setValue([])
      } else setValue([item])
    },
    size,
    variant,
    disabled,
    attached,
  }

  const groupRef = useRef<HTMLDivElement>(null)
  const rootRef = useComposedRefs(groupRef, ref)
  // Roving tabindex lives on the DOM so items need no index: one tab stop, on the first
  // pressed item, else the first enabled one, and it follows focus.
  const setStop = (target?: HTMLElement) => {
    const items = Array.from(
      groupRef.current?.querySelectorAll<HTMLElement>(ROVING_ITEM_SELECTOR) ?? [],
    )
    const stop =
      target ?? items.find((item) => item.getAttribute("aria-pressed") === "true") ?? items[0]
    for (const item of items) item.tabIndex = item === stop ? 0 : -1
  }
  useIsomorphicLayoutEffect(() => {
    if (!groupRef.current?.contains(document.activeElement)) setStop()
  })

  return (
    <div
      ref={rootRef}
      role="group"
      className={cx(
        "kg-toggle-group inline-flex items-center gap-1",
        "data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch",
        // Attached: one sheet; its border and padding sit inside the control height.
        "data-attached:gap-0 data-attached:p-[2px] data-attached:rounded-kg-md",
        "data-attached:border-2 data-attached:border-kg-ink data-attached:bg-kg-surface",
        attached && variant === "outline" && "shadow-[3px_3px_0_var(--kg-ink)]",
        className,
      )}
      data-orientation={orientation}
      data-attached={attached || undefined}
      data-variant={variant}
      aria-orientation={orientation}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (!event.defaultPrevented) roving(event)
      }}
      onFocus={(event) => {
        onFocus?.(event)
        if (event.target.matches(ROVING_ITEM_SELECTOR)) setStop(event.target)
      }}
      {...rest}
    >
      <Context.Provider value={context}>{children}</Context.Provider>
    </div>
  )
})

ToggleGroup.displayName = "ToggleGroup"

export const ToggleGroupItem = forwardRef<HTMLButtonElement, ToggleGroupItemProps>(
  ({ value, className, disabled, onClick, ...props }, ref) => {
    const group = useContext(Context)
    if (!group) throw new Error("ToggleGroupItem must be used inside ToggleGroup")
    const pressed = group.pressed(value)
    const isDisabled = disabled || group.disabled
    return (
      <button
        ref={ref}
        type="button"
        aria-pressed={pressed}
        disabled={isDisabled}
        data-kg-item=""
        data-size={group.size}
        data-variant={group.variant}
        data-state={pressed ? "on" : "off"}
        className={toggleVariants({
          // The attached bar is the outline, so its items sit flat inside it.
          variant: group.attached ? "ghost" : group.variant,
          size: group.size,
          className: cx(
            "kg-toggle-group__item",
            "[[data-attached]>&]:h-[calc(var(--_size)-8px)] [[data-attached]>&]:min-w-[calc(var(--_size)-8px)]",
            "[[data-attached]>&]:rounded-kg-sm",
            className,
          ),
        })}
        onClick={(event) => {
          onClick?.(event)
          if (!event.defaultPrevented) group.toggle(value)
        }}
        {...props}
      />
    )
  },
)

ToggleGroupItem.displayName = "ToggleGroupItem"

