"use client"

import {
  type ButtonHTMLAttributes,
  type CSSProperties,
  forwardRef,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { Layer } from "../../primitives/layer.js"
import { useComposedRefs } from "../../utils/compose-refs.js"
import { cx } from "../../utils/cx.js"
import {
  CheckIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  listboxClass,
  optionCheckClass,
  optionIconClass,
  triggerLabelledBy,
  usePopup,
} from "../combobox/internal.js"
import { resolveFieldControl, useField } from "../field/field.js"
import {
  type SearchSelectProps,
  searchSelectChevron,
  searchSelectValue,
  searchSelectVariants,
} from "../search-select/search-select.js"

/* The treeitem takes focus; its row shows the tint, the ring and the selection. */
const rowClass = cx(
  "kg-tree-select__row relative flex items-center gap-1.5 min-h-(--kg-control-sm) py-1 ps-(--_ps) pe-2.5",
  "leading-[1.3] rounded-kg-sm cursor-default select-none transition-colors duration-(--kg-duration-fast) ease-kg-out",
  "[:not([aria-disabled=true])>&]:hover:bg-kg-muted [:focus>&]:bg-kg-muted",
  "[:focus-visible>&]:outline-2 [:focus-visible>&]:-outline-offset-2 [:focus-visible>&]:outline-kg-ring",
  "[[aria-selected=true]>&]:font-semibold",
  "[[aria-disabled=true]>&]:opacity-50 [[aria-disabled=true]>&]:cursor-not-allowed",
)

/* A hairline guide shows each level's parent. */
const groupClass = cx(
  "kg-tree-select__group relative",
  "before:absolute before:top-0 before:bottom-2 before:start-3.5 before:w-px before:bg-kg-border before:content-['']",
  "[[role=group]_&]:before:start-8",
)

const twistClass = cx(
  "kg-tree-select__twist inline-grid place-items-center shrink-0 size-5 rounded-kg-xs text-kg-fg-faint hover:text-kg-fg",
  "[&_svg]:size-[0.85rem] [&_svg]:transition-[rotate] [&_svg]:duration-(--kg-duration-base) [&_svg]:ease-kg-out",
  "[&[data-open]_svg]:rotate-90",
)

export interface TreeSelectNode {
  value: string
  label: string
  icon?: ReactNode
  disabled?: boolean
  children?: readonly TreeSelectNode[]
}

export interface TreeSelectProps extends Omit<
  ButtonHTMLAttributes<HTMLButtonElement>,
  "value" | "defaultValue" | "onChange" | "children" | "type" | "name"
> {
  nodes: readonly TreeSelectNode[]
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (value: string) => void
  /** Lets branches be chosen too, not only leaves. */
  selectBranches?: boolean
  placeholder?: string
  /** Separator for the path shown in the field. */
  separator?: string
  size?: SearchSelectProps["size"]
  invalid?: boolean
  name?: string
}

interface Flat {
  node: TreeSelectNode
  level: number
  parent: string | null
  path: string[]
}

const flatten = (
  nodes: readonly TreeSelectNode[],
  level = 1,
  parent: string | null = null,
  path: string[] = [],
): Flat[] =>
  nodes.flatMap((node) => [
    { node, level, parent, path: [...path, node.label] },
    ...flatten(node.children ?? [], level + 1, node.value, [...path, node.label]),
  ])

/**
 * A select whose options are a tree, following the APG tree view pattern: arrows walk and
 * fold branches, Enter picks, Escape closes.
 */
export const TreeSelect = forwardRef<HTMLButtonElement, TreeSelectProps>(
  (
    {
      nodes,
      value: valueProp,
      defaultValue = null,
      onValueChange,
      selectBranches = false,
      placeholder = "Select",
      separator = " / ",
      size = "md",
      invalid,
      disabled,
      name,
      id,
      className,
      onClick,
      onKeyDown,
      "aria-describedby": describedBy,
      "aria-labelledby": ariaLabelledBy,
      ...props
    },
    forwardedRef,
  ) => {
    const control = resolveFieldControl(useField(), {
      id,
      disabled,
      invalid,
      "aria-describedby": describedBy,
    })
    const [value, setValue] = useControllableState<string | null>({
      value: valueProp,
      defaultValue,
      onChange: onValueChange as ((value: string | null) => void) | undefined,
    })
    const all = useMemo(() => flatten(nodes), [nodes])
    const byValue = useMemo(() => new Map(all.map((item) => [item.node.value, item])), [all])
    const ancestors = (key: string | null) => {
      const out: string[] = []
      let current = key ? byValue.get(key)?.parent : null
      while (current) {
        out.push(current)
        current = byValue.get(current)?.parent ?? null
      }
      return out
    }

    const [open, setOpen] = useState(false)
    const [expanded, setExpanded] = useState<Set<string>>(() => new Set(ancestors(value)))
    const [focused, setFocused] = useState<string | null>(null)
    const triggerRef = useRef<HTMLButtonElement>(null)
    const ref = useComposedRefs(triggerRef, forwardedRef)
    const treeRef = useRef<HTMLDivElement>(null)
    const treeId = useId()
    const triggerId = control.id ?? `${treeId}-trigger`

    const visible = all.filter((item) => ancestors(item.node.value).every((a) => expanded.has(a)))
    const selected = value ? byValue.get(value) : undefined

    const close = (refocus = true) => {
      setOpen(false)
      if (refocus) triggerRef.current?.focus()
    }
    const { ref: layerRef, present, state } = usePopup({
      open,
      anchorRef: triggerRef,
      onDismiss: () => close(),
    })

    useEffect(() => {
      if (!open || !focused) return
      const items = treeRef.current?.querySelectorAll<HTMLElement>("[data-value]") ?? []
      for (const item of items) if (item.dataset.value === focused) item.focus()
    }, [open, focused])

    const openTree = () => {
      setExpanded((prev) => new Set([...prev, ...ancestors(value)]))
      setFocused(value ?? all.find((item) => !item.node.disabled)?.node.value ?? null)
      setOpen(true)
    }

    const toggleBranch = (key: string, force?: boolean) =>
      setExpanded((prev) => {
        const next = new Set(prev)
        if (force ?? !next.has(key)) next.add(key)
        else next.delete(key)
        return next
      })

    const choose = (item: Flat) => {
      if (item.node.disabled) return
      const branch = Boolean(item.node.children?.length)
      if (branch && !selectBranches) return toggleBranch(item.node.value)
      setValue(item.node.value)
      close()
    }

    const handleTreeKey = (event: ReactKeyboardEvent<HTMLDivElement>) => {
      const index = visible.findIndex((item) => item.node.value === focused)
      const item = visible[index]
      if (!item) return
      const branch = Boolean(item.node.children?.length)
      const isOpen = expanded.has(item.node.value)
      const focusAt = (at: number) => {
        const target = visible[Math.max(0, Math.min(visible.length - 1, at))]
        if (target) setFocused(target.node.value)
      }
      switch (event.key) {
        case "ArrowDown":
          event.preventDefault()
          return focusAt(index + 1)
        case "ArrowUp":
          event.preventDefault()
          return focusAt(index - 1)
        case "Home":
          event.preventDefault()
          return focusAt(0)
        case "End":
          event.preventDefault()
          return focusAt(visible.length - 1)
        case "ArrowRight":
          event.preventDefault()
          if (branch && !isOpen) toggleBranch(item.node.value, true)
          else if (branch) focusAt(index + 1)
          return
        case "ArrowLeft":
          event.preventDefault()
          if (branch && isOpen) toggleBranch(item.node.value, false)
          else if (item.parent) setFocused(item.parent)
          return
        case "Enter":
        case " ":
          event.preventDefault()
          return choose(item)
        case "Tab":
          event.preventDefault()
          return close()
      }
    }

    const renderLevel = (items: readonly TreeSelectNode[]): ReactNode =>
      items.map((node) => {
        const item = byValue.get(node.value) as Flat
        const branch = Boolean(node.children?.length)
        const isOpen = expanded.has(node.value)
        // Named by its own label only, not by the nested group it contains.
        const labelId = `${treeId}-label-${all.indexOf(item)}`
        return (
          <div
            key={node.value}
            role="treeitem"
            aria-labelledby={labelId}
            aria-level={item.level}
            aria-expanded={branch ? isOpen : undefined}
            aria-selected={node.value === value}
            aria-disabled={node.disabled || undefined}
            tabIndex={node.value === focused ? 0 : -1}
            data-value={node.value}
            className="kg-tree-select__item outline-none"
            onFocus={(event) => {
              if (event.target === event.currentTarget) setFocused(node.value)
            }}
            onClick={(event) => {
              event.stopPropagation()
              setFocused(node.value)
              choose(item)
            }}
          >
            <span
              className={rowClass}
              style={{ "--_ps": `calc(var(--kg-space) * ${1 + (item.level - 1) * 4.5})` } as CSSProperties}
            >
              <span
                className={twistClass}
                data-open={isOpen || undefined}
                aria-hidden="true"
                onClick={(event) => {
                  if (!branch) return
                  event.stopPropagation()
                  setFocused(node.value)
                  toggleBranch(node.value)
                }}
              >
                {branch && <ChevronRightIcon />}
              </span>
              {node.icon != null && (
                <span className={optionIconClass} aria-hidden="true">
                  {node.icon}
                </span>
              )}
              <span id={labelId} className="kg-tree-select__label flex-1 min-w-0 truncate">
                {node.label}
              </span>
              {branch && (
                <span className="kg-tree-select__count text-kg-xs font-normal tabular-nums text-kg-fg-muted" aria-hidden="true">
                  {node.children?.length}
                </span>
              )}
              <span className={optionCheckClass} aria-hidden="true">
                {node.value === value && <CheckIcon />}
              </span>
            </span>
            {branch && isOpen && (
              <div role="group" className={groupClass}>
                {renderLevel(node.children ?? [])}
              </div>
            )}
          </div>
        )
      })

    return (
      <>
        <button
          ref={ref}
          type="button"
          id={triggerId}
          aria-labelledby={triggerLabelledBy({
            labelledBy: ariaLabelledBy,
            labelId: control.labelId,
            ariaLabel: props["aria-label"],
            selfId: triggerId,
            valueId: `${treeId}-value`,
            hasValue: selected !== undefined,
          })}
          aria-haspopup="tree"
          aria-expanded={open}
          aria-controls={present ? treeId : undefined}
          aria-describedby={control.describedBy}
          aria-invalid={control.invalid || undefined}
          disabled={control.disabled}
          className={searchSelectVariants({ variant: "field", size, className: cx("kg-tree-select", className) })}
          data-size={size}
          data-variant="field"
          data-state={open ? "open" : "closed"}
          data-invalid={control.invalid || undefined}
          data-placeholder={selected ? undefined : ""}
          {...props}
          onClick={(event) => {
            onClick?.(event)
            if (event.defaultPrevented) return
            if (open) close(false)
            else openTree()
          }}
          onKeyDown={(event) => {
            onKeyDown?.(event)
            if (!open && (event.key === "ArrowDown" || event.key === "ArrowUp")) {
              event.preventDefault()
              openTree()
            }
          }}
        >
          <span id={`${treeId}-value`} className={searchSelectValue}>
            {selected ? (
              <>
                {selected.path.length > 1 && (
                  <span className="kg-tree-select__path text-kg-fg-muted">
                    {selected.path.slice(0, -1).join(separator)}
                    {separator}
                  </span>
                )}
                {selected.node.label}
              </>
            ) : (
              placeholder
            )}
          </span>
          <span className={searchSelectChevron} aria-hidden="true">
            <ChevronDownIcon />
          </span>
        </button>
        {name !== undefined && <input type="hidden" name={name} value={value ?? ""} />}
        {present && (
          <Layer
            ref={layerRef}
            className={cx(listboxClass(size), "kg-tree-select__popup min-w-64")}
            data-state={state}
            data-size={size}
          >
            <div
              ref={treeRef}
              id={treeId}
              role="tree"
              aria-labelledby={control.labelId}
              aria-label={control.labelId ? undefined : props["aria-label"]}
              onKeyDown={handleTreeKey}
            >
              {renderLevel(nodes)}
            </div>
          </Layer>
        )}
      </>
    )
  },
)

TreeSelect.displayName = "TreeSelect"

components/tree-view/tree-view.tsx:
"use client"

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../../hooks/use-controllable-state.js"
import { cx } from "../../utils/cx.js"

export interface TreeViewNode {
  id: string
  label: ReactNode
  /** Plain text for type-ahead when `label` is not a string. */
  textValue?: string
  icon?: ReactNode
  /** Icon shown while expanded, e.g. an open folder. */
  expandedIcon?: ReactNode
  children?: TreeViewNode[]
  /** Marks a branch whose children load on first expand via `onLoadChildren`. */
  hasChildren?: boolean
  disabled?: boolean
  /** Trailing content such as a count or badge. */
  meta?: ReactNode
}

export type TreeViewSelectionMode = "none" | "single" | "multiple"

export interface TreeViewLabels {
  loading?: string
}

export interface TreeViewProps
  extends Omit<
    HTMLAttributes<HTMLUListElement>,
    "onSelect" | "defaultValue" | "defaultChecked"
  > {
  nodes: TreeViewNode[]
  /** Accessible name. Required unless `aria-labelledby` is given. */
  label?: string
  expanded?: string[]
  defaultExpanded?: string[]
  onExpandedChange?: (ids: string[]) => void
  selectionMode?: TreeViewSelectionMode
  selected?: string[]
  defaultSelected?: string[]
  onSelectedChange?: (ids: string[]) => void
  /** Tri-state checkboxes that cascade to descendants. Replaces selection. */
  checkable?: boolean
  checked?: string[]
  defaultChecked?: string[]
  onCheckedChange?: (ids: string[]) => void
  /** Called the first time a lazy branch (`hasChildren` without `children`) is expanded. */
  onLoadChildren?: (node: TreeViewNode) => Promise<void> | void
  /** Enter or click on a leaf. */
  onAction?: (node: TreeViewNode) => void
  /** Draws indent guides. */
  guides?: boolean
  labels?: TreeViewLabels
}

interface Flat {
  node: TreeViewNode
  level: number
  parent: string | undefined
  setSize: number
  posInSet: number
}

const isBranch = (node: TreeViewNode) => Boolean(node.children?.length || node.hasChildren)

const textOf = (node: TreeViewNode) =>
  node.textValue ?? (typeof node.label === "string" ? node.label : "")

const descendants = (node: TreeViewNode): string[] =>
  (node.children ?? []).flatMap((child) => [child.id, ...descendants(child)])

type CheckState = "true" | "false" | "mixed"

const checkState = (node: TreeViewNode, checked: Set<string>): CheckState => {
  const kids = node.children ?? []
  if (kids.length === 0) return checked.has(node.id) ? "true" : "false"
  const states = kids.map((child) => checkState(child, checked))
  if (states.every((s) => s === "true")) return "true"
  if (states.every((s) => s === "false")) return "false"
  return "mixed"
}

const Chevron = () => (
  <svg viewBox="0 0 16 16" aria-hidden="true">
    <path
      d="M6 4l4 4-4 4"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
)

/**
 * A hierarchical list following the WAI-ARIA tree pattern: arrows move and open, Home/End
 * jump, `*` expands siblings, typing finds a node, Space selects or checks.
 */
export const TreeView = forwardRef<HTMLUListElement, TreeViewProps>(
  (
    {
      nodes,
      label,
      expanded: expandedProp,
      defaultExpanded = [],
      onExpandedChange,
      selectionMode = "single",
      selected: selectedProp,
      defaultSelected = [],
      onSelectedChange,
      checkable = false,
      checked: checkedProp,
      defaultChecked = [],
      onCheckedChange,
      onLoadChildren,
      onAction,
      guides = true,
      labels,
      className,
      ...props
    },
    ref,
  ) => {
    const [expanded, setExpanded] = useControllableState({
      value: expandedProp,
      defaultValue: defaultExpanded,
      onChange: onExpandedChange,
    })
    const [selected, setSelected] = useControllableState({
      value: selectedProp,
      defaultValue: defaultSelected,
      onChange: onSelectedChange,
    })
    const [checked, setChecked] = useControllableState({
      value: checkedProp,
      defaultValue: defaultChecked,
      onChange: onCheckedChange,
    })
    const expandedSet = useMemo(() => new Set(expanded), [expanded])
    const selectedSet = useMemo(() => new Set(selected), [selected])
    const checkedSet = useMemo(() => new Set(checked), [checked])
    const [loading, setLoading] = useState<Set<string>>(() => new Set())
    const loaded = useRef(new Set<string>())
    const items = useRef(new Map<string, HTMLLIElement>())
    const typeahead = useRef({ text: "", time: 0 })
    const baseId = useId()
    const labelId = (id: string) => `${baseId}-${id.replace(/[^\w-]/g, "_")}`

    const visible = useMemo(() => {
      const out: Flat[] = []
      const walk = (list: TreeViewNode[], level: number, parent: string | undefined) => {
        list.forEach((node, index) => {
          out.push({ node, level, parent, setSize: list.length, posInSet: index + 1 })
          if (expandedSet.has(node.id) && node.children) walk(node.children, level + 1, node.id)
        })
      }
      walk(nodes, 1, undefined)
      return out
    }, [nodes, expandedSet])

    const enabled = visible.filter((item) => !item.node.disabled)
    const initialFocus =
      enabled.find((item) => selectedSet.has(item.node.id))?.node.id ?? enabled[0]?.node.id
    const [focused, setFocused] = useState<string | undefined>(initialFocus)
    const focusId = visible.some((item) => item.node.id === focused) ? focused : initialFocus
    const shouldFocus = useRef(false)

    useEffect(() => {
      if (!shouldFocus.current || !focusId) return
      shouldFocus.current = false
      items.current.get(focusId)?.focus()
    }, [focusId])

    const moveTo = (id: string | undefined) => {
      if (!id) return
      shouldFocus.current = true
      setFocused(id)
      if (id === focusId) items.current.get(id)?.focus()
    }

    const setOpen = (node: TreeViewNode, open: boolean) => {
      if (open === expandedSet.has(node.id)) return
      setExpanded((current) =>
        open ? [...current, node.id] : current.filter((id) => id !== node.id),
      )
      if (open && node.hasChildren && !node.children?.length && onLoadChildren && !loaded.current.has(node.id)) {
        loaded.current.add(node.id)
        const result = onLoadChildren(node)
        if (result && typeof (result as Promise<void>).then === "function") {
          setLoading((current) => new Set(current).add(node.id))
          void (result as Promise<void>).finally(() =>
            setLoading((current) => {
              const next = new Set(current)
              next.delete(node.id)
              return next
            }),
          )
        }
      }
    }

    const toggleCheck = (node: TreeViewNode) => {
      const ids = [node.id, ...descendants(node)]
      const on = checkState(node, checkedSet) !== "true"
      setChecked((current) => {
        const next = new Set(current)
        for (const id of ids) {
          if (on) next.add(id)
          else next.delete(id)
        }
        return [...next]
      })
    }

    const select = (node: TreeViewNode, additive: boolean) => {
      if (node.disabled) return
      if (checkable) return toggleCheck(node)
      if (selectionMode === "none") return
      if (selectionMode === "single") return setSelected([node.id])
      setSelected((current) =>
        current.includes(node.id)
          ? additive
            ? current
            : current.filter((id) => id !== node.id)
          : [...current, node.id],
      )
    }

    const activate = (node: TreeViewNode) => {
      if (node.disabled) return
      if (isBranch(node)) setOpen(node, !expandedSet.has(node.id))
      else {
        if (selectionMode === "single" && !checkable) setSelected([node.id])
        onAction?.(node)
      }
    }

    const onKeyDown = (event: KeyboardEvent<HTMLUListElement>) => {
      const index = enabled.findIndex((item) => item.node.id === focusId)
      const current = enabled[index]
      if (!current) return
      const { node } = current
      const open = expandedSet.has(node.id)
      let handled = true
      switch (event.key) {
        case "ArrowDown":
          moveTo(enabled[index + 1]?.node.id)
          if (event.shiftKey && selectionMode === "multiple" && enabled[index + 1])
            select((enabled[index + 1] as Flat).node, true)
          break
        case "ArrowUp":
          moveTo(enabled[index - 1]?.node.id)
          if (event.shiftKey && selectionMode === "multiple" && enabled[index - 1])
            select((enabled[index - 1] as Flat).node, true)
          break
        case "ArrowRight":
          if (!isBranch(node)) break
          if (!open) setOpen(node, true)
          else if (node.children?.[0]) moveTo(node.children.find((c) => !c.disabled)?.id)
          break
        case "ArrowLeft":
          if (isBranch(node) && open) setOpen(node, false)
          else moveTo(current.parent)
          break
        case "Home":
          moveTo(enabled[0]?.node.id)
          break
        case "End":
          moveTo(enabled[enabled.length - 1]?.node.id)
          break
        case "Enter":
          activate(node)
          break
        case " ":
          if (checkable || selectionMode !== "none") select(node, false)
          else activate(node)
          break
        case "*": {
          const siblings = visible
            .filter((item) => item.parent === current.parent && isBranch(item.node))
            .map((item) => item.node)
          for (const sibling of siblings) setOpen(sibling, true)
          break
        }
        default:
          if (event.key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey) {
            const now = Date.now()
            const state = typeahead.current
            state.text = now - state.time > 600 ? event.key : state.text + event.key
            state.time = now
            const needle = state.text.toLowerCase()
            const ordered = [...enabled.slice(index + 1), ...enabled.slice(0, index + 1)]
            const match =
              ordered.find((item) => textOf(item.node).toLowerCase().startsWith(needle)) ??
              (needle.length > 1
                ? undefined
                : ordered.find((item) => textOf(item.node).toLowerCase().startsWith(event.key)))
            moveTo(match?.node.id)
          } else handled = false
      }
      if (handled) event.preventDefault()
    }

    const words = { loading: "Loading", ...labels }

    const renderNodes = (list: TreeViewNode[], level: number): ReactNode =>
      list.map((node, index) => {
        const branch = isBranch(node)
        const open = branch && expandedSet.has(node.id)
        const state = checkable ? checkState(node, checkedSet) : undefined
        const isSelected = !checkable && selectionMode !== "none" ? selectedSet.has(node.id) : undefined
        const busy = loading.has(node.id)
        return (
          <li
            key={node.id}
            ref={(element) => {
              if (element) items.current.set(node.id, element)
              else items.current.delete(node.id)
            }}
            role="treeitem"
            className="kg-tree-view__item outline-none"
            aria-labelledby={labelId(node.id)}
            aria-level={level}
            aria-setsize={list.length}
            aria-posinset={index + 1}
            aria-expanded={branch ? open : undefined}
            aria-selected={isSelected}
            aria-checked={state}
            aria-disabled={node.disabled || undefined}
            aria-busy={busy || undefined}
            tabIndex={node.id === focusId ? 0 : -1}
            data-state={state === "true" || isSelected ? "selected" : undefined}
            onFocus={(event) => {
              if (event.target === event.currentTarget) setFocused(node.id)
            }}
          >
            {/* biome-ignore lint/a11y/useKeyWithClickEvents: keyboard is handled on the tree. */}
            <div
              className={cx(
                "kg-tree-view__row relative flex min-h-(--_row) items-center gap-1.5 rounded-kg-md ps-(--_pad) pe-2 transition-colors duration-(--kg-duration-fast) ease-kg-out",
                "[:focus-visible>&]:outline-2 [:focus-visible>&]:-outline-offset-2 [:focus-visible>&]:outline-kg-ring",
                node.disabled
                  ? "cursor-not-allowed text-kg-fg-faint"
                  : isSelected
                    ? "cursor-pointer bg-kg-paper-sage text-kg-fg before:absolute before:inset-y-1.5 before:start-0 before:w-[3px] before:rounded-full before:bg-kg-ink"
                    : "cursor-pointer hover:bg-kg-muted",
              )}
              style={{ "--_level": level - 1, "--_pad": `calc(${level - 1} * var(--_indent) + 0.25rem)` } as CSSProperties}
              onClick={(event) => {
                if (node.disabled) return
                moveTo(node.id)
                if (checkable) toggleCheck(node)
                else if (branch) {
                  setOpen(node, !open)
                  if (selectionMode !== "none")
                    select(node, false)
                } else {
                  select(node, false)
                  onAction?.(node)
                }
              }}
            >
              <span
                className={cx(
                  "kg-tree-view__chevron inline-grid size-4 flex-none place-items-center [&_svg]:size-3.5 [&_svg]:transition-transform [&_svg]:duration-(--kg-duration-base) [&_svg]:ease-kg-spring",
                  isSelected ? "text-kg-fg" : "text-kg-fg-muted",
                  open && "[&_svg]:rotate-90",
                )}
                data-visible={branch || undefined}
              >
                {branch && (busy ? <span className="kg-tree-view__spinner size-3 animate-spin rounded-full border-[1.5px] border-kg-border-strong border-t-transparent [animation-duration:0.7s] motion-reduce:[animation-duration:2.4s] [[data-kg-motion=reduce]_&]:[animation-duration:2.4s]" /> : <Chevron />)}
              </span>
              {checkable && (
                <span
                  className={cx(
                    "kg-tree-view__checkbox inline-grid size-4 flex-none place-items-center rounded-kg-xs border-2 border-kg-ink transition-colors duration-(--kg-duration-fast) ease-kg-out",
                    "[&_svg]:size-3 [&_svg]:fill-none [&_svg]:stroke-kg-accent-fg [&_svg]:stroke-[2.2] [&_svg]:[stroke-linecap:round] [&_svg]:[stroke-linejoin:round] [&_svg]:transition-[opacity,scale] [&_svg]:duration-(--kg-duration-spring) [&_svg]:ease-(--kg-ease-bounce)",
                    state === "true" || state === "mixed"
                      ? "bg-kg-accent"
                      : "bg-kg-surface [&_svg]:scale-60 [&_svg]:opacity-0",
                  )}
                  data-state={state}
                  aria-hidden="true"
                >
                  <svg viewBox="0 0 16 16">
                    {state === "mixed" ? (
                      <path d="M4.5 8h7" />
                    ) : (
                      <path d="M4 8.5l2.5 2.5 5.5-6" />
                    )}
                  </svg>
                </span>
              )}
              {(node.icon || node.expandedIcon) && (
                <span
                  className={cx(
                    "kg-tree-view__icon inline-flex flex-none [&_svg]:size-4",
                    isSelected ? "text-kg-accent-strong" : "text-kg-fg-muted",
                  )}
                  aria-hidden="true"
                >
                  {open && node.expandedIcon ? node.expandedIcon : node.icon}
                </span>
              )}
              <span id={labelId(node.id)} className="kg-tree-view__label min-w-0 flex-1 overflow-hidden text-ellipsis whitespace-nowrap">
                {node.label}
              </span>
              {node.meta != null && <span
                  className={cx(
                    "kg-tree-view__meta flex-none text-kg-xs tabular-nums",
                    isSelected ? "text-kg-fg" : "text-kg-fg-muted",
                  )}
                >
                  {node.meta}
                </span>}
            </div>
            {open && (
              // biome-ignore lint/a11y/useSemanticElements: role="group" is required by the tree pattern.
              <ul
                role="group"
                className={cx(
                  "kg-tree-view__group relative m-0 list-none p-0 transition-[opacity,translate] duration-(--kg-duration-base) ease-kg-out starting:-translate-y-[3px] starting:opacity-0",
                  guides &&
                    "before:absolute before:inset-y-0.5 before:start-(--_guide) before:w-px before:bg-kg-ink/25",
                )}
                data-guides={guides || undefined}
                style={guides ? ({ "--_guide": `calc(${level - 1} * var(--_indent) + 0.75rem)` } as CSSProperties) : undefined}
              >
                {node.children?.length ? (
                  renderNodes(node.children, level + 1)
                ) : busy ? (
                  <li
                    role="none"
                    className="kg-tree-view__loading flex min-h-(--_row) items-center ps-(--_pad) text-kg-sm text-kg-fg-muted"
                    style={{ "--_level": level, "--_pad": `calc(${level} * var(--_indent) + 1.625rem)` } as CSSProperties}
                  >
                    {words.loading}
                  </li>
                ) : null}
              </ul>
            )}
          </li>
        )
      })

    return (
      <ul
        ref={ref}
        role="tree"
        aria-label={label}
        aria-multiselectable={selectionMode === "multiple" && !checkable ? true : undefined}
        className={cx(
          "kg-tree-view m-0 list-none p-0 text-[length:var(--_fs,var(--kg-text-base))] text-kg-fg select-none [--_indent:1.125rem] [--_row:1.875rem]",
          className,
        )}
        onKeyDown={onKeyDown}
        {...props}
      >
        {renderNodes(nodes, 1)}
      </ul>
    )
  },
)
TreeView.displayName = "TreeView"

