"use client"

import { type SetStateAction, useCallback, useRef, useState } from "react"
import { useEventCallback } from "./use-event-callback.js"

export interface ControllableStateOptions<T> {
  value?: T | undefined
  defaultValue: T
  onChange?: ((value: T) => void) | undefined
}

/** State that is owned by the parent when `value` is defined and by the component otherwise. */
export const useControllableState = <T>({
  value,
  defaultValue,
  onChange,
}: ControllableStateOptions<T>): readonly [T, (next: SetStateAction<T>) => void] => {
  const [internal, setInternal] = useState(defaultValue)
  const controlled = value !== undefined
  const current = controlled ? value : internal
  const latest = useRef(current)
  latest.current = current
  const emit = useEventCallback(onChange)

  const setValue = useCallback(
    (next: SetStateAction<T>) => {
      const resolved =
        typeof next === "function" ? (next as (prev: T) => T)(latest.current) : next
      if (Object.is(resolved, latest.current)) return
      latest.current = resolved
      if (!controlled) setInternal(resolved)
      emit(resolved)
    },
    [controlled, emit],
  )

  return [current, setValue] as const
}

hooks/use-dismiss.ts:
"use client"

import { type RefObject, useEffect } from "react"
import { useEventCallback } from "./use-event-callback.js"

export type DismissReason = "escape" | "outside"

export interface DismissOptions {
  enabled: boolean
  onDismiss: (reason: DismissReason) => void
  /** Elements that count as "inside": the layer itself and usually its trigger. */
  refs: RefObject<HTMLElement | null>[]
  escape?: boolean
  outside?: boolean
}

// Only the most recently opened layer answers Escape, so nested popovers close one at a time.
const layers: symbol[] = []

export const useDismiss = ({
  enabled,
  onDismiss,
  refs,
  escape = true,
  outside = true,
}: DismissOptions): void => {
  const dismiss = useEventCallback(onDismiss)
  const isInside = useEventCallback((target: Node) =>
    refs.some((ref) => ref.current?.contains(target)),
  )

  useEffect(() => {
    if (!enabled) return
    const id = Symbol("layer")
    layers.push(id)

    const handleKey = (event: KeyboardEvent) => {
      if (!escape || event.key !== "Escape" || layers.at(-1) !== id) return
      event.preventDefault()
      dismiss("escape")
    }
    const handlePointer = (event: PointerEvent) => {
      if (!outside) return
      const target = event.target as Node | null
      if (target && isInside(target)) return
      dismiss("outside")
    }

    document.addEventListener("keydown", handleKey)
    document.addEventListener("pointerdown", handlePointer, true)
    return () => {
      layers.splice(layers.indexOf(id), 1)
      document.removeEventListener("keydown", handleKey)
      document.removeEventListener("pointerdown", handlePointer, true)
    }
  }, [enabled, escape, outside, dismiss, isInside])
}

hooks/use-event-callback.ts:
"use client"

import { useCallback, useRef } from "react"
import { useIsomorphicLayoutEffect } from "./use-isomorphic-layout-effect.js"

/** A stable function identity that always calls the latest `callback`. */
export const useEventCallback = <Args extends unknown[], Result>(
  callback: ((...args: Args) => Result) | undefined,
): ((...args: Args) => Result | undefined) => {
  const ref = useRef(callback)
  useIsomorphicLayoutEffect(() => {
    ref.current = callback
  })
  return useCallback((...args: Args) => ref.current?.(...args), [])
}

hooks/use-floating.ts:
"use client"

import type { RefObject } from "react"
import { clamp } from "../utils/math.js"
import { useIsomorphicLayoutEffect } from "./use-isomorphic-layout-effect.js"

export type Side = "top" | "right" | "bottom" | "left"
export type Align = "start" | "center" | "end"

export interface FloatingOptions {
  open: boolean
  side?: Side
  align?: Align
  /** Gap between anchor and layer, in px. */
  offset?: number
  /** Minimum distance kept from the viewport edge, in px. */
  padding?: number
  /** Move to the opposite side when the preferred side lacks room. */
  flip?: boolean
  /** Make the layer at least as wide as the anchor. */
  matchWidth?: boolean
}

const opposite: Record<Side, Side> = {
  top: "bottom",
  bottom: "top",
  left: "right",
  right: "left",
}

/**
 * Positions a `position: fixed` layer next to its anchor and keeps it there through scroll and
 * resize. Writes `data-side`, `--kg-origin` (for scale-from-anchor animations) and
 * `--kg-anchor-width` directly on the layer, so it never triggers a React render.
 */
export const useFloating = (
  anchorRef: RefObject<HTMLElement | null>,
  floatingRef: RefObject<HTMLElement | null>,
  {
    open,
    side = "bottom",
    align = "center",
    offset = 8,
    padding = 8,
    flip = true,
    matchWidth = false,
  }: FloatingOptions,
): void => {
  useIsomorphicLayoutEffect(() => {
    const anchor = anchorRef.current
    const floating = floatingRef.current
    if (!open || !anchor || !floating) return
    let frame = 0

    const update = () => {
      const a = anchor.getBoundingClientRect()
      floating.style.setProperty("--kg-anchor-width", `${a.width}px`)
      if (matchWidth) floating.style.minWidth = `${a.width}px`
      // offset* ignores the entry transform, so the scale-in animation can't skew the measurement.
      const width = floating.offsetWidth
      const height = floating.offsetHeight
      const vw = document.documentElement.clientWidth
      const vh = window.innerHeight

      let resolved = side
      if (flip) {
        const room = {
          top: a.top,
          bottom: vh - a.bottom,
          left: a.left,
          right: vw - a.right,
        }
        const vertical = side === "top" || side === "bottom"
        const needed = (vertical ? height : width) + offset + padding
        if (room[side] < needed && room[opposite[side]] > room[side])
          resolved = opposite[side]
      }

      const vertical = resolved === "top" || resolved === "bottom"
      let x: number
      let y: number
      if (vertical) {
        y = resolved === "bottom" ? a.bottom + offset : a.top - offset - height
        x =
          align === "start"
            ? a.left
            : align === "end"
              ? a.right - width
              : a.left + a.width / 2 - width / 2
      } else {
        x = resolved === "right" ? a.right + offset : a.left - offset - width
        y =
          align === "start"
            ? a.top
            : align === "end"
              ? a.bottom - height
              : a.top + a.height / 2 - height / 2
      }
      x = clamp(x, padding, Math.max(padding, vw - width - padding))
      y = clamp(y, padding, Math.max(padding, vh - height - padding))

      floating.style.left = `${Math.round(x)}px`
      floating.style.top = `${Math.round(y)}px`
      floating.dataset.side = resolved

      const originX = clamp(a.left + a.width / 2 - x, 0, width)
      const originY = clamp(a.top + a.height / 2 - y, 0, height)
      floating.style.setProperty(
        "--kg-origin",
        vertical
          ? `${originX}px ${resolved === "bottom" ? 0 : height}px`
          : `${resolved === "right" ? 0 : width}px ${originY}px`,
      )
    }

    const schedule = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(update)
    }

    update()
    const observer = new ResizeObserver(schedule)
    observer.observe(anchor)
    observer.observe(floating)
    window.addEventListener("scroll", schedule, { capture: true, passive: true })
    window.addEventListener("resize", schedule)
    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
      window.removeEventListener("scroll", schedule, { capture: true })
      window.removeEventListener("resize", schedule)
    }
  }, [open, side, align, offset, padding, flip, matchWidth, anchorRef, floatingRef])
}

hooks/use-in-view.ts:
"use client"

import { type RefObject, useEffect, useState } from "react"

export interface InViewOptions {
  /** Stop observing after the first intersection. */
  once?: boolean
  /** Fraction of the element that must be visible. */
  amount?: number
  rootMargin?: string
}

export const useInView = (
  ref: RefObject<Element | null>,
  { once = true, amount = 0.15, rootMargin = "0px" }: InViewOptions = {},
): boolean => {
  const [inView, setInView] = useState(false)

  useEffect(() => {
    const node = ref.current
    if (!node) return
    if (typeof IntersectionObserver === "undefined") {
      setInView(true)
      return
    }
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry) return
        if (entry.isIntersecting) {
          setInView(true)
          if (once) observer.disconnect()
        } else if (!once) {
          setInView(false)
        }
      },
      { threshold: amount, rootMargin },
    )
    observer.observe(node)
    return () => observer.disconnect()
  }, [ref, once, amount, rootMargin])

  return inView
}

hooks/use-locale.ts:
"use client"

import { useSyncExternalStore } from "react"

/** What server renders and hydration agree on before the browser's own locale is known. */
export const SERVER_LOCALE = "en-US"

const subscribe = (notify: () => void) => {
  window.addEventListener("languagechange", notify)
  return () => window.removeEventListener("languagechange", notify)
}

/**
 * The locale to format with: the explicit one when given, otherwise the browser's. Server
 * render and hydration both use SERVER_LOCALE so their text matches; the browser locale takes
 * over right after hydration.
 */
export const useLocale = (locale?: string): string => {
  const detected = useSyncExternalStore(
    subscribe,
    () => navigator.language,
    () => SERVER_LOCALE,
  )
  return locale ?? detected
}

hooks/use-media-query.ts:
"use client"

import { useCallback, useSyncExternalStore } from "react"

export const useMediaQuery = (query: string, serverValue = false): boolean => {
  const subscribe = useCallback(
    (notify: () => void) => {
      const list = window.matchMedia(query)
      list.addEventListener("change", notify)
      return () => list.removeEventListener("change", notify)
    },
    [query],
  )
  return useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => serverValue,
  )
}

hooks/use-pointer-vars.ts:
"use client"

import { type RefObject, useEffect } from "react"
import { useEventCallback } from "./use-event-callback.js"

export interface PointerSample {
  /** Pixels from the element's top-left corner. */
  x: number
  y: number
  /** 0–1 across the element's width and height. */
  u: number
  v: number
  rect: DOMRect
}

export interface PointerVarsOptions {
  enabled?: boolean
  onMove?: (sample: PointerSample) => void
  onLeave?: () => void
}

/**
 * Writes `--kg-pointer-x/y` (px) and `--kg-pointer-u/v` (0–1) onto the element at most once
 * per frame, and toggles `data-pointer="in"`, so CSS can follow the cursor without re-renders.
 */
export const usePointerVars = (
  ref: RefObject<HTMLElement | null>,
  { enabled = true, onMove, onLeave }: PointerVarsOptions = {},
): void => {
  const move = useEventCallback(onMove)
  const leave = useEventCallback(onLeave)

  useEffect(() => {
    const node = ref.current
    if (!node || !enabled) return
    let frame = 0
    let last: PointerEvent | null = null

    const flush = () => {
      frame = 0
      if (!last) return
      const rect = node.getBoundingClientRect()
      const x = last.clientX - rect.left
      const y = last.clientY - rect.top
      const u = rect.width ? x / rect.width : 0
      const v = rect.height ? y / rect.height : 0
      node.style.setProperty("--kg-pointer-x", `${x}px`)
      node.style.setProperty("--kg-pointer-y", `${y}px`)
      node.style.setProperty("--kg-pointer-u", u.toFixed(4))
      node.style.setProperty("--kg-pointer-v", v.toFixed(4))
      move({ x, y, u, v, rect })
    }

    const handleMove = (event: PointerEvent) => {
      last = event
      if (!frame) frame = requestAnimationFrame(flush)
    }
    const handleEnter = () => {
      node.dataset.pointer = "in"
    }
    const handleLeave = () => {
      delete node.dataset.pointer
      leave()
    }

    node.addEventListener("pointermove", handleMove, { passive: true })
    node.addEventListener("pointerenter", handleEnter)
    node.addEventListener("pointerleave", handleLeave)
    return () => {
      cancelAnimationFrame(frame)
      node.removeEventListener("pointermove", handleMove)
      node.removeEventListener("pointerenter", handleEnter)
      node.removeEventListener("pointerleave", handleLeave)
    }
  }, [ref, enabled, move, leave])
}

hooks/use-presence.ts:
"use client"

import { type RefObject, useEffect, useRef, useState } from "react"
import { useIsomorphicLayoutEffect } from "./use-isomorphic-layout-effect.js"

export interface Presence<T extends HTMLElement> {
  ref: RefObject<T | null>
  /** Render the element while this is true: it stays true through the exit animation. */
  present: boolean
  /** Put on the element as `data-state` so CSS can choose the enter or exit animation. */
  state: "open" | "closed"
}

/** Keeps an element mounted until every CSS animation it runs after closing has finished. */
export const usePresence = <T extends HTMLElement = HTMLElement>(
  open: boolean,
): Presence<T> => {
  const ref = useRef<T | null>(null)
  const [mounted, setMounted] = useState(open)

  useIsomorphicLayoutEffect(() => {
    if (open) setMounted(true)
  }, [open])

  useEffect(() => {
    if (open || !mounted) return
    const node = ref.current
    // Infinite loops (spinners, shimmer) never finish, so waiting on them would never unmount.
    const animations = (node?.getAnimations?.({ subtree: true }) ?? []).filter(
      (animation) =>
        animation.effect?.getTiming().iterations !== Number.POSITIVE_INFINITY,
    )
    if (animations.length === 0) {
      setMounted(false)
      return
    }
    let cancelled = false
    void Promise.allSettled(animations.map((animation) => animation.finished)).then(
      () => {
        if (!cancelled) setMounted(false)
      },
    )
    return () => {
      cancelled = true
    }
  }, [open, mounted])

  return { ref, present: open || mounted, state: open ? "open" : "closed" }
}

hooks/use-reduced-motion.ts:
"use client"

import { useContext } from "react"
import { MotionContext } from "../provider/motion-context.js"
import { useMediaQuery } from "./use-media-query.js"

/** Live: flips when the OS setting changes, not just on mount. */
export const useReducedMotion = (): boolean => {
  const preference = useContext(MotionContext)
  const system = useMediaQuery("(prefers-reduced-motion: reduce)")
  return preference === "always" || system
}

hooks/use-roving-focus.ts:
"use client"

import { type KeyboardEvent, useCallback } from "react"

export interface RovingFocusOptions {
  orientation?: "horizontal" | "vertical" | "both"
  loop?: boolean
  /** Items are found by this selector inside the element that receives the handler. */
  selector?: string
}

export const ROVING_ITEM_SELECTOR =
  '[data-kg-item]:not([disabled]):not([aria-disabled="true"])'

/**
 * Returns an onKeyDown handler for a composite widget (tabs, radio group, toolbar, menu) that
 * moves focus between items with the arrow keys, Home and End, mirroring arrows in RTL.
 * The newly focused item is returned so callers can select on focus.
 */
export const useRovingFocus = ({
  orientation = "horizontal",
  loop = true,
  selector = ROVING_ITEM_SELECTOR,
}: RovingFocusOptions = {}) =>
  useCallback(
    (event: KeyboardEvent<HTMLElement>): HTMLElement | undefined => {
      const container = event.currentTarget
      const rtl = getComputedStyle(container).direction === "rtl"
      const deltas: Record<string, number> = {}
      if (orientation !== "vertical") {
        deltas.ArrowRight = rtl ? -1 : 1
        deltas.ArrowLeft = rtl ? 1 : -1
      }
      if (orientation !== "horizontal") {
        deltas.ArrowDown = 1
        deltas.ArrowUp = -1
      }

      const items = Array.from(container.querySelectorAll<HTMLElement>(selector))
      if (items.length === 0) return
      const current = items.indexOf(document.activeElement as HTMLElement)
      let next: number

      if (event.key === "Home") next = 0
      else if (event.key === "End") next = items.length - 1
      else if (event.key in deltas) {
        const delta = deltas[event.key] as number
        if (current === -1) next = delta > 0 ? 0 : items.length - 1
        else if (loop) next = (current + delta + items.length) % items.length
        else next = Math.min(Math.max(current + delta, 0), items.length - 1)
      } else return

      event.preventDefault()
      const item = items[next]
      item?.focus()
      return item
    },
    [orientation, loop, selector],
  )

hooks/use-scroll-lock.ts:
"use client"

import { useIsomorphicLayoutEffect } from "./use-isomorphic-layout-effect.js"

// Reference-counted so stacked modals unlock only when the last one closes.
let locks = 0
let restore: (() => void) | null = null

export const useScrollLock = (locked: boolean): void => {
  useIsomorphicLayoutEffect(() => {
    if (!locked) return
    if (locks++ === 0) {
      const root = document.documentElement
      const gutter = window.innerWidth - root.clientWidth
      const previous = {
        overflow: root.style.overflow,
        paddingRight: root.style.paddingRight,
      }
      root.style.overflow = "hidden"
      if (gutter > 0) root.style.paddingRight = `${gutter}px`
      restore = () => {
        root.style.overflow = previous.overflow
        root.style.paddingRight = previous.paddingRight
      }
    }
    return () => {
      if (--locks === 0) {
        restore?.()
        restore = null
      }
    }
  }, [locked])
}

hooks/use-spring.ts:
"use client"

import { useEffect, useMemo, useRef } from "react"
import { useEventCallback } from "./use-event-callback.js"
import { useReducedMotion } from "./use-reduced-motion.js"

export interface SpringConfig {
  stiffness?: number
  damping?: number
  mass?: number
  /** Settles once both distance and speed fall below this. */
  precision?: number
}

export interface Spring {
  get: () => number
  /** Animate toward `target`, keeping current velocity. */
  set: (target: number) => void
  /** Move to `value` immediately. */
  jump: (value: number) => void
  stop: () => void
}

const SUBSTEP = 1 / 240

export const createSpring = (
  initial: number,
  onUpdate: (value: number) => void,
  { stiffness = 170, damping = 26, mass = 1, precision = 0.01 }: SpringConfig = {},
): Spring => {
  let value = initial
  let target = initial
  let velocity = 0
  let frame = 0
  let last = 0

  const step = (now: number) => {
    // rAF timestamps can predate the performance.now() taken in set() (and use another clock in
    // some environments), so a non-positive delta falls back to one nominal frame.
    const elapsed = Math.min(Math.max((now - last) / 1000, 0), 0.064) || 1 / 60
    last = now
    const steps = Math.ceil(elapsed / SUBSTEP)
    const dt = elapsed / steps
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity
      velocity += (force / mass) * dt
      value += velocity * dt
    }
    if (Math.abs(value - target) < precision && Math.abs(velocity) < precision) {
      value = target
      velocity = 0
      frame = 0
      onUpdate(value)
      return
    }
    onUpdate(value)
    frame = requestAnimationFrame(step)
  }

  const stop = () => {
    cancelAnimationFrame(frame)
    frame = 0
  }

  return {
    get: () => value,
    set: (next) => {
      target = next
      if (frame) return
      last = performance.now()
      frame = requestAnimationFrame(step)
    },
    jump: (next) => {
      stop()
      value = target = next
      velocity = 0
      onUpdate(value)
    },
    stop,
  }
}

/**
 * A rAF-driven spring that reports through `onUpdate` instead of state, so per-frame values can be
 * written straight to styles. Under reduced motion `set` jumps to the target.
 */
export const useSpring = (
  initial: number,
  onUpdate: (value: number) => void,
  config?: SpringConfig,
): Spring => {
  const reduced = useReducedMotion()
  const update = useEventCallback(onUpdate)
  const spring = useRef<Spring | null>(null)
  spring.current ??= createSpring(initial, (value) => update(value), config)

  useEffect(() => () => spring.current?.stop(), [])

  return useMemo(() => {
    const inner = spring.current as Spring
    return { ...inner, set: reduced ? inner.jump : inner.set }
  }, [reduced])
}

primitives/layer.tsx:
"use client"

import { forwardRef, type HTMLAttributes, useRef } from "react"
import { useIsomorphicLayoutEffect } from "../hooks/use-isomorphic-layout-effect.js"
import { useComposedRefs } from "../utils/compose-refs.js"
import { cx } from "../utils/cx.js"
import { supportsPopover } from "../utils/env.js"

export type LayerProps = HTMLAttributes<HTMLDivElement>

/**
 * A floating surface promoted to the browser top layer through the Popover API. It escapes
 * `overflow` clipping and stacking contexts without a portal, so it keeps inheriting theme
 * variables from where it is rendered. Older browsers fall back to `position: fixed` + z-index.
 */
export const Layer = forwardRef<HTMLDivElement, LayerProps>(
  ({ className, ...props }, forwardedRef) => {
    const local = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(local, forwardedRef)

    useIsomorphicLayoutEffect(() => {
      const node = local.current
      if (!node || !supportsPopover()) return
      node.showPopover()
      return () => {
        if (node.matches(":popover-open")) node.hidePopover()
      }
    }, [])

    return (
      <div
        ref={ref}
        popover="manual"
        className={cx("kg-layer", className)}
        {...props}
      />
    )
  },
)

Layer.displayName = "Layer"

primitives/slot.tsx:
import {
  Children,
  cloneElement,
  forwardRef,
  type HTMLAttributes,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  version,
} from "react"
import { composeRefs } from "../utils/compose-refs.js"
import { mergeProps } from "../utils/merge-props.js"

const major = Number.parseInt(version, 10)

// React 19 moved `ref` onto props; reading `element.ref` there logs a deprecation warning.
const getElementRef = (element: ReactElement): Ref<unknown> | undefined =>
  major >= 19
    ? (element.props as { ref?: Ref<unknown> }).ref
    : (element as unknown as { ref?: Ref<unknown> }).ref

export interface SlotProps extends HTMLAttributes<HTMLElement> {
  children?: ReactNode
}

/** Renders its only child with the slot's props merged in. Powers every `asChild` prop. */
export const Slot = forwardRef<HTMLElement, SlotProps>(
  ({ children, ...props }, ref) => {
    const child = Children.only(children)
    if (!isValidElement(child)) return null
    return cloneElement(child, {
      ...mergeProps(props, child.props as Record<string, unknown>),
      ref: composeRefs(ref, getElementRef(child)),
    } as Record<string, unknown>)
  },
)

Slot.displayName = "Slot"

