@layer kg.base {
  [class^="kg-"],
  [class*=" kg-"],
  [class^="kg-"]::before,
  [class*=" kg-"]::before,
  [class^="kg-"]::after,
  [class*=" kg-"]::after {
    box-sizing: border-box;
  }

  .kg-visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  .kg-tabular {
    font-variant-numeric: tabular-nums;
  }

  /* Neutralises the UA [popover] box so Layer only contributes top-layer promotion. */
  .kg-layer {
    position: fixed;
    inset: auto;
    width: max-content;
    height: auto;
    max-width: calc(100vw - 1rem);
    margin: 0;
    padding: 0;
    overflow: visible;
    color: inherit;
    background: none;
    border: 0;
    z-index: var(--kg-z-popover);
  }

  @keyframes kg-fade-in {
    from {
      opacity: 0;
    }
  }

  @keyframes kg-fade-out {
    to {
      opacity: 0;
    }
  }

  @keyframes kg-pop-in {
    from {
      opacity: 0;
      transform: translateY(var(--kg-enter-y, 4px)) scale(0.96);
    }
  }

  @keyframes kg-pop-out {
    to {
      opacity: 0;
      transform: translateY(var(--kg-enter-y, 4px)) scale(0.97);
